n\":10,\"watermarkOpacity\":60,\"watermarkApplyScope\":\"all\",\"watermarkEnableBackup\":true,\"watermarkApplyToExistingImages\":\"\",\"watermarkRemoveWatermark\":\"\"},\"exif\":{\"enableExif\":false,\"exifCamera\":true,\"exifLens\":true,\"exifShutterSpeed\":true,\"exifAperture\":true,\"exifFocalLength\":true,\"exifIso\":true,\"exifDate\":true},\"licensing\":{\"imageLicensing\":\"none\",\"author\":\"\",\"company\":\"\",\"displayWithDescription\":false,\"showOnLightbox\":true},\"comments\":{\"commentStatus\":false,\"toggleComments\":true,\"startCollapsed\":false},\"proofing\":{\"imageProofing\":false,\"minSelection\":0,\"maxSelection\":0,\"notificationEmail\":\"\",\"loginRejectionNotice\":\"\",\"showLoginLink\":true,\"expireRejectionNotice\":\"\",\"expireLinkToPage\":\"0\",\"expireLinkToPageUrl\":\"\"},\"instagram\":{\"syncWithInstagram\":false},\"exportImport\":[]}'),
