INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(240, 1, '2026-10-26 17:17:53', '2026-10-26 11:47:53', '    <article>\r\n\r\n        <!-- =========================================================\r\n             HERO SHOWCASE SECTION\r\n        ========================================================== -->\r\n        <section class=\"ukt-hero-showcase\">\r\n            <div class=\"ukt-hero-slide-layout\">\r\n                <div class=\"container-fluid\">\r\n                    <div class=\"row g-0 align-items-stretch\">\r\n\r\n                        <!-- LEFT CONTENT AREA -->\r\n                        <div class=\"col-lg-5 d-flex align-items-center\">\r\n                            <div class=\"ukt-hero-copy-zone\">\r\n                                <div class=\"ukt-hero-left-decoration\"></div>\r\n\r\n                                <div class=\"ukt-hero-slide-kicker\">\r\n                                    Ancient Vedic Fire Science &amp; Homa Therapy\r\n                                </div>\r\n\r\n                                <h1 class=\"ukt-hero-main-title\">\r\n                                    Karnataka Agnihotra <span>Spectacular</span>\r\n                                </h1>\r\n\r\n                                <div class=\"ukt-hero-script-line\">\r\n                                    Purifying Atmosphere, Mind &amp; Spirit\r\n                                </div>\r\n\r\n                                <p class=\"ukt-hero-description\">\r\n                                    The Agnihotra is an ancient Vedic fire ritual rooted in the Yajurveda. Performed at\r\n                                    sunrise and sunset with authentic copper pyramid vessels, it restores cosmic harmony\r\n                                    (ṛta), heals the surrounding atmosphere, and cultivates profound spiritual\r\n                                    elevation.\r\n                                </p>\r\n\r\n                                <div class=\"ukt-hero-action-row\">\r\n                                    <a href=\"#vedic-sources\" class=\"ukt-hero-primary-action\">\r\n                                        Explore Vedic Roots\r\n                                        <i class=\"bi bi-arrow-down\"></i>\r\n                                    </a>\r\n\r\n                                    <a href=\"http://localhost/universal-knowledge-trust-wordpress/agnihotra-procedures\" class=\"ukt-hero-secondary-action\">\r\n                                        <i class=\"bi bi-fire text-warning me-1\"></i> Ritual Procedure\r\n                                    </a>\r\n                                </div>\r\n\r\n                            </div>\r\n                        </div>\r\n\r\n                        <!-- RIGHT IMAGE AREA -->\r\n                        <div class=\"col-lg-7\">\r\n                            <div class=\"ukt-hero-visual-zone\">\r\n                                <div class=\"ukt-hero-image-frame\">\r\n                                    <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/karnataka-agnihotra-banner.jpg\"\r\n                                        alt=\"Karnataka Agnihotra Spectacular - Vedic Fire Ritual by Universal Knowledge Trust\"\r\n                                        title=\"Karnataka Agnihotra Spectacular\" loading=\"eager\">\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </section>\r\n\r\n        <!-- =========================================================\r\n             SECTION: KARNATAKA AGNIHOTRA SPECTACULAR - WORLD AGNIHOTRA DAY 2025\r\n        ========================================================== -->\r\n        <section class=\"py-5 ukt-agnihotra-record-section\" id=\"world-agnihotra-day-2025\">\r\n            <div class=\"container py-lg-2\">\r\n                <div class=\"row align-items-center g-4 g-lg-5\">\r\n\r\n                    <!-- LEFT COLUMN: CAROUSEL WITH SLIDING EFFECT -->\r\n                    <div class=\"col-lg-6 col-md-12\">\r\n                        <div class=\"pe-lg-3\">\r\n                            <div class=\"ukt-agnihotra-carousel-frame\">\r\n\r\n                                <!-- BOOTSTRAP SLIDING CAROUSEL -->\r\n                                <div id=\"agnihotraWorldRecordCarousel\" class=\"carousel slide\" data-bs-ride=\"carousel\"\r\n                                    data-bs-interval=\"4500\">\r\n\r\n                                    <!-- INDICATORS -->\r\n                                    <div class=\"carousel-indicators mb-1\">\r\n                                        <button type=\"button\" data-bs-target=\"#agnihotraWorldRecordCarousel\"\r\n                                            data-bs-slide-to=\"0\" class=\"active ukt-carousel-indicator-gold\"\r\n                                            aria-current=\"true\" aria-label=\"Slide 1\"></button>\r\n                                        <button type=\"button\" data-bs-target=\"#agnihotraWorldRecordCarousel\"\r\n                                            data-bs-slide-to=\"1\" class=\"ukt-carousel-indicator-gold\"\r\n                                            aria-label=\"Slide 2\"></button>\r\n                                    </div>\r\n\r\n                                    <!-- SLIDES (FLUSH FIT WITHOUT VERTICAL GAP) -->\r\n                                    <div class=\"carousel-inner ukt-carousel-inner-rounded\">\r\n                                        <div class=\"carousel-item active\">\r\n                                            <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-world-record/agnihotra-world-record-1.jpg\"\r\n                                                alt=\"Karnataka Agnihotra Spectacular - World Agnihotra Day 2025 Dharwad\"\r\n                                                title=\"Karnataka Agnihotra Spectacular 2025\"\r\n                                                class=\"d-block w-100 img-fluid ukt-agnihotra-carousel-img\">\r\n                                        </div>\r\n                                        <div class=\"carousel-item\">\r\n                                            <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-world-record/agnihotra-world-record-2.jpg\"\r\n                                                alt=\"World Agnihotra Day 2025 World Record Attempt\"\r\n                                                title=\"World Agnihotra Day 2025 Guide\"\r\n                                                class=\"d-block w-100 img-fluid ukt-agnihotra-carousel-img\">\r\n                                        </div>\r\n                                    </div>\r\n\r\n                                    <!-- CONTROLS -->\r\n                                    <button class=\"carousel-control-prev ukt-carousel-control-narrow\" type=\"button\"\r\n                                        data-bs-target=\"#agnihotraWorldRecordCarousel\" data-bs-slide=\"prev\">\r\n                                        <span class=\"carousel-control-prev-icon ukt-carousel-control-icon-circle\"\r\n                                            aria-hidden=\"true\"></span>\r\n                                        <span class=\"visually-hidden\">Previous</span>\r\n                                    </button>\r\n                                    <button class=\"carousel-control-next ukt-carousel-control-narrow\" type=\"button\"\r\n                                        data-bs-target=\"#agnihotraWorldRecordCarousel\" data-bs-slide=\"next\">\r\n                                        <span class=\"carousel-control-next-icon ukt-carousel-control-icon-circle\"\r\n                                            aria-hidden=\"true\"></span>\r\n                                        <span class=\"visually-hidden\">Next</span>\r\n                                    </button>\r\n\r\n                                </div><!-- /#agnihotraWorldRecordCarousel -->\r\n\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- RIGHT COLUMN: CONTENT -->\r\n                    <div class=\"col-lg-6 col-md-12\">\r\n                        <div class=\"ps-lg-2\">\r\n                            <div class=\"ukt-section-eyebrow text-start m-0 mb-1\">\r\n                                <span></span>\r\n                                WORLD AGNIHOTRA DAY 2025\r\n                                <span></span>\r\n                            </div>\r\n                            <h2 class=\"ukt-section-main-title ukt-section-title-clamp-md text-start mb-2\">\r\n                                Karnataka Agnihotra Spectacular <span> – World record Agnihotra Spectacular 2025\r\n                                    🔥</span>\r\n                            </h2>\r\n                            <div class=\"ukt-section-heading-design m-0 mb-2 justify-content-start\">\r\n                                <span></span>\r\n                                <i class=\"bi bi-fire\"></i>\r\n                                <span></span>\r\n                            </div>\r\n\r\n                            <p class=\"ukt-agnihotra-record-text\">\r\n                                We wish for you to join us on this journey, and hence, this special invitation is\r\n                                extended to you.\r\n                            </p>\r\n\r\n                            <p class=\"ukt-agnihotra-record-text-sm\">\r\n                                On <strong>13th April 2025, at Dharwad</strong>,<br>\r\n                                Please join us in hosting a grand Agnihotra world record event with <strong>10,000+\r\n                                    participants</strong>, who will do Agnihotra at a single location.<br>\r\n                                This is been organized by <strong>Gram Vikas Society</strong> and <strong>Universal\r\n                                    Knowledge Trust</strong>.\r\n                            </p>\r\n\r\n                            <p class=\"ukt-agnihotra-record-text-sm\">\r\n                                Let’s come together to experience this beautiful ancient practice that brings peace,\r\n                                harmony, and positivity to our lives and the world.\r\n                            </p>\r\n\r\n                            <!-- CALLOUT: GATHERING & SPARK -->\r\n                            <div class=\"ukt-agnihotra-gratitude-box mb-3\">\r\n                                <p class=\"ukt-agnihotra-gratitude-tagline ukt-agnihotra-tagline-normal mb-1\">\r\n                                    ✨ Be a part of this incredible gathering and become an Agnihotri! ✨\r\n                                </p>\r\n                                <p class=\"ukt-agnihotra-gratitude-text mb-0\">\r\n                                    Let’s light the fire of transformation and unity.\r\n                                </p>\r\n                            </div>\r\n\r\n                            <p class=\"ukt-agnihotra-record-text-sm mb-2\">\r\n                                📅 <strong>Event Date:</strong> 13th April 2025 &nbsp;&nbsp; 📍\r\n                                <strong>Location:</strong> Dharwad\r\n                            </p>\r\n\r\n                            <p class=\"ukt-agnihotra-record-text ukt-agnihotra-record-highlight fw-semibold mb-3\">\r\n                                Together, let’s make a difference! 🙏\r\n                            </p>\r\n\r\n                            <!-- EVENT DETAILS CARD -->\r\n                            <div class=\"ukt-agnihotra-event-card mb-3\">\r\n                                <h4 class=\"ukt-agnihotra-event-card-title fw-bold mb-1\">\r\n                                    KARNATAKA AGNIHOTRA SPECTACULAR,\r\n                                </h4>\r\n                                <p class=\"ukt-agnihotra-event-card-desc mb-2\">\r\n                                    an initiative by GVS powered by UKT to celebrate<br>\r\n                                    <strong>WORLD AGNIHOTRA DAY on 13th April 2025.</strong>\r\n                                </p>\r\n                                <p class=\"ukt-agnihotra-event-card-stat mb-1 fw-bold\">\r\n                                    11,111+ Agnihotris, 11,111+ Locations, 111+ Consecutive Days of Agnihotra\r\n                                </p>\r\n                                <p class=\"ukt-agnihotra-event-card-record mb-0 fw-bold\">\r\n                                    Leading to CREATION OF WORLD 🌍 RECORD.\r\n                                </p>\r\n                            </div>\r\n\r\n                            <p class=\"ukt-agnihotra-record-text-sm mb-2\">\r\n                                If you are interested in join this event and ready to do Agnihotra in your\r\n                                house/workspace, you can register\r\n                            </p>\r\n\r\n                            <div class=\"ukt-agnihotra-free-kit-badge mb-3\">\r\n                                🎁 First Registered 11,111 Residents of Karnataka to get FREE START UP AGNIHOTRA KIT\r\n                            </div>\r\n\r\n                            <!-- GRATITUDE & SIGN-OFF BANNER -->\r\n                            <div class=\"ukt-agnihotra-gratitude-box\">\r\n                                <p class=\"ukt-agnihotra-gratitude-text mb-0\">\r\n                                    Thanks, Regards, Team GVS &amp; UKT\r\n                                </p>\r\n                            </div>\r\n\r\n                        </div>\r\n                    </div>\r\n\r\n                </div>\r\n            </div>\r\n        </section>\r\n\r\n        <!-- =========================================================\r\n             KEY PILLARS SUMMARY BAR (4 HIGHLIGHTS)\r\n        ========================================================== -->\r\n        <!-- <section class=\"ukt-agni-stats-bar\">\r\n            <div class=\"container\">\r\n                <div class=\"row g-3\">\r\n                    <div class=\"col-xl-3 col-lg-6 col-md-6 col-12\">\r\n                        <div class=\"ukt-agni-stat-item\">\r\n                            <div class=\"ukt-agni-stat-icon\">\r\n                                <i class=\"bi bi-sunrise\"></i>\r\n                            </div>\r\n                            <div class=\"ukt-agni-stat-content\">\r\n                                <h4>Solar Biorhythms</h4>\r\n                                <p>Performed at the exact moments of sunrise and sunset to harness cosmic bio-energies.</p>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"col-xl-3 col-lg-6 col-md-6 col-12\">\r\n                        <div class=\"ukt-agni-stat-item\">\r\n                            <div class=\"ukt-agni-stat-icon\">\r\n                                <i class=\"bi bi-book\"></i>\r\n                            </div>\r\n                            <div class=\"ukt-agni-stat-content\">\r\n                                <h4>Yajurvedic Origin</h4>\r\n                                <p>Rooted in Taittiriya Samhita, Shukla Yajurveda, and Shatapatha Brahmana.</p>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"col-xl-3 col-lg-6 col-md-6 col-12\">\r\n                        <div class=\"ukt-agni-stat-item\">\r\n                            <div class=\"ukt-agni-stat-icon\">\r\n                                <i class=\"bi bi-fire\"></i>\r\n                            </div>\r\n                            <div class=\"ukt-agni-stat-content\">\r\n                                <h4>Three Sacred Fires</h4>\r\n                                <p>Preserved across millennia through Gārhapatya, Dakṣiṇāgni, and Āhavanīya.</p>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"col-xl-3 col-lg-6 col-md-6 col-12\">\r\n                        <div class=\"ukt-agni-stat-item\">\r\n                            <div class=\"ukt-agni-stat-icon\">\r\n                                <i class=\"bi bi-tree\"></i>\r\n                            </div>\r\n                            <div class=\"ukt-agni-stat-content\">\r\n                                <h4>Atmospheric Healing</h4>\r\n                                <p>Scientifically recognized Homa therapy for ecological and biological rejuvenation.</p>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        <!-- =========================================================\r\n             SECTION 1: PHILOSOPHY & ORIGIN OF AGNIHOTRA\r\n        ========================================================== -->\r\n        <section class=\"py-4 py-lg-5 ukt-section-bg-white\">\r\n            <div class=\"container py-lg-2\">\r\n                <div class=\"row align-items-center justify-content-between g-3 g-lg-4 mb-4\">\r\n\r\n                    <div class=\"col-lg-7 col-md-12\">\r\n                        <div class=\"pe-0 pe-lg-3\">\r\n                            <div class=\"ukt-section-eyebrow text-start m-0 mb-2\">\r\n                                <span></span>\r\n                                SACRED VEDIC ROOTS\r\n                                <span></span>\r\n                            </div>\r\n                            <h2 class=\"ukt-section-main-title mb-3\">\r\n                                The Sacred Fire Offering: <span>Agnihotra</span>\r\n                            </h2>\r\n                            <div class=\"ukt-section-heading-design m-0 mb-3 justify-content-start\">\r\n                                <span></span>\r\n                                <i class=\"bi bi-flower1\"></i>\r\n                                <span></span>\r\n                            </div>\r\n\r\n                            <p class=\"ukt-agnihotra-intro-text\">\r\n                                The <strong>Agnihotri practice</strong>, also known as <strong>Agnihotra</strong>, is an\r\n                                ancient Vedic fire ritual that has its origins in the early Vedic period of the Indian\r\n                                subcontinent. It is one of the oldest and most sacred rituals in Hinduism, deeply rooted\r\n                                in the Vedic tradition.\r\n                            </p>\r\n\r\n                            <p class=\"ukt-agnihotra-intro-text-last\">\r\n                                The Agnihotri practice originates from the Vedic period of ancient India and is closely\r\n                                linked to Vedic rituals and the Agnihotra fire sacrifice. The term\r\n                                <strong>Agnihotri</strong> refers to a Brahmin who performs the Agnihotra ritual daily\r\n                                and maintains the sacred fire (Agni) as part of their spiritual and priestly duties.\r\n                            </p>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div\r\n                        class=\"col-lg-5 col-md-12 d-flex align-items-center justify-content-center justify-content-lg-center\">\r\n                        <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-img-191x300.jpg\"\r\n                            alt=\"Karnataka Agnihotra Spectacular - Universal Knowledge Trust\"\r\n                            class=\"ukt-agnihotra-poster-img\">\r\n                    </div>\r\n\r\n                </div>\r\n\r\n                <!-- ORIGINS OF THE AGNIHOTRI PRACTICE -->\r\n                <div class=\"ukt-practical-unified-card mt-3 mb-4 text-start\">\r\n                    <div class=\"ukt-practical-accent-bar\"></div>\r\n                    <h3 class=\"ukt-practical-title mb-3\">\r\n                        <i class=\"bi bi-fire ukt-icon-gold\"></i> Origins of the Agnihotri Practice:\r\n                    </h3>\r\n\r\n                    <!-- 1. Vedic Foundations -->\r\n                    <div class=\"mb-3\">\r\n                        <h4 class=\"ukt-agnihotri-origin-subtitle fw-bold mb-2\">\r\n                            1. Vedic Foundations (c. 1500–500 BCE):\r\n                        </h4>\r\n                        <ul class=\"ukt-practical-list-nomargin\">\r\n                            <li class=\"ukt-practical-list-item\">\r\n                                <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                                <div>The Agnihotra is a fire ritual mentioned in the Rigveda, Yajurveda, and\r\n                                    Atharvaveda.</div>\r\n                            </li>\r\n                            <li class=\"ukt-practical-list-item\">\r\n                                <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                                <div>It was performed at sunrise and sunset to honor Agni, the fire deity, and maintain\r\n                                    cosmic balance.</div>\r\n                            </li>\r\n                            <li class=\"ukt-practical-list-item\">\r\n                                <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                                <div>The Agnihotri was a specialized priest responsible for conducting these rituals.\r\n                                </div>\r\n                            </li>\r\n                        </ul>\r\n                    </div>\r\n\r\n                    <!-- 2. Brahmanical Tradition -->\r\n                    <div class=\"mb-3\">\r\n                        <h4 class=\"ukt-agnihotri-origin-subtitle fw-bold mb-2\">\r\n                            2. Brahmanical Tradition:\r\n                        </h4>\r\n                        <ul class=\"ukt-practical-list-nomargin\">\r\n                            <li class=\"ukt-practical-list-item\">\r\n                                <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                                <div>The Agnihotris were part of the Shrauta tradition, which involved elaborate fire\r\n                                    sacrifices (Yajnas).</div>\r\n                            </li>\r\n                            <li class=\"ukt-practical-list-item\">\r\n                                <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                                <div>They played a significant role in royal and temple rituals, ensuring the continuity\r\n                                    of Vedic traditions.</div>\r\n                            </li>\r\n                        </ul>\r\n                    </div>\r\n\r\n                    <!-- 3. Smritis and Dharmashastra Influence -->\r\n                    <div class=\"mb-3\">\r\n                        <h4 class=\"ukt-agnihotri-origin-subtitle fw-bold mb-2\">\r\n                            3. Smritis and Dharmashastra Influence (c. 500 BCE – 500 CE):\r\n                        </h4>\r\n                        <ul class=\"ukt-practical-list-nomargin\">\r\n                            <li class=\"ukt-practical-list-item\">\r\n                                <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                                <div>Texts like the Manusmriti and Baudhayana Dharma Sutra emphasized the importance of\r\n                                    Agnihotra in daily life.</div>\r\n                            </li>\r\n                            <li class=\"ukt-practical-list-item\">\r\n                                <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                                <div>The practice was considered a compulsory duty (Nitya Karma) for Brahmins devoted to\r\n                                    Vedic rituals.</div>\r\n                            </li>\r\n                        </ul>\r\n                    </div>\r\n\r\n                    <!-- 4. Medieval and Modern Continuation -->\r\n                    <div class=\"mb-0\">\r\n                        <h4 class=\"ukt-agnihotri-origin-subtitle fw-bold mb-2\">\r\n                            4. Medieval and Modern Continuation:\r\n                        </h4>\r\n                        <ul class=\"ukt-practical-list-nomargin\">\r\n                            <li class=\"ukt-practical-list-item\">\r\n                                <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                                <div>Though large-scale Yajnas declined with the rise of Bhakti and temple-based\r\n                                    worship, some Brahmin families continued the Agnihotri tradition.</div>\r\n                            </li>\r\n                            <li class=\"ukt-practical-list-item\">\r\n                                <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                                <div>Even today, certain Brahmin sects in India, such as Namboodiri Brahmins of Kerala\r\n                                    and Maharashtrian Brahmins, maintain Agnihotra practices.</div>\r\n                            </li>\r\n                        </ul>\r\n                    </div>\r\n\r\n                </div>\r\n\r\n                <!-- CURRENT STATUS OF AGNIHOTRI PRACTICE -->\r\n                <div class=\"ukt-agnihotra-gratitude-box mb-3 p-3 text-start\">\r\n                    <h3 class=\"ukt-practical-title ukt-agnihotri-status-title mb-2\">\r\n                        <i class=\"bi bi-geo-alt-fill ukt-icon-gold\"></i> Current Status of Agnihotri Practice:\r\n                    </h3>\r\n                    <ul class=\"ukt-practical-list-nomargin mb-3\">\r\n                        <li class=\"ukt-practical-list-item\">\r\n                            <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                            <div>Some traditional Agnihotri families still maintain the sacred fire and conduct\r\n                                Agnihotra as part of their daily worship.</div>\r\n                        </li>\r\n                        <li class=\"ukt-practical-list-item\">\r\n                            <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                            <div>The practice has also seen a revival in spiritual and environmental movements, with\r\n                                many promoting Agnihotra for its claimed benefits in purifying air and the atmosphere.\r\n                            </div>\r\n                        </li>\r\n                    </ul>\r\n                    <p class=\"ukt-agnihotri-inquiry-text m-0 text-muted fst-italic\">\r\n                        Would you like details on any specific aspect of the Agnihotri practice?\r\n                    </p>\r\n                </div>\r\n            </div>\r\n        </section>\r\n\r\n        <!-- =========================================================\r\n             SECTION 2: PRIMARY VEDIC SOURCES & AUTHENTIC TEXTS\r\n        ========================================================== -->\r\n        <section class=\"py-5 ukt-vedic-sources-section\" id=\"vedic-sources\">\r\n            <div class=\"container py-lg-4\">\r\n\r\n                <!-- SECTION HEADER -->\r\n                <div class=\"ukt-section-header\">\r\n                    <div class=\"ukt-section-eyebrow\">\r\n                        <span></span>\r\n                        CANONICAL SCRIPTURES\r\n                        <span></span>\r\n                    </div>\r\n                    <h2 class=\"ukt-section-main-title\">\r\n                        Primary <span>Vedic Sources</span>\r\n                    </h2>\r\n                    <div class=\"ukt-section-heading-design\">\r\n                        <span></span>\r\n                        <i class=\"bi bi-flower1\"></i>\r\n                        <span></span>\r\n                    </div>\r\n                    <p class=\"ukt-section-lead-text\">\r\n                        The Agni Hotra (or Agnihotra) is an ancient Vedic fire ritual rooted in the Yajurveda. To engage\r\n                        with authentic sources for this practice, consider the following structured approach:\r\n                    </p>\r\n                </div>\r\n\r\n                <div class=\"row justify-content-center g-4\">\r\n\r\n                    <!-- SOURCE 1: YAJURVEDA -->\r\n                    <div class=\"col-lg-4 col-md-6 col-12\">\r\n                        <div class=\"ukt-source-card\">\r\n                            <div class=\"ukt-source-header\">\r\n                                <div class=\"ukt-source-icon-badge\">\r\n                                    <i class=\"bi bi-journal-richtext\"></i>\r\n                                </div>\r\n                                <span class=\"ukt-source-tag\">Veda Samhita</span>\r\n                            </div>\r\n                            <h3 class=\"ukt-source-title\">1. Yajurveda</h3>\r\n                            <ul class=\"ukt-source-texts-list\">\r\n                                <li>\r\n                                    <i class=\"bi bi-bookmark-check\"></i>\r\n                                    <span><strong>Taittiriya Samhita:</strong> Central text detailing fire rituals. The\r\n                                        Agni Hotra is described here, especially in sections related to daily offerings\r\n                                        (sandhyā).</span>\r\n                                </li>\r\n                            </ul>\r\n                            <div class=\"ukt-source-translation-pill\">\r\n                                <strong>Translation:</strong> “The Yajurveda Taittiriya Samhita” by R.L. Kashyap\r\n                                (Sanskrit-English, 2020) provides accessible insights.\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- SOURCE 2: BRAHMANAS -->\r\n                    <div class=\"col-lg-4 col-md-6 col-12\">\r\n                        <div class=\"ukt-source-card\">\r\n                            <div class=\"ukt-source-header\">\r\n                                <div class=\"ukt-source-icon-badge\">\r\n                                    <i class=\"bi bi-layers\"></i>\r\n                                </div>\r\n                                <span class=\"ukt-source-tag\">Brahmana Texts</span>\r\n                            </div>\r\n                            <h3 class=\"ukt-source-title\">2. Brahmanas</h3>\r\n                            <ul class=\"ukt-source-texts-list\">\r\n                                <li>\r\n                                    <i class=\"bi bi-bookmark-check\"></i>\r\n                                    <span><strong>Shatapatha Brahmana:</strong> Elaborates on ritual significance. Book\r\n                                        2 discusses Agni Hotra’s symbolism.</span>\r\n                                </li>\r\n                            </ul>\r\n                            <div class=\"ukt-source-translation-pill\">\r\n                                <strong>Translation:</strong> “The Satapatha Brahmana” by Julius Eggeling (Sacred Books\r\n                                of the East series, 1882).\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- SOURCE 3: GRIHYA SUTRAS -->\r\n                    <div class=\"col-lg-4 col-md-6 col-12\">\r\n                        <div class=\"ukt-source-card\">\r\n                            <div class=\"ukt-source-header\">\r\n                                <div class=\"ukt-source-icon-badge\">\r\n                                    <i class=\"bi bi-house-door\"></i>\r\n                                </div>\r\n                                <span class=\"ukt-source-tag\">Grihya Sutras</span>\r\n                            </div>\r\n                            <h3 class=\"ukt-source-title\">3. Grihya Sutras</h3>\r\n                            <ul class=\"ukt-source-texts-list\">\r\n                                <li>\r\n                                    <i class=\"bi bi-bookmark-check\"></i>\r\n                                    <span><strong>Apastamba Grihya Sutra:</strong> Outlines domestic rituals, including\r\n                                        Agni Hotra procedures.</span>\r\n                                </li>\r\n                                <li>\r\n                                    <i class=\"bi bi-bookmark-check\"></i>\r\n                                    <span><strong>Ashvalayana Grihya Sutra:</strong> Another key text for householder\r\n                                        practices.</span>\r\n                                </li>\r\n                            </ul>\r\n                            <div class=\"ukt-source-translation-pill\">\r\n                                <strong>Translation:</strong> “Hindu Domestic Rituals” by H. Oldenberg (1892).\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n        </section>\r\n\r\n        <!-- =========================================================\r\n             SECTION 3: ROLE OF THE AGNIHOTRI & THREE SACRED FIRES\r\n        ========================================================== -->\r\n        <section class=\"py-5 ukt-agnihotri-role-section\">\r\n            <div class=\"container py-lg-4\">\r\n\r\n                <!-- SECTION HEADER -->\r\n                <div class=\"ukt-section-header\">\r\n                    <div class=\"ukt-section-eyebrow\">\r\n                        <span></span>\r\n                        VEDIC TRADITION\r\n                        <span></span>\r\n                    </div>\r\n                    <h2 class=\"ukt-section-main-title\">\r\n                        Role of the <span>Agnihotri</span>\r\n                    </h2>\r\n                    <div class=\"ukt-section-heading-design\">\r\n                        <span></span>\r\n                        <i class=\"bi bi-flower1\"></i>\r\n                        <span></span>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- CONTENT: SINGLE UNIFIED CARD -->\r\n                <div class=\"ukt-agnihotri-role-card\">\r\n\r\n                    <!-- TOP ACCENT BAR -->\r\n                    <div class=\"ukt-agnihotri-role-accent\"></div>\r\n\r\n                    <!-- INNER PADDING WRAP -->\r\n                    <div class=\"ukt-agnihotri-role-body\">\r\n\r\n                        <!-- HEREDITARY DUTY -->\r\n                        <div class=\"ukt-agnihotri-duty-block\">\r\n                            <div class=\"ukt-agnihotri-label-amber\">\r\n                                <i class=\"bi bi-bookmark-star-fill\"></i>\r\n                                HEREDITARY DUTY\r\n                            </div>\r\n                            <p class=\"ukt-agnihotri-prose\">\r\n                                The term <strong class=\"ukt-text-highlight-teal\">Agnihotri</strong> refers to Brahmin\r\n                                families\r\n                                who were entrusted with the responsibility of performing the Agnihotra ritual. These\r\n                                families belonged to specific <strong class=\"ukt-text-highlight-teal\">Vedic Shakhas\r\n                                    (schools)</strong> and were trained in the precise recitation of Vedic mantras and\r\n                                the correct performance of the ritual.\r\n                            </p>\r\n                        </div>\r\n\r\n                        <!-- THREE SACRED FIRES -->\r\n                        <div>\r\n                            <div class=\"ukt-agnihotri-label-teal\">\r\n                                <i class=\"bi bi-fire text-warning\"></i>\r\n                                THREE SACRED FIRES\r\n                            </div>\r\n\r\n                            <p class=\"ukt-agnihotri-prose-mb\">\r\n                                The Agnihotri maintained three sacred fires:\r\n                            </p>\r\n\r\n                            <!-- Fire rows -->\r\n                            <div class=\"ukt-fire-rows-list\">\r\n\r\n                                <!-- GARHAPATYA -->\r\n                                <div class=\"ukt-fire-row-item-garhapatya\">\r\n                                    <div class=\"ukt-fire-row-icon-orange\">\r\n                                        <i class=\"bi bi-house-heart-fill\"></i>\r\n                                    </div>\r\n                                    <div>\r\n                                        <span class=\"ukt-fire-row-name\">Garhapatya</span>\r\n                                        <span class=\"ukt-fire-row-type\">(household fire)</span>\r\n                                    </div>\r\n                                </div>\r\n\r\n                                <!-- DAKSHINAGNI -->\r\n                                <div class=\"ukt-fire-row-item-dakshinagni\">\r\n                                    <div class=\"ukt-fire-row-icon-teal\">\r\n                                        <i class=\"bi bi-compass-fill\"></i>\r\n                                    </div>\r\n                                    <div>\r\n                                        <span class=\"ukt-fire-row-name\">Dakshinagni</span>\r\n                                        <span class=\"ukt-fire-row-type\">(southern fire)</span>\r\n                                    </div>\r\n                                </div>\r\n\r\n                                <!-- AHAVANIYA -->\r\n                                <div class=\"ukt-fire-row-item-ahavaniya\">\r\n                                    <div class=\"ukt-fire-row-icon-gold\">\r\n                                        <i class=\"bi bi-stars\"></i>\r\n                                    </div>\r\n                                    <div>\r\n                                        <span class=\"ukt-fire-row-name\">Ahavaniya</span>\r\n                                        <span class=\"ukt-fire-row-type\">(offering fire)</span>\r\n                                    </div>\r\n                                </div>\r\n\r\n                            </div><!-- /.fire rows -->\r\n\r\n                            <!-- Closing statement -->\r\n                            <div class=\"ukt-fire-closing-note\">\r\n                                <p>\r\n                                    These fires symbolized different aspects of life and the cosmos.\r\n                                </p>\r\n                            </div>\r\n\r\n                        </div><!-- /.three sacred fires -->\r\n\r\n                    </div><!-- /.inner padding wrap -->\r\n\r\n                </div><!-- /.unified card -->\r\n\r\n            </div>\r\n        </section>\r\n\r\n\r\n        <!-- =========================================================\r\n             SECTION 4: HISTORICAL TIMELINE (1500 BCE - PRESENT)\r\n        ========================================================== -->\r\n        <section class=\"py-5 ukt-vedic-sources-section\">\r\n            <div class=\"container py-lg-4\">\r\n\r\n                <!-- SECTION HEADER -->\r\n                <div class=\"ukt-section-header\">\r\n                    <div class=\"ukt-section-eyebrow\">\r\n                        <span></span>\r\n                        HISTORICAL EVOLUTION\r\n                        <span></span>\r\n                    </div>\r\n                    <h2 class=\"ukt-section-main-title\">\r\n                        Timeline of the <span>Agnihotri Tradition</span>\r\n                    </h2>\r\n                    <div class=\"ukt-section-heading-design\">\r\n                        <span></span>\r\n                        <i class=\"bi bi-flower1\"></i>\r\n                        <span></span>\r\n                    </div>\r\n                    <p class=\"ukt-section-lead-text\">\r\n                        How the sacred fire practice evolved from ancient Vedic Shrauta sacrifices to its modern\r\n                        ecological and therapeutic revival worldwide.\r\n                    </p>\r\n                </div>\r\n\r\n                <div class=\"ukt-timeline-container\">\r\n\r\n                    <!-- ERA 1: VEDIC ORIGINS -->\r\n                    <div class=\"ukt-timeline-item\">\r\n                        <div class=\"ukt-timeline-dot\"></div>\r\n                        <div class=\"ukt-timeline-card\">\r\n                            <span class=\"ukt-timeline-era\">c. 1500 – 500 BCE</span>\r\n                            <h3 class=\"ukt-timeline-title\">1. Vedic Origins</h3>\r\n                            <div class=\"ukt-timeline-text-wrap\">\r\n                                <p class=\"ukt-timeline-text\">\r\n                                    <strong>Source in the Vedas:</strong> The Agnihotra ritual is explicitly mentioned\r\n                                    in the Yajurveda, particularly in the Shukla Yajurveda, and is elaborated upon in\r\n                                    the Brahmana texts, such as the Shatapatha Brahmana. These texts provide detailed\r\n                                    instructions on how to perform the ritual.\r\n                                </p>\r\n                                <p class=\"ukt-timeline-text ukt-timeline-text-spacing\">\r\n                                    <strong>Purpose and Symbolism:</strong> The ritual involves offering oblations (such\r\n                                    as milk, ghee, or grains) into a sacred fire at sunrise and sunset. It is performed\r\n                                    to honor Agni (the fire god) and Surya (the sun god), who are considered essential\r\n                                    for maintaining cosmic order (<em>ṛta</em>). Agni, as the divine messenger, carries\r\n                                    the offerings to the gods, ensuring harmony between the human and divine realms.\r\n                                </p>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- ERA 2: POST-VEDIC PERIOD -->\r\n                    <div class=\"ukt-timeline-item\">\r\n                        <div class=\"ukt-timeline-dot\"></div>\r\n                        <div class=\"ukt-timeline-card\">\r\n                            <span class=\"ukt-timeline-era\">c. 500 BCE – 500 CE</span>\r\n                            <h3 class=\"ukt-timeline-title\">2. Post-Vedic Period</h3>\r\n                            <div class=\"ukt-timeline-text-wrap\">\r\n                                <p class=\"ukt-timeline-text\">\r\n                                    <strong>Codification in Grihya Sutras:</strong> During this period, the Agnihotra\r\n                                    was codified in the Grihya Sutras, which are texts dealing with domestic rituals.\r\n                                    The ritual became more accessible to householders (<em>grhasthas</em>) and was\r\n                                    integrated into daily life.\r\n                                </p>\r\n                                <p class=\"ukt-timeline-text ukt-timeline-text-spacing\">\r\n                                    <strong>Philosophical Shifts:</strong> With the rise of the Upanishads, there was a\r\n                                    shift from external rituals to internal spiritual practices. However, the Agnihotra\r\n                                    continued to be practiced as a symbolic act of maintaining cosmic and social order.\r\n                                </p>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- ERA 3: MEDIEVAL PERIOD -->\r\n                    <div class=\"ukt-timeline-item\">\r\n                        <div class=\"ukt-timeline-dot\"></div>\r\n                        <div class=\"ukt-timeline-card\">\r\n                            <span class=\"ukt-timeline-era\">c. 500 – 1500 CE</span>\r\n                            <h3 class=\"ukt-timeline-title\">3. Medieval Period</h3>\r\n                            <div class=\"ukt-timeline-text-wrap\">\r\n                                <p class=\"ukt-timeline-text\">\r\n                                    <strong>Continuity Amidst Change:</strong> Despite the rise of Buddhism, Jainism,\r\n                                    and later Islam, the Agnihotri tradition was preserved by Brahmin families,\r\n                                    particularly in regions like Maharashtra, Gujarat, and Bengal. These families\r\n                                    maintained the ritual as part of their cultural and religious identity.\r\n                                </p>\r\n                                <p class=\"ukt-timeline-text ukt-timeline-text-spacing\">\r\n                                    <strong>Integration into Temple Rituals:</strong> The Agnihotra also found its way\r\n                                    into temple rituals, where it was performed as part of larger ceremonies.\r\n                                </p>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- ERA 4: MODERN ERA -->\r\n                    <div class=\"ukt-timeline-item\">\r\n                        <div class=\"ukt-timeline-dot\"></div>\r\n                        <div class=\"ukt-timeline-card\">\r\n                            <span class=\"ukt-timeline-era\">19th Century – Present</span>\r\n                            <h3 class=\"ukt-timeline-title\">4. Modern Era</h3>\r\n                            <div class=\"ukt-timeline-text-wrap\">\r\n                                <p class=\"ukt-timeline-text\">\r\n                                    <strong>Revival and Adaptation:</strong> In the 19th and 20th centuries, movements\r\n                                    like the Arya Samaj sought to revive Vedic practices, including the Agnihotra. In\r\n                                    contemporary times, the ritual has been reinterpreted by spiritual groups for its\r\n                                    ecological and therapeutic benefits. For example, some practitioners claim that the\r\n                                    ritual purifies the environment and promotes mental well-being.\r\n                                </p>\r\n                                <p class=\"ukt-timeline-text ukt-timeline-text-spacing\">\r\n                                    <strong>Global Spread:</strong> The Agnihotra has gained followers outside India,\r\n                                    with people around the world adopting it as a form of spiritual and ecological\r\n                                    practice.\r\n                                </p>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- KEY TAKEAWAYS -->\r\n                    <div class=\"ukt-timeline-item\">\r\n                        <div class=\"ukt-timeline-dot\"></div>\r\n                        <div class=\"ukt-timeline-card\">\r\n                            <span class=\"ukt-timeline-era\">Summary</span>\r\n                            <h3 class=\"ukt-timeline-title\">Key Takeaways</h3>\r\n                            <div class=\"ukt-timeline-text-wrap\">\r\n                                <p class=\"ukt-timeline-text\">\r\n                                    – The Agnihotri practice originated in the Vedic period as a fire ritual to honor\r\n                                    Agni and Surya, maintaining cosmic order.\r\n                                </p>\r\n                                <p class=\"ukt-timeline-text ukt-timeline-text-spacing\">\r\n                                    – It was preserved by Brahmin families and adapted over time, surviving through\r\n                                    various cultural and religious shifts.\r\n                                </p>\r\n                                <p class=\"ukt-timeline-text ukt-timeline-text-spacing\">\r\n                                    – Today, it continues to be practiced both in its traditional form and as a modern\r\n                                    spiritual and ecological ritual.\r\n                                </p>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n        </section>\r\n\r\n        <!-- =========================================================\r\n             SECTION 6: HOW TO PERFORM AGNIHOTRA\r\n        ========================================================== -->\r\n        <section id=\"agnihotra_procedure\" class=\"py-5 ukt-procedure-section\">\r\n            <div class=\"container py-lg-4\">\r\n\r\n                <!-- SECTION HEADER -->\r\n                <div class=\"ukt-section-header\">\r\n                    <div class=\"ukt-section-eyebrow\">\r\n                        <span></span>\r\n                        STEP-BY-STEP RITUAL GUIDE\r\n                        <span></span>\r\n                    </div>\r\n                    <h2 class=\"ukt-section-main-title\">\r\n                        How to Perform <span>Agnihotra</span>\r\n                    </h2>\r\n                    <div class=\"ukt-section-heading-design\">\r\n                        <span></span>\r\n                        <i class=\"bi bi-flower1\"></i>\r\n                        <span></span>\r\n                    </div>\r\n                    <p class=\"ukt-section-lead-text\">\r\n                        Angihotra, also known as Agnihotra, is an ancient Vedic fire ritual originating from India. It’s\r\n                        a powerful practice for physical, mental, and spiritual well-being. Here’s a step-by-step guide:\r\n                    </p>\r\n                </div>\r\n\r\n                <!-- ROW 1: MERGED CARDS (MATERIALS & PREPARATION + TIPS & BENEFITS) -->\r\n                <div class=\"row g-4 align-items-stretch mb-4 text-start\">\r\n\r\n                    <!-- MERGED DIV 1: MATERIALS NEEDED & PREPARATION -->\r\n                    <div class=\"col-lg-6\">\r\n                        <div class=\"ukt-procedure-card-materials\">\r\n                            <div class=\"ukt-procedure-card-accent-gold\"></div>\r\n\r\n                            <div>\r\n                                <!-- Materials Needed -->\r\n                                <div class=\"d-flex align-items-center gap-3 mb-3\">\r\n                                    <div class=\"ukt-procedure-icon-gold\">\r\n                                        <i class=\"bi bi-box-seam-fill\"></i>\r\n                                    </div>\r\n                                    <div>\r\n                                        <div class=\"ukt-procedure-kicker-amber\">\r\n                                            ESSENTIALS</div>\r\n                                        <h3 class=\"ukt-procedure-card-title\">\r\n                                            Materials Needed</h3>\r\n                                    </div>\r\n                                </div>\r\n                                <div class=\"row g-2 mb-4\">\r\n                                    <div class=\"col-sm-6\">\r\n                                        <div class=\"ukt-procedure-material-box\">\r\n                                            <i class=\"bi bi-triangle-fill ukt-procedure-icon-gold-sm\"></i>\r\n                                            <span>Copper pyramid (specifically designed for Agnihotra)</span>\r\n                                        </div>\r\n                                    </div>\r\n                                    <div class=\"col-sm-6\">\r\n                                        <div class=\"ukt-procedure-material-box\">\r\n                                            <i class=\"bi bi-droplet-fill ukt-procedure-icon-gold-sm\"></i>\r\n                                            <span>Ghee (clarified butter)</span>\r\n                                        </div>\r\n                                    </div>\r\n                                    <div class=\"col-sm-6\">\r\n                                        <div class=\"ukt-procedure-material-box\">\r\n                                            <i class=\"bi bi-circle-fill ukt-procedure-icon-gold-xs\"></i>\r\n                                            <span>Rice grains</span>\r\n                                        </div>\r\n                                    </div>\r\n                                    <div class=\"col-sm-6\">\r\n                                        <div class=\"ukt-procedure-material-box\">\r\n                                            <i class=\"bi bi-fire ukt-procedure-icon-gold-sm\"></i>\r\n                                            <span>Cow dung cakes</span>\r\n                                        </div>\r\n                                    </div>\r\n                                    <div class=\"col-sm-6\">\r\n                                        <div class=\"ukt-procedure-material-box\">\r\n                                            <i class=\"bi bi-lightning-charge-fill ukt-procedure-icon-gold-sm\"></i>\r\n                                            <span>Matches or a lighter</span>\r\n                                        </div>\r\n                                    </div>\r\n                                    <div class=\"col-sm-6\">\r\n                                        <div class=\"ukt-procedure-material-box\">\r\n                                            <i class=\"bi bi-clock-fill ukt-procedure-icon-gold-sm\"></i>\r\n                                            <span>Timing device (to synchronize with sunrise/sunset)</span>\r\n                                        </div>\r\n                                    </div>\r\n                                </div>\r\n\r\n                                <!-- Divider -->\r\n                                <div class=\"ukt-procedure-divider\"></div>\r\n\r\n                                <!-- Preparation -->\r\n                                <div class=\"d-flex align-items-center gap-3 mb-3\">\r\n                                    <div class=\"ukt-procedure-icon-teal\">\r\n                                        <i class=\"bi bi-clipboard2-check-fill\"></i>\r\n                                    </div>\r\n                                    <div>\r\n                                        <div class=\"ukt-procedure-kicker-cyan\">\r\n                                            SETTING UP</div>\r\n                                        <h3 class=\"ukt-procedure-card-title\">\r\n                                            Preparation</h3>\r\n                                    </div>\r\n                                </div>\r\n                                <div class=\"ukt-procedure-steps-wrap\">\r\n                                    <div class=\"ukt-procedure-step-row\">\r\n                                        <div class=\"ukt-procedure-step-badge-teal\">1</div>\r\n                                        <p class=\"ukt-procedure-step-desc\">\r\n                                            Choose a quiet, clean space for performing the ritual.</p>\r\n                                    </div>\r\n                                    <div class=\"ukt-procedure-step-row\">\r\n                                        <div class=\"ukt-procedure-step-badge-teal\">2</div>\r\n                                        <p class=\"ukt-procedure-step-desc\">\r\n                                            Set up the copper pyramid on a safe, heat-resistant surface.</p>\r\n                                    </div>\r\n                                    <div class=\"ukt-procedure-step-row\">\r\n                                        <div class=\"ukt-procedure-step-badge-teal\">3</div>\r\n                                        <p class=\"ukt-procedure-step-desc\">\r\n                                            Prepare ghee and rice grains beforehand.</p>\r\n                                    </div>\r\n                                    <div class=\"text-center pt-2\">\r\n                                        <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-world-record/31-U3L5RSFL-300x236-1.webp\"\r\n                                            alt=\"Agnihotra Copper Pyramid Kit\" title=\"Agnihotra Copper Pyramid Kit\"\r\n                                            class=\"img-fluid rounded ukt-procedure-kit-img\">\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- MERGED DIV 2: TIPS, PRECAUTIONS & BENEFITS -->\r\n                    <div class=\"col-lg-6\">\r\n                        <div class=\"ukt-procedure-card-tips\">\r\n                            <div class=\"ukt-procedure-card-accent-multi\"></div>\r\n\r\n                            <div>\r\n                                <!-- Tips & Precautions -->\r\n                                <div class=\"d-flex align-items-center gap-3 mb-3\">\r\n                                    <div class=\"ukt-procedure-icon-teal-cyan\">\r\n                                        <i class=\"bi bi-shield-fill-check\"></i>\r\n                                    </div>\r\n                                    <div>\r\n                                        <div class=\"ukt-procedure-kicker-cyan\">\r\n                                            GUIDELINES &amp; SAFETY</div>\r\n                                        <h3 class=\"ukt-procedure-card-title\">\r\n                                            Tips and Precautions</h3>\r\n                                    </div>\r\n                                </div>\r\n                                <div class=\"ukt-procedure-guidelines-wrap\">\r\n                                    <div class=\"ukt-procedure-guideline-item\">\r\n                                        <i class=\"bi bi-alarm-fill ukt-procedure-icon-cyan-sm\"></i>\r\n                                        <span>1. Use a timer to synchronize with sunrise/sunset.</span>\r\n                                    </div>\r\n                                    <div class=\"ukt-procedure-guideline-item\">\r\n                                        <i class=\"bi bi-calendar-check-fill ukt-procedure-icon-cyan-sm\"></i>\r\n                                        <span>2. Maintain a consistent schedule.</span>\r\n                                    </div>\r\n                                    <div class=\"ukt-procedure-guideline-item\">\r\n                                        <i class=\"bi bi-sparkles ukt-procedure-icon-cyan-sm\"></i>\r\n                                        <span>3. Keep the area clean and free from distractions.</span>\r\n                                    </div>\r\n                                    <div class=\"ukt-procedure-guideline-item-danger\">\r\n                                        <i class=\"bi bi-exclamation-triangle-fill ukt-procedure-icon-danger-sm\"></i>\r\n                                        <span>4. Avoid performing Agnihotra during menstruation or when feeling\r\n                                            unwell.</span>\r\n                                    </div>\r\n                                    <div class=\"ukt-procedure-guideline-item\">\r\n                                        <i class=\"bi bi-fire ukt-procedure-icon-gold-mid\"></i>\r\n                                        <span>5. Respect the fire and handle it carefully.</span>\r\n                                    </div>\r\n                                </div>\r\n\r\n                                <!-- Divider -->\r\n                                <div class=\"ukt-procedure-divider\"></div>\r\n\r\n                                <!-- Benefits -->\r\n                                <div class=\"d-flex align-items-center gap-3 mb-3\">\r\n                                    <div class=\"ukt-procedure-icon-gold-teal\">\r\n                                        <i class=\"bi bi-stars\"></i>\r\n                                    </div>\r\n                                    <div>\r\n                                        <div class=\"ukt-procedure-kicker-amber\">\r\n                                            TRANSFORMATION</div>\r\n                                        <h3 class=\"ukt-procedure-card-title\">\r\n                                            Benefits</h3>\r\n                                    </div>\r\n                                </div>\r\n                                <div class=\"row g-2 mb-3\">\r\n                                    <div class=\"col-sm-6\">\r\n                                        <div class=\"ukt-procedure-benefit-pill\">\r\n                                            <i class=\"bi bi-wind\"></i> 1. Purifies the environment\r\n                                        </div>\r\n                                    </div>\r\n                                    <div class=\"col-sm-6\">\r\n                                        <div class=\"ukt-procedure-benefit-pill\">\r\n                                            <i class=\"bi bi-brain\"></i> 2. Improves mental clarity and focus\r\n                                        </div>\r\n                                    </div>\r\n                                    <div class=\"col-sm-6\">\r\n                                        <div class=\"ukt-procedure-benefit-pill\">\r\n                                            <i class=\"bi bi-heart-pulse-fill\"></i> 3. Enhances physical health\r\n                                        </div>\r\n                                    </div>\r\n                                    <div class=\"col-sm-6\">\r\n                                        <div class=\"ukt-procedure-benefit-pill\">\r\n                                            <i class=\"bi bi-emoji-smile-fill\"></i> 4. Reduces stress and anxiety\r\n                                        </div>\r\n                                    </div>\r\n                                    <div class=\"col-12\">\r\n                                        <div class=\"ukt-procedure-benefit-pill\">\r\n                                            <i class=\"bi bi-flower2\"></i> 5. Promotes spiritual growth\r\n                                        </div>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                </div><!-- /.row 1 -->\r\n\r\n                <!-- ROW 2: PROCEDURES (SUNRISE & SUNSET) -->\r\n                <div class=\"row g-4 align-items-stretch text-start\">\r\n\r\n                    <!-- SUNRISE AGNIHOTRA -->\r\n                    <div class=\"col-lg-6\">\r\n                        <div class=\"ukt-procedure-card-sunrise text-start\">\r\n                            <div class=\"ukt-procedure-card-accent-orange\"></div>\r\n                            <div class=\"d-flex align-items-center gap-3 mb-4\">\r\n                                <div class=\"ukt-procedure-icon-orange\">\r\n                                    <i class=\"bi bi-sunrise-fill\"></i>\r\n                                </div>\r\n                                <div>\r\n                                    <div class=\"ukt-procedure-kicker-amber mb-1\">\r\n                                        MORNING RITUAL</div>\r\n                                    <h3 class=\"ukt-procedure-card-title-lg\">\r\n                                        Sunrise Agnihotra</h3>\r\n                                </div>\r\n                            </div>\r\n                            <div class=\"ukt-procedure-steps-gap\">\r\n                                <div class=\"ukt-procedure-step-row\">\r\n                                    <span class=\"ukt-procedure-step-badge-orange\">1</span>\r\n                                    <p class=\"ukt-procedure-step-desc\">\r\n                                        Calculate local sunrise time.</p>\r\n                                </div>\r\n                                <div class=\"ukt-procedure-step-row\">\r\n                                    <span class=\"ukt-procedure-step-badge-orange\">2</span>\r\n                                    <p class=\"ukt-procedure-step-desc\">\r\n                                        Light the fire 10-15 minutes before sunrise.</p>\r\n                                </div>\r\n                                <div class=\"ukt-procedure-step-row\">\r\n                                    <span class=\"ukt-procedure-step-badge-orange\">3</span>\r\n                                    <p class=\"ukt-procedure-step-desc\">\r\n                                        Add 2-3 pinches of rice grains to the fire.</p>\r\n                                </div>\r\n                                <div class=\"ukt-procedure-step-row\">\r\n                                    <span class=\"ukt-procedure-step-badge-orange\">4</span>\r\n                                    <p class=\"ukt-procedure-step-desc\">\r\n                                        Add 2-3 drops of ghee to the fire.</p>\r\n                                </div>\r\n                                <div class=\"ukt-procedure-step-row\">\r\n                                    <span class=\"ukt-procedure-step-badge-orange\">5</span>\r\n                                    <p class=\"ukt-procedure-step-desc\">\r\n                                        Recite the 2 mantras:</p>\r\n                                </div>\r\n                                <div class=\"ukt-procedure-step-row\">\r\n                                    <span class=\"ukt-procedure-step-badge-orange\">6</span>\r\n                                    <p class=\"ukt-procedure-step-desc\">\r\n                                        . Repeat steps 3-5 for 10-15 minutes.</p>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- SUNSET AGNIHOTRA -->\r\n                    <div class=\"col-lg-6\">\r\n                        <div class=\"ukt-procedure-card-sunset\">\r\n                            <div class=\"ukt-procedure-card-accent-purple\"></div>\r\n                            <div class=\"d-flex align-items-center gap-3 mb-4\">\r\n                                <div class=\"ukt-procedure-icon-purple\">\r\n                                    <i class=\"bi bi-sunset-fill\"></i>\r\n                                </div>\r\n                                <div>\r\n                                    <div class=\"ukt-procedure-kicker-purple\">\r\n                                        EVENING RITUAL</div>\r\n                                    <h3 class=\"ukt-procedure-card-title-lg\">\r\n                                        Sunset Agnihotra</h3>\r\n                                </div>\r\n                            </div>\r\n                            <div class=\"ukt-procedure-steps-gap\">\r\n                                <div class=\"ukt-procedure-step-row\">\r\n                                    <span class=\"ukt-procedure-step-badge-purple\">1</span>\r\n                                    <p class=\"ukt-procedure-step-desc\">\r\n                                        Calculate local sunset time.</p>\r\n                                </div>\r\n                                <div class=\"ukt-procedure-step-row\">\r\n                                    <span class=\"ukt-procedure-step-badge-purple\">2</span>\r\n                                    <p class=\"ukt-procedure-step-desc\">\r\n                                        Light the fire 10-15 minutes before sunset.</p>\r\n                                </div>\r\n                                <div class=\"ukt-procedure-step-row\">\r\n                                    <span class=\"ukt-procedure-step-badge-purple\">3</span>\r\n                                    <p class=\"ukt-procedure-step-desc\">\r\n                                        Add 2-3 pinches of rice grains to the fire.</p>\r\n                                </div>\r\n                                <div class=\"ukt-procedure-step-row\">\r\n                                    <span class=\"ukt-procedure-step-badge-purple\">4</span>\r\n                                    <p class=\"ukt-procedure-step-desc\">\r\n                                        Add 2-3 drops of ghee to the fire.</p>\r\n                                </div>\r\n                                <div class=\"ukt-procedure-step-row\">\r\n                                    <span class=\"ukt-procedure-step-badge-purple\">5</span>\r\n                                    <p class=\"ukt-procedure-step-desc\">\r\n                                        Recite the 2 mantra:</p>\r\n                                </div>\r\n                                <div class=\"ukt-procedure-step-row\">\r\n                                    <span class=\"ukt-procedure-step-badge-purple\">6</span>\r\n                                    <p class=\"ukt-procedure-step-desc\">\r\n                                        Repeat steps 3-5 for 10-15 minutes.</p>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                </div><!-- /.row 2 -->\r\n\r\n                <!-- RESOURCES -->\r\n                <div class=\"ukt-practical-unified-card mt-4 mb-3 text-start\">\r\n                    <div class=\"ukt-practical-accent-bar\"></div>\r\n                    <h3 class=\"ukt-practical-title ukt-practical-title-md mb-2\">\r\n                        <i class=\"bi bi-journal-bookmark-fill ukt-icon-gold\"></i> Resources:\r\n                    </h3>\r\n                    <ul class=\"ukt-practical-list-nomargin\">\r\n                        <li class=\"ukt-practical-list-item\">\r\n                            <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                            <div>1. Consult Vedic texts or experienced practitioners for guidance.</div>\r\n                        </li>\r\n                        <li class=\"ukt-practical-list-item\">\r\n                            <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                            <div>2. Visit <a href=\"http://localhost/universal-knowledge-trust-wordpress/agnihotra-procedures\"\r\n                                    class=\"ukt-agnihotra-link-teal fw-bold text-decoration-none\">Agnihotra Procedure</a>\r\n                                for more information.</div>\r\n                        </li>\r\n                    </ul>\r\n                </div>\r\n\r\n                <!-- CONSISTENCY CALLOUT -->\r\n                <div class=\"ukt-procedure-consistency-box\">\r\n                    <i class=\"bi bi-fire me-2\"></i>\r\n                    <span>Remember, consistency and sincerity are key to experiencing the benefits of Agnihotra.</span>\r\n                </div>\r\n\r\n                <!-- WORLD RECORD PARTICIPATION PARAGRAPHS -->\r\n                <div class=\"mt-4 text-start\">\r\n                    <p class=\"ukt-agnihotra-record-text mb-2\">\r\n                        Gram Vikas Society (GVS) Powered by Universal Knowledge is creating a World Record by lighting\r\n                        Agnihotra at 11,000 + at single location.\r\n                    </p>\r\n\r\n                    <p class=\"ukt-agnihotra-record-text mb-3\">\r\n                        This is an unique program and we will join to have a Agnihotra done at 11,000 different houses /\r\n                        offices in and around Karnataka\r\n                    </p>\r\n\r\n                    <h4 class=\"ukt-agnihotra-record-subheading fw-bold mb-2\">\r\n                        How you can be a part of this world record?\r\n                    </h4>\r\n\r\n                    <p class=\"ukt-agnihotra-record-text mb-2\">\r\n                        If you are willing to participate and have agnihotra done at your house or office daily, you can\r\n                        apply at the link below;\r\n                    </p>\r\n\r\n                    <p class=\"ukt-agnihotra-record-text mb-2\">\r\n                        Gram Vikas Society (GVS) will provide you with free startup Agnihotra kit, which will include\r\n                        Copper pyramid Bowl, startup material for 4 days worth ₹ 1,250/-.\r\n                    </p>\r\n\r\n                    <p class=\"ukt-agnihotra-record-text mb-0\">\r\n                        You will need to have Cow Dung, Ghee and unbroken Rice, which is a daily consumption.\r\n                    </p>\r\n                </div>\r\n\r\n            </div>\r\n        </section>\r\n\r\n        <!-- =========================================================\r\n             SECTION 5: PRACTICAL CONSIDERATIONS & ACADEMIC STUDIES\r\n        ========================================================== -->\r\n        <section class=\"py-5 ukt-practical-section\">\r\n            <div class=\"container py-lg-4\">\r\n\r\n                <!-- SECTION HEADER -->\r\n                <div class=\"ukt-section-header\">\r\n                    <div class=\"ukt-section-eyebrow\">\r\n                        <span></span>\r\n                        RESEARCH &amp; GUIDELINES\r\n                        <span></span>\r\n                    </div>\r\n                    <h2 class=\"ukt-section-main-title\">\r\n                        Practical Considerations <span>&amp; Academic Studies</span>\r\n                    </h2>\r\n                    <div class=\"ukt-section-heading-design\">\r\n                        <span></span>\r\n                        <i class=\"bi bi-flower1\"></i>\r\n                        <span></span>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- SINGLE UNIFIED CONTAINER DIV (SIMPLE LIST FORMAT) -->\r\n                <div class=\"ukt-practical-unified-card\">\r\n                    <div class=\"ukt-practical-accent-bar\"></div>\r\n\r\n                    <div class=\"row g-4 g-lg-5 text-start\">\r\n\r\n                        <!-- LEFT COLUMN: MODERN GUIDES & ACADEMIC WORKS -->\r\n                        <div class=\"col-lg-6\">\r\n\r\n                            <!-- Modern Guides & Commentaries -->\r\n                            <h3 class=\"ukt-practical-title\">\r\n                                <i class=\"bi bi-book-half ukt-icon-gold\"></i> Modern Guides & Commentaries:\r\n                            </h3>\r\n                            <ul class=\"ukt-practical-list\">\r\n                                <li class=\"ukt-practical-list-item\">\r\n                                    <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                                    <div>\r\n                                        <strong class=\"ukt-text-highlight-teal\">Fivefold Path Mission:</strong> Founded\r\n                                        by Shree\r\n                                        Vasant Paranjpe, this organization promotes Agni Hotra. Their handbook,\r\n                                        “Agnihotra: The Ultimate Homa Therapy”, blends tradition with practical\r\n                                        guidance.\r\n                                    </div>\r\n                                </li>\r\n                            </ul>\r\n\r\n                            <!-- Academic Works -->\r\n                            <h3 class=\"ukt-practical-title\">\r\n                                <i class=\"bi bi-mortarboard-fill ukt-icon-cyan\"></i> Academic Works:\r\n                            </h3>\r\n                            <ul class=\"ukt-practical-list\">\r\n                                <li class=\"ukt-practical-list-item\">\r\n                                    <i class=\"bi bi-circle-fill ukt-practical-dot-cyan\"></i>\r\n                                    <div>\r\n                                        “Agni: The Vedic Ritual of the Fire Altar” by Frits Staal (1983) analyzes ritual\r\n                                        structures.\r\n                                    </div>\r\n                                </li>\r\n                                <li class=\"ukt-practical-list-item\">\r\n                                    <i class=\"bi bi-circle-fill ukt-practical-dot-cyan\"></i>\r\n                                    <div>\r\n                                        David Frawley’s “Wisdom of the Ancient Seers” (1992) contextualizes Vedic\r\n                                        practices.\r\n                                    </div>\r\n                                </li>\r\n                            </ul>\r\n\r\n                            <!-- Key Takeaway -->\r\n                            <h3 class=\"ukt-practical-title\">\r\n                                <i class=\"bi bi-key-fill ukt-icon-gold\"></i> Key Takeaway:\r\n                            </h3>\r\n                            <p class=\"ukt-practical-list-item mb-3\">\r\n                                While written texts provide foundational knowledge, Agni Hotra’s authenticity relies on\r\n                                oral transmission (guru-shishya parampara). Cross-reference primary sources with\r\n                                reputable modern interpretations for a holistic understanding.\r\n                            </p>\r\n                            <p class=\"ukt-practical-list-item mb-0\">\r\n                                The Agnihotri practice originates from the Vedic period of ancient India and is closely\r\n                                linked to Vedic rituals and the Agnihotra fire sacrifice. The term Agnihotri refers to a\r\n                                Brahmin who performs the Agnihotra ritual daily and maintains the sacred fire (Agni) as\r\n                                part of their spiritual and priestly duties.\r\n                            </p>\r\n\r\n                        </div>\r\n\r\n                        <!-- RIGHT COLUMN: PRACTICAL CONSIDERATIONS -->\r\n                        <div class=\"col-lg-6\">\r\n\r\n                            <h3 class=\"ukt-practical-title\">\r\n                                <i class=\"bi bi-sliders ukt-icon-cyan\"></i> Practical Considerations:\r\n                            </h3>\r\n                            <ul class=\"ukt-practical-list-nomargin\">\r\n                                <li class=\"ukt-practical-list-item\">\r\n                                    <i class=\"bi bi-circle-fill ukt-practical-dot-cyan\"></i>\r\n                                    <div>\r\n                                        <strong class=\"ukt-text-highlight-teal\">Oral Tradition:</strong> The ritual\r\n                                        requires\r\n                                        precise mantras, timings (sunrise/sunset), and materials (cow dung, ghee, rice).\r\n                                        Seek guidance from a knowledgeable priest or practitioner.\r\n                                    </div>\r\n                                </li>\r\n                                <li class=\"ukt-practical-list-item\">\r\n                                    <i class=\"bi bi-circle-fill ukt-practical-dot-cyan\"></i>\r\n                                    <div>\r\n                                        <strong class=\"ukt-text-highlight-teal\">Ethical Sourcing:</strong> Use organic\r\n                                        offerings\r\n                                        and copper pyramid-shaped pots as prescribed.\r\n                                    </div>\r\n                                </li>\r\n                            </ul>\r\n\r\n                        </div>\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n        </section>\r\n\r\n        <!-- =========================================================\r\n             SECTION 7: FEATURED VIDEOS & IMAGES\r\n        ========================================================== -->\r\n        <section class=\"py-5 ukt-vedic-sources-section\" id=\"featured-videos\">\r\n            <div class=\"container py-lg-4\">\r\n\r\n                <!-- SECTION HEADER -->\r\n                <div class=\"ukt-section-header\">\r\n                    <div class=\"ukt-section-eyebrow\">\r\n                        <span></span>\r\n                        MEDIA HIGHLIGHTS\r\n                        <span></span>\r\n                    </div>