INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(244, 1, '2026-10-26 17:26:23', '2026-10-26 11:56:23', '<!-- =========================================================\r\n     ARTICLE CONTENT\r\n========================================================== -->\r\n<article>\r\n\r\n    <!-- =========================================================\r\n         HERO SHOWCASE SECTION\r\n    ========================================================== -->\r\n    <section class=\"ukt-hero-showcase\">\r\n        <div class=\"ukt-hero-slide-layout\">\r\n            <div class=\"container-fluid\">\r\n                <div class=\"row g-0 align-items-stretch\">\r\n\r\n                    <!-- LEFT CONTENT AREA -->\r\n                    <div class=\"col-lg-5 d-flex align-items-center\">\r\n                        <div class=\"ukt-hero-copy-zone\">\r\n                            <div class=\"ukt-hero-left-decoration\"></div>\r\n\r\n                            <div class=\"ukt-hero-slide-kicker\">\r\n                                Ancient Vedic Fire Science &amp; Homa Therapy\r\n                            </div>\r\n\r\n                            <h1 class=\"ukt-hero-main-title\">\r\n                                Karnataka Agnihotra <span>Spectacular</span>\r\n                            </h1>\r\n\r\n                            <div class=\"ukt-hero-script-line\">\r\n                                Purifying Atmosphere, Mind &amp; Spirit\r\n                            </div>\r\n\r\n                            <p class=\"ukt-hero-description\">\r\n                                The Agnihotra is an ancient Vedic fire ritual rooted in the Yajurveda. Performed at\r\n                                sunrise and sunset with authentic copper pyramid vessels, it restores cosmic harmony\r\n                                (ṛta), heals the surrounding atmosphere, and cultivates profound spiritual\r\n                                elevation.\r\n                            </p>\r\n\r\n                            <div class=\"ukt-hero-action-row\">\r\n                                <a href=\"#vedic-sources\" class=\"ukt-hero-primary-action\">\r\n                                    Explore Vedic Roots\r\n                                    <i class=\"bi bi-arrow-down\"></i>\r\n                                </a>\r\n\r\n                                <a href=\"http://localhost/universal-knowledge-trust-wordpress/agnihotra-procedures\" class=\"ukt-hero-secondary-action\">\r\n                                    <i class=\"bi bi-fire text-warning me-1\"></i> Ritual Procedure\r\n                                </a>\r\n                            </div>\r\n\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- RIGHT IMAGE AREA -->\r\n                    <div class=\"col-lg-7\">\r\n                        <div class=\"ukt-hero-visual-zone\">\r\n                            <div class=\"ukt-hero-image-frame\">\r\n                                <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/karnataka-agnihotra-banner.jpg\"\r\n                                    alt=\"Karnataka Agnihotra Spectacular - Vedic Fire Ritual by Universal Knowledge Trust\"\r\n                                    title=\"Karnataka Agnihotra Spectacular\" loading=\"eager\">\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         SECTION: KARNATAKA AGNIHOTRA SPECTACULAR - WORLD AGNIHOTRA DAY 2025\r\n    ========================================================== -->\r\n    <section class=\"py-5 ukt-agnihotra-record-section\" id=\"world-agnihotra-day-2025\">\r\n        <div class=\"container py-lg-2\">\r\n            <div class=\"row align-items-center g-4 g-lg-5\">\r\n\r\n                <!-- LEFT COLUMN: CAROUSEL WITH SLIDING EFFECT -->\r\n                <div class=\"col-lg-6 col-md-12\">\r\n                    <div class=\"pe-lg-3\">\r\n                        <div class=\"ukt-agnihotra-carousel-frame\">\r\n\r\n                            <!-- BOOTSTRAP SLIDING CAROUSEL -->\r\n                            <div id=\"agnihotraWorldRecordCarousel\" class=\"carousel slide\" data-bs-ride=\"carousel\"\r\n                                data-bs-interval=\"4500\">\r\n\r\n                                <!-- INDICATORS -->\r\n                                <div class=\"carousel-indicators mb-1\">\r\n                                    <button type=\"button\" data-bs-target=\"#agnihotraWorldRecordCarousel\"\r\n                                        data-bs-slide-to=\"0\" class=\"active ukt-carousel-indicator-gold\"\r\n                                        aria-current=\"true\" aria-label=\"Slide 1\"></button>\r\n                                    <button type=\"button\" data-bs-target=\"#agnihotraWorldRecordCarousel\"\r\n                                        data-bs-slide-to=\"1\" class=\"ukt-carousel-indicator-gold\"\r\n                                        aria-label=\"Slide 2\"></button>\r\n                                </div>\r\n\r\n                                <!-- SLIDES (FLUSH FIT WITHOUT VERTICAL GAP) -->\r\n                                <div class=\"carousel-inner ukt-carousel-inner-rounded\">\r\n                                    <div class=\"carousel-item active\">\r\n                                        <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-world-record/agnihotra-world-record-1.jpg\"\r\n                                            alt=\"Karnataka Agnihotra Spectacular - World Agnihotra Day 2025 Dharwad\"\r\n                                            title=\"Karnataka Agnihotra Spectacular 2025\"\r\n                                            class=\"d-block w-100 img-fluid ukt-agnihotra-carousel-img\">\r\n                                    </div>\r\n                                    <div class=\"carousel-item\">\r\n                                        <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-world-record/agnihotra-world-record-2.jpg\"\r\n                                            alt=\"World Agnihotra Day 2025 World Record Attempt\"\r\n                                            title=\"World Agnihotra Day 2025 Guide\"\r\n                                            class=\"d-block w-100 img-fluid ukt-agnihotra-carousel-img\">\r\n                                    </div>\r\n                                </div>\r\n\r\n                                <!-- CONTROLS -->\r\n                                <button class=\"carousel-control-prev ukt-carousel-control-narrow\" type=\"button\"\r\n                                    data-bs-target=\"#agnihotraWorldRecordCarousel\" data-bs-slide=\"prev\">\r\n                                    <span class=\"carousel-control-prev-icon ukt-carousel-control-icon-circle\"\r\n                                        aria-hidden=\"true\"></span>\r\n                                    <span class=\"visually-hidden\">Previous</span>\r\n                                </button>\r\n                                <button class=\"carousel-control-next ukt-carousel-control-narrow\" type=\"button\"\r\n                                    data-bs-target=\"#agnihotraWorldRecordCarousel\" data-bs-slide=\"next\">\r\n                                    <span class=\"carousel-control-next-icon ukt-carousel-control-icon-circle\"\r\n                                        aria-hidden=\"true\"></span>\r\n                                    <span class=\"visually-hidden\">Next</span>\r\n                                </button>\r\n\r\n                            </div><!-- /#agnihotraWorldRecordCarousel -->\r\n\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- RIGHT COLUMN: CONTENT -->\r\n                <div class=\"col-lg-6 col-md-12\">\r\n                    <div class=\"ps-lg-2\">\r\n                        <div class=\"ukt-section-eyebrow text-start m-0 mb-1\">\r\n                            <span></span>\r\n                            WORLD AGNIHOTRA DAY 2025\r\n                            <span></span>\r\n                        </div>\r\n                        <h2 class=\"ukt-section-main-title ukt-section-title-clamp-md text-start mb-2\">\r\n                            Karnataka Agnihotra Spectacular <span> – World record Agnihotra Spectacular 2025\r\n                                🔥</span>\r\n                        </h2>\r\n                        <div class=\"ukt-section-heading-design m-0 mb-2 justify-content-start\">\r\n                            <span></span>\r\n                            <i class=\"bi bi-fire\"></i>\r\n                            <span></span>\r\n                        </div>\r\n\r\n                        <p class=\"ukt-agnihotra-record-text\">\r\n                            We wish for you to join us on this journey, and hence, this special invitation is\r\n                            extended to you.\r\n                        </p>\r\n\r\n                        <p class=\"ukt-agnihotra-record-text-sm\">\r\n                            On <strong>13th April 2025, at Dharwad</strong>,<br>\r\n                            Please join us in hosting a grand Agnihotra world record event with <strong>10,000+\r\n                                participants</strong>, who will do Agnihotra at a single location.<br>\r\n                            This is been organized by <strong>Gram Vikas Society</strong> and <strong>Universal\r\n                                Knowledge Trust</strong>.\r\n                        </p>\r\n\r\n                        <p class=\"ukt-agnihotra-record-text-sm\">\r\n                            Let’s come together to experience this beautiful ancient practice that brings peace,\r\n                            harmony, and positivity to our lives and the world.\r\n                        </p>\r\n\r\n                        <!-- CALLOUT: GATHERING & SPARK -->\r\n                        <div class=\"ukt-agnihotra-gratitude-box mb-3\">\r\n                            <p class=\"ukt-agnihotra-gratitude-tagline ukt-agnihotra-tagline-normal mb-1\">\r\n                                ✨ Be a part of this incredible gathering and become an Agnihotri! ✨\r\n                            </p>\r\n                            <p class=\"ukt-agnihotra-gratitude-text mb-0\">\r\n                                Let’s light the fire of transformation and unity.\r\n                            </p>\r\n                        </div>\r\n\r\n                        <p class=\"ukt-agnihotra-record-text-sm mb-2\">\r\n                            📅 <strong>Event Date:</strong> 13th April 2025 &nbsp;&nbsp; 📍\r\n                            <strong>Location:</strong> Dharwad\r\n                        </p>\r\n\r\n                        <p class=\"ukt-agnihotra-record-text ukt-agnihotra-record-highlight fw-semibold mb-3\">\r\n                            Together, let’s make a difference! 🙏\r\n                        </p>\r\n\r\n                        <!-- EVENT DETAILS CARD -->\r\n                        <div class=\"ukt-agnihotra-event-card mb-3\">\r\n                            <h4 class=\"ukt-agnihotra-event-card-title fw-bold mb-1\">\r\n                                KARNATAKA AGNIHOTRA SPECTACULAR,\r\n                            </h4>\r\n                            <p class=\"ukt-agnihotra-event-card-desc mb-2\">\r\n                                an initiative by GVS powered by UKT to celebrate<br>\r\n                                <strong>WORLD AGNIHOTRA DAY on 13th April 2025.</strong>\r\n                            </p>\r\n                            <p class=\"ukt-agnihotra-event-card-stat mb-1 fw-bold\">\r\n                                11,111+ Agnihotris, 11,111+ Locations, 111+ Consecutive Days of Agnihotra\r\n                            </p>\r\n                            <p class=\"ukt-agnihotra-event-card-record mb-0 fw-bold\">\r\n                                Leading to CREATION OF WORLD 🌍 RECORD.\r\n                            </p>\r\n                        </div>\r\n\r\n                        <p class=\"ukt-agnihotra-record-text-sm mb-2\">\r\n                            If you are interested in join this event and ready to do Agnihotra in your\r\n                            house/workspace, you can register\r\n                        </p>\r\n\r\n                        <div class=\"ukt-agnihotra-free-kit-badge mb-3\">\r\n                            🎁 First Registered 11,111 Residents of Karnataka to get FREE START UP AGNIHOTRA KIT\r\n                        </div>\r\n\r\n                        <!-- GRATITUDE & SIGN-OFF BANNER -->\r\n                        <div class=\"ukt-agnihotra-gratitude-box\">\r\n                            <p class=\"ukt-agnihotra-gratitude-text mb-0\">\r\n                                Thanks, Regards, Team GVS &amp; UKT\r\n                            </p>\r\n                        </div>\r\n\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         SECTION 1: PHILOSOPHY & ORIGIN OF AGNIHOTRA\r\n    ========================================================== -->\r\n    <section class=\"py-4 py-lg-5 ukt-section-bg-white\">\r\n        <div class=\"container py-lg-2\">\r\n            <div class=\"row align-items-center justify-content-between g-3 g-lg-4 mb-4\">\r\n\r\n                <div class=\"col-lg-7 col-md-12\">\r\n                    <div class=\"pe-0 pe-lg-3\">\r\n                        <div class=\"ukt-section-eyebrow text-start m-0 mb-2\">\r\n                            <span></span>\r\n                            SACRED VEDIC ROOTS\r\n                            <span></span>\r\n                        </div>\r\n                        <h2 class=\"ukt-section-main-title mb-3\">\r\n                            The Sacred Fire Offering: <span>Agnihotra</span>\r\n                        </h2>\r\n                        <div class=\"ukt-section-heading-design m-0 mb-3 justify-content-start\">\r\n                            <span></span>\r\n                            <i class=\"bi bi-flower1\"></i>\r\n                            <span></span>\r\n                        </div>\r\n\r\n                        <p class=\"ukt-agnihotra-intro-text\">\r\n                            The <strong>Agnihotri practice</strong>, also known as <strong>Agnihotra</strong>, is an\r\n                            ancient Vedic fire ritual that has its origins in the early Vedic period of the Indian\r\n                            subcontinent. It is one of the oldest and most sacred rituals in Hinduism, deeply rooted\r\n                            in the Vedic tradition.\r\n                        </p>\r\n\r\n                        <p class=\"ukt-agnihotra-intro-text-last\">\r\n                            The Agnihotri practice originates from the Vedic period of ancient India and is closely\r\n                            linked to Vedic rituals and the Agnihotra fire sacrifice. The term\r\n                            <strong>Agnihotri</strong> refers to a Brahmin who performs the Agnihotra ritual daily\r\n                            and maintains the sacred fire (Agni) as part of their spiritual and priestly duties.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n                <div\r\n                    class=\"col-lg-5 col-md-12 d-flex align-items-center justify-content-center justify-content-lg-center\">\r\n                    <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-img-191x300.jpg\"\r\n                        alt=\"Karnataka Agnihotra Spectacular - Universal Knowledge Trust\"\r\n                        class=\"ukt-agnihotra-poster-img\">\r\n                </div>\r\n\r\n            </div>\r\n\r\n            <!-- ORIGINS OF THE AGNIHOTRI PRACTICE -->\r\n            <div class=\"ukt-practical-unified-card mt-3 mb-4 text-start\">\r\n                <div class=\"ukt-practical-accent-bar\"></div>\r\n                <h3 class=\"ukt-practical-title mb-3\">\r\n                    <i class=\"bi bi-fire ukt-icon-gold\"></i> Origins of the Agnihotri Practice:\r\n                </h3>\r\n\r\n                <!-- 1. Vedic Foundations -->\r\n                <div class=\"mb-3\">\r\n                    <h4 class=\"ukt-agnihotri-origin-subtitle fw-bold mb-2\">\r\n                        1. Vedic Foundations (c. 1500–500 BCE):\r\n                    </h4>\r\n                    <ul class=\"ukt-practical-list-nomargin\">\r\n                        <li class=\"ukt-practical-list-item\">\r\n                            <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                            <div>The Agnihotra is a fire ritual mentioned in the Rigveda, Yajurveda, and\r\n                                Atharvaveda.</div>\r\n                        </li>\r\n                        <li class=\"ukt-practical-list-item\">\r\n                            <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                            <div>It was performed at sunrise and sunset to honor Agni, the fire deity, and maintain\r\n                                cosmic balance.</div>\r\n                        </li>\r\n                        <li class=\"ukt-practical-list-item\">\r\n                            <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                            <div>The Agnihotri was a specialized priest responsible for conducting these rituals.\r\n                            </div>\r\n                        </li>\r\n                    </ul>\r\n                </div>\r\n\r\n                <!-- 2. Brahmanical Tradition -->\r\n                <div class=\"mb-3\">\r\n                    <h4 class=\"ukt-agnihotri-origin-subtitle fw-bold mb-2\">\r\n                        2. Brahmanical Tradition:\r\n                    </h4>\r\n                    <ul class=\"ukt-practical-list-nomargin\">\r\n                        <li class=\"ukt-practical-list-item\">\r\n                            <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                            <div>The Agnihotris were part of the Shrauta tradition, which involved elaborate fire\r\n                                sacrifices (Yajnas).</div>\r\n                        </li>\r\n                        <li class=\"ukt-practical-list-item\">\r\n                            <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                            <div>They played a significant role in royal and temple rituals, ensuring the continuity\r\n                                of Vedic traditions.</div>\r\n                        </li>\r\n                    </ul>\r\n                </div>\r\n\r\n                <!-- 3. Smritis and Dharmashastra Influence -->\r\n                <div class=\"mb-3\">\r\n                    <h4 class=\"ukt-agnihotri-origin-subtitle fw-bold mb-2\">\r\n                        3. Smritis and Dharmashastra Influence (c. 500 BCE – 500 CE):\r\n                    </h4>\r\n                    <ul class=\"ukt-practical-list-nomargin\">\r\n                        <li class=\"ukt-practical-list-item\">\r\n                            <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                            <div>Texts like the Manusmriti and Baudhayana Dharma Sutra emphasized the importance of\r\n                                Agnihotra in daily life.</div>\r\n                        </li>\r\n                        <li class=\"ukt-practical-list-item\">\r\n                            <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                            <div>The practice was considered a compulsory duty (Nitya Karma) for Brahmins devoted to\r\n                                Vedic rituals.</div>\r\n                        </li>\r\n                    </ul>\r\n                </div>\r\n\r\n                <!-- 4. Medieval and Modern Continuation -->\r\n                <div class=\"mb-0\">\r\n                    <h4 class=\"ukt-agnihotri-origin-subtitle fw-bold mb-2\">\r\n                        4. Medieval and Modern Continuation:\r\n                    </h4>\r\n                    <ul class=\"ukt-practical-list-nomargin\">\r\n                        <li class=\"ukt-practical-list-item\">\r\n                            <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                            <div>Though large-scale Yajnas declined with the rise of Bhakti and temple-based\r\n                                worship, some Brahmin families continued the Agnihotri tradition.</div>\r\n                        </li>\r\n                        <li class=\"ukt-practical-list-item\">\r\n                            <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                            <div>Even today, certain Brahmin sects in India, such as Namboodiri Brahmins of Kerala\r\n                                and Maharashtrian Brahmins, maintain Agnihotra practices.</div>\r\n                        </li>\r\n                    </ul>\r\n                </div>\r\n\r\n            </div>\r\n\r\n            <!-- CURRENT STATUS OF AGNIHOTRI PRACTICE -->\r\n            <div class=\"ukt-agnihotra-gratitude-box mb-3 p-3 text-start\">\r\n                <h3 class=\"ukt-practical-title ukt-agnihotri-status-title mb-2\">\r\n                    <i class=\"bi bi-geo-alt-fill ukt-icon-gold\"></i> Current Status of Agnihotri Practice:\r\n                </h3>\r\n                <ul class=\"ukt-practical-list-nomargin mb-3\">\r\n                    <li class=\"ukt-practical-list-item\">\r\n                        <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                        <div>Some traditional Agnihotri families still maintain the sacred fire and conduct\r\n                            Agnihotra as part of their daily worship.</div>\r\n                    </li>\r\n                    <li class=\"ukt-practical-list-item\">\r\n                        <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                        <div>The practice has also seen a revival in spiritual and environmental movements, with\r\n                            many promoting Agnihotra for its claimed benefits in purifying air and the atmosphere.\r\n                        </div>\r\n                    </li>\r\n                </ul>\r\n                <p class=\"ukt-agnihotri-inquiry-text m-0 text-muted fst-italic\">\r\n                    Would you like details on any specific aspect of the Agnihotri practice?\r\n                </p>\r\n            </div>\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         SECTION 2: PRIMARY VEDIC SOURCES & AUTHENTIC TEXTS\r\n    ========================================================== -->\r\n    <section class=\"py-5 ukt-vedic-sources-section\" id=\"vedic-sources\">\r\n        <div class=\"container py-lg-4\">\r\n\r\n            <!-- SECTION HEADER -->\r\n            <div class=\"ukt-section-header\">\r\n                <div class=\"ukt-section-eyebrow\">\r\n                    <span></span>\r\n                    CANONICAL SCRIPTURES\r\n                    <span></span>\r\n                </div>\r\n                <h2 class=\"ukt-section-main-title\">\r\n                    Primary <span>Vedic Sources</span>\r\n                </h2>\r\n                <div class=\"ukt-section-heading-design\">\r\n                    <span></span>\r\n                    <i class=\"bi bi-flower1\"></i>\r\n                    <span></span>\r\n                </div>\r\n                <p class=\"ukt-section-lead-text\">\r\n                    The Agni Hotra (or Agnihotra) is an ancient Vedic fire ritual rooted in the Yajurveda. To engage\r\n                    with authentic sources for this practice, consider the following structured approach:\r\n                </p>\r\n            </div>\r\n\r\n            <div class=\"row justify-content-center g-4\">\r\n\r\n                <!-- SOURCE 1: YAJURVEDA -->\r\n                <div class=\"col-lg-4 col-md-6 col-12\">\r\n                    <div class=\"ukt-source-card\">\r\n                        <div class=\"ukt-source-header\">\r\n                            <div class=\"ukt-source-icon-badge\">\r\n                                <i class=\"bi bi-journal-richtext\"></i>\r\n                            </div>\r\n                            <span class=\"ukt-source-tag\">Veda Samhita</span>\r\n                        </div>\r\n                        <h3 class=\"ukt-source-title\">1. Yajurveda</h3>\r\n                        <ul class=\"ukt-source-texts-list\">\r\n                            <li>\r\n                                <i class=\"bi bi-bookmark-check\"></i>\r\n                                <span><strong>Taittiriya Samhita:</strong> Central text detailing fire rituals. The\r\n                                    Agni Hotra is described here, especially in sections related to daily offerings\r\n                                    (sandhyā).</span>\r\n                            </li>\r\n                        </ul>\r\n                        <div class=\"ukt-source-translation-pill\">\r\n                            <strong>Translation:</strong> “The Yajurveda Taittiriya Samhita” by R.L. Kashyap\r\n                            (Sanskrit-English, 2020) provides accessible insights.\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- SOURCE 2: BRAHMANAS -->\r\n                <div class=\"col-lg-4 col-md-6 col-12\">\r\n                    <div class=\"ukt-source-card\">\r\n                        <div class=\"ukt-source-header\">\r\n                            <div class=\"ukt-source-icon-badge\">\r\n                                <i class=\"bi bi-layers\"></i>\r\n                            </div>\r\n                            <span class=\"ukt-source-tag\">Brahmana Texts</span>\r\n                        </div>\r\n                        <h3 class=\"ukt-source-title\">2. Brahmanas</h3>\r\n                        <ul class=\"ukt-source-texts-list\">\r\n                            <li>\r\n                                <i class=\"bi bi-bookmark-check\"></i>\r\n                                <span><strong>Shatapatha Brahmana:</strong> Elaborates on ritual significance. Book\r\n                                    2 discusses Agni Hotra’s symbolism.</span>\r\n                            </li>\r\n                        </ul>\r\n                        <div class=\"ukt-source-translation-pill\">\r\n                            <strong>Translation:</strong> “The Satapatha Brahmana” by Julius Eggeling (Sacred Books\r\n                            of the East series, 1882).\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- SOURCE 3: GRIHYA SUTRAS -->\r\n                <div class=\"col-lg-4 col-md-6 col-12\">\r\n                    <div class=\"ukt-source-card\">\r\n                        <div class=\"ukt-source-header\">\r\n                            <div class=\"ukt-source-icon-badge\">\r\n                                <i class=\"bi bi-house-door\"></i>\r\n                            </div>\r\n                            <span class=\"ukt-source-tag\">Grihya Sutras</span>\r\n                        </div>\r\n                        <h3 class=\"ukt-source-title\">3. Grihya Sutras</h3>\r\n                        <ul class=\"ukt-source-texts-list\">\r\n                            <li>\r\n                                <i class=\"bi bi-bookmark-check\"></i>\r\n                                <span><strong>Apastamba Grihya Sutra:</strong> Outlines domestic rituals, including\r\n                                    Agni Hotra procedures.</span>\r\n                            </li>\r\n                            <li>\r\n                                <i class=\"bi bi-bookmark-check\"></i>\r\n                                <span><strong>Ashvalayana Grihya Sutra:</strong> Another key text for householder\r\n                                    practices.</span>\r\n                            </li>\r\n                        </ul>\r\n                        <div class=\"ukt-source-translation-pill\">\r\n                            <strong>Translation:</strong> “Hindu Domestic Rituals” by H. Oldenberg (1892).\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         SECTION 3: ROLE OF THE AGNIHOTRI & THREE SACRED FIRES\r\n    ========================================================== -->\r\n    <section class=\"py-5 ukt-agnihotri-role-section\">\r\n        <div class=\"container py-lg-4\">\r\n\r\n            <!-- SECTION HEADER -->\r\n            <div class=\"ukt-section-header\">\r\n                <div class=\"ukt-section-eyebrow\">\r\n                    <span></span>\r\n                    VEDIC TRADITION\r\n                    <span></span>\r\n                </div>\r\n                <h2 class=\"ukt-section-main-title\">\r\n                    Role of the <span>Agnihotri</span>\r\n                </h2>\r\n                <div class=\"ukt-section-heading-design\">\r\n                    <span></span>\r\n                    <i class=\"bi bi-flower1\"></i>\r\n                    <span></span>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- CONTENT: SINGLE UNIFIED CARD -->\r\n            <div class=\"ukt-agnihotri-role-card\">\r\n\r\n                <!-- TOP ACCENT BAR -->\r\n                <div class=\"ukt-agnihotri-role-accent\"></div>\r\n\r\n                <!-- INNER PADDING WRAP -->\r\n                <div class=\"ukt-agnihotri-role-body\">\r\n\r\n                    <!-- HEREDITARY DUTY -->\r\n                    <div class=\"ukt-agnihotri-duty-block\">\r\n                        <div class=\"ukt-agnihotri-label-amber\">\r\n                            <i class=\"bi bi-bookmark-star-fill\"></i>\r\n                            HEREDITARY DUTY\r\n                        </div>\r\n                        <p class=\"ukt-agnihotri-prose\">\r\n                            The term <strong class=\"ukt-text-highlight-teal\">Agnihotri</strong> refers to Brahmin\r\n                            families\r\n                            who were entrusted with the responsibility of performing the Agnihotra ritual. These\r\n                            families belonged to specific <strong class=\"ukt-text-highlight-teal\">Vedic Shakhas\r\n                                (schools)</strong> and were trained in the precise recitation of Vedic mantras and\r\n                            the correct performance of the ritual.\r\n                        </p>\r\n                    </div>\r\n\r\n                    <!-- THREE SACRED FIRES -->\r\n                    <div>\r\n                        <div class=\"ukt-agnihotri-label-teal\">\r\n                            <i class=\"bi bi-fire text-warning\"></i>\r\n                            THREE SACRED FIRES\r\n                        </div>\r\n\r\n                        <p class=\"ukt-agnihotri-prose-mb\">\r\n                            The Agnihotri maintained three sacred fires:\r\n                        </p>\r\n\r\n                        <!-- Fire rows -->\r\n                        <div class=\"ukt-fire-rows-list\">\r\n\r\n                            <!-- GARHAPATYA -->\r\n                            <div class=\"ukt-fire-row-item-garhapatya\">\r\n                                <div class=\"ukt-fire-row-icon-orange\">\r\n                                    <i class=\"bi bi-house-heart-fill\"></i>\r\n                                </div>\r\n                                <div>\r\n                                    <span class=\"ukt-fire-row-name\">Garhapatya</span>\r\n                                    <span class=\"ukt-fire-row-type\">(household fire)</span>\r\n                                </div>\r\n                            </div>\r\n\r\n                            <!-- DAKSHINAGNI -->\r\n                            <div class=\"ukt-fire-row-item-dakshinagni\">\r\n                                <div class=\"ukt-fire-row-icon-teal\">\r\n                                    <i class=\"bi bi-compass-fill\"></i>\r\n                                </div>\r\n                                <div>\r\n                                    <span class=\"ukt-fire-row-name\">Dakshinagni</span>\r\n                                    <span class=\"ukt-fire-row-type\">(southern fire)</span>\r\n                                </div>\r\n                            </div>\r\n\r\n                            <!-- AHAVANIYA -->\r\n                            <div class=\"ukt-fire-row-item-ahavaniya\">\r\n                                <div class=\"ukt-fire-row-icon-gold\">\r\n                                    <i class=\"bi bi-stars\"></i>\r\n                                </div>\r\n                                <div>\r\n                                    <span class=\"ukt-fire-row-name\">Ahavaniya</span>\r\n                                    <span class=\"ukt-fire-row-type\">(offering fire)</span>\r\n                                </div>\r\n                            </div>\r\n\r\n                        </div><!-- /.fire rows -->\r\n\r\n                        <!-- Closing statement -->\r\n                        <div class=\"ukt-fire-closing-note\">\r\n                            <p>\r\n                                These fires symbolized different aspects of life and the cosmos.\r\n                            </p>\r\n                        </div>\r\n\r\n                    </div><!-- /.three sacred fires -->\r\n\r\n                </div><!-- /.inner padding wrap -->\r\n\r\n            </div><!-- /.unified card -->\r\n\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         SECTION 4: HISTORICAL TIMELINE (1500 BCE - PRESENT)\r\n    ========================================================== -->\r\n    <section class=\"py-5 ukt-vedic-sources-section\">\r\n        <div class=\"container py-lg-4\">\r\n\r\n            <!-- SECTION HEADER -->\r\n            <div class=\"ukt-section-header\">\r\n                <div class=\"ukt-section-eyebrow\">\r\n                    <span></span>\r\n                    HISTORICAL EVOLUTION\r\n                    <span></span>\r\n                </div>\r\n                <h2 class=\"ukt-section-main-title\">\r\n                    Timeline of the <span>Agnihotri Tradition</span>\r\n                </h2>\r\n                <div class=\"ukt-section-heading-design\">\r\n                    <span></span>\r\n                    <i class=\"bi bi-flower1\"></i>\r\n                    <span></span>\r\n                </div>\r\n                <p class=\"ukt-section-lead-text\">\r\n                    How the sacred fire practice evolved from ancient Vedic Shrauta sacrifices to its modern\r\n                    ecological and therapeutic revival worldwide.\r\n                </p>\r\n            </div>\r\n\r\n            <div class=\"ukt-timeline-container\">\r\n\r\n                <!-- ERA 1: VEDIC ORIGINS -->\r\n                <div class=\"ukt-timeline-item\">\r\n                    <div class=\"ukt-timeline-dot\"></div>\r\n                    <div class=\"ukt-timeline-card\">\r\n                        <span class=\"ukt-timeline-era\">c. 1500 – 500 BCE</span>\r\n                        <h3 class=\"ukt-timeline-title\">1. Vedic Origins</h3>\r\n                        <div class=\"ukt-timeline-text-wrap\">\r\n                            <p class=\"ukt-timeline-text\">\r\n                                <strong>Source in the Vedas:</strong> The Agnihotra ritual is explicitly mentioned\r\n                                in the Yajurveda, particularly in the Shukla Yajurveda, and is elaborated upon in\r\n                                the Brahmana texts, such as the Shatapatha Brahmana. These texts provide detailed\r\n                                instructions on how to perform the ritual.\r\n                            </p>\r\n                            <p class=\"ukt-timeline-text ukt-timeline-text-spacing\">\r\n                                <strong>Purpose and Symbolism:</strong> The ritual involves offering oblations (such\r\n                                as milk, ghee, or grains) into a sacred fire at sunrise and sunset. It is performed\r\n                                to honor Agni (the fire god) and Surya (the sun god), who are considered essential\r\n                                for maintaining cosmic order (<em>ṛta</em>). Agni, as the divine messenger, carries\r\n                                the offerings to the gods, ensuring harmony between the human and divine realms.\r\n                            </p>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- ERA 2: POST-VEDIC PERIOD -->\r\n                <div class=\"ukt-timeline-item\">\r\n                    <div class=\"ukt-timeline-dot\"></div>\r\n                    <div class=\"ukt-timeline-card\">\r\n                        <span class=\"ukt-timeline-era\">c. 500 BCE – 500 CE</span>\r\n                        <h3 class=\"ukt-timeline-title\">2. Post-Vedic Period</h3>\r\n                        <div class=\"ukt-timeline-text-wrap\">\r\n                            <p class=\"ukt-timeline-text\">\r\n                                <strong>Codification in Grihya Sutras:</strong> During this period, the Agnihotra\r\n                                was codified in the Grihya Sutras, which are texts dealing with domestic rituals.\r\n                                The ritual became more accessible to householders (<em>grhasthas</em>) and was\r\n                                integrated into daily life.\r\n                            </p>\r\n                            <p class=\"ukt-timeline-text ukt-timeline-text-spacing\">\r\n                                <strong>Philosophical Shifts:</strong> With the rise of the Upanishads, there was a\r\n                                shift from external rituals to internal spiritual practices. However, the Agnihotra\r\n                                continued to be practiced as a symbolic act of maintaining cosmic and social order.\r\n                            </p>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- ERA 3: MEDIEVAL PERIOD -->\r\n                <div class=\"ukt-timeline-item\">\r\n                    <div class=\"ukt-timeline-dot\"></div>\r\n                    <div class=\"ukt-timeline-card\">\r\n                        <span class=\"ukt-timeline-era\">c. 500 – 1500 CE</span>\r\n                        <h3 class=\"ukt-timeline-title\">3. Medieval Period</h3>\r\n                        <div class=\"ukt-timeline-text-wrap\">\r\n                            <p class=\"ukt-timeline-text\">\r\n                                <strong>Continuity Amidst Change:</strong> Despite the rise of Buddhism, Jainism,\r\n                                and later Islam, the Agnihotri tradition was preserved by Brahmin families,\r\n                                particularly in regions like Maharashtra, Gujarat, and Bengal. These families\r\n                                maintained the ritual as part of their cultural and religious identity.\r\n                            </p>\r\n                            <p class=\"ukt-timeline-text ukt-timeline-text-spacing\">\r\n                                <strong>Integration into Temple Rituals:</strong> The Agnihotra also found its way\r\n                                into temple rituals, where it was performed as part of larger ceremonies.\r\n                            </p>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- ERA 4: MODERN ERA -->\r\n                <div class=\"ukt-timeline-item\">\r\n                    <div class=\"ukt-timeline-dot\"></div>\r\n                    <div class=\"ukt-timeline-card\">\r\n                        <span class=\"ukt-timeline-era\">19th Century – Present</span>\r\n                        <h3 class=\"ukt-timeline-title\">4. Modern Era</h3>\r\n                        <div class=\"ukt-timeline-text-wrap\">\r\n                            <p class=\"ukt-timeline-text\">\r\n                                <strong>Revival and Adaptation:</strong> In the 19th and 20th centuries, movements\r\n                                like the Arya Samaj sought to revive Vedic practices, including the Agnihotra. In\r\n                                contemporary times, the ritual has been reinterpreted by spiritual groups for its\r\n                                ecological and therapeutic benefits. For example, some practitioners claim that the\r\n                                ritual purifies the environment and promotes mental well-being.\r\n                            </p>\r\n                            <p class=\"ukt-timeline-text ukt-timeline-text-spacing\">\r\n                                <strong>Global Spread:</strong> The Agnihotra has gained followers outside India,\r\n                                with people around the world adopting it as a form of spiritual and ecological\r\n                                practice.\r\n                            </p>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- KEY TAKEAWAYS -->\r\n                <div class=\"ukt-timeline-item\">\r\n                    <div class=\"ukt-timeline-dot\"></div>\r\n                    <div class=\"ukt-timeline-card\">\r\n                        <span class=\"ukt-timeline-era\">Summary</span>\r\n                        <h3 class=\"ukt-timeline-title\">Key Takeaways</h3>\r\n                        <div class=\"ukt-timeline-text-wrap\">\r\n                            <p class=\"ukt-timeline-text\">\r\n                                – The Agnihotri practice originated in the Vedic period as a fire ritual to honor\r\n                                Agni and Surya, maintaining cosmic order.\r\n                            </p>\r\n                            <p class=\"ukt-timeline-text ukt-timeline-text-spacing\">\r\n                                – It was preserved by Brahmin families and adapted over time, surviving through\r\n                                various cultural and religious shifts.\r\n                            </p>\r\n                            <p class=\"ukt-timeline-text ukt-timeline-text-spacing\">\r\n                                – Today, it continues to be practiced both in its traditional form and as a modern\r\n                                spiritual and ecological ritual.\r\n                            </p>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         SECTION 6: HOW TO PERFORM AGNIHOTRA\r\n    ========================================================== -->\r\n    <section id=\"agnihotra_procedure\" class=\"py-5 ukt-procedure-section\">\r\n        <div class=\"container py-lg-4\">\r\n\r\n            <!-- SECTION HEADER -->\r\n            <div class=\"ukt-section-header\">\r\n                <div class=\"ukt-section-eyebrow\">\r\n                    <span></span>\r\n                    STEP-BY-STEP RITUAL GUIDE\r\n                    <span></span>\r\n                </div>\r\n                <h2 class=\"ukt-section-main-title\">\r\n                    How to Perform <span>Agnihotra</span>\r\n                </h2>\r\n                <div class=\"ukt-section-heading-design\">\r\n                    <span></span>\r\n                    <i class=\"bi bi-flower1\"></i>\r\n                    <span></span>\r\n                </div>\r\n                <p class=\"ukt-section-lead-text\">\r\n                    Angihotra, also known as Agnihotra, is an ancient Vedic fire ritual originating from India. It’s\r\n                    a powerful practice for physical, mental, and spiritual well-being. Here’s a step-by-step guide:\r\n                </p>\r\n            </div>\r\n\r\n            <!-- ROW 1: MERGED CARDS (MATERIALS & PREPARATION + TIPS & BENEFITS) -->\r\n            <div class=\"row g-4 align-items-stretch mb-4 text-start\">\r\n\r\n                <!-- MERGED DIV 1: MATERIALS NEEDED & PREPARATION -->\r\n                <div class=\"col-lg-6\">\r\n                    <div class=\"ukt-procedure-card-materials\">\r\n                        <div class=\"ukt-procedure-card-accent-gold\"></div>\r\n\r\n                        <div>\r\n                            <!-- Materials Needed -->\r\n                            <div class=\"d-flex align-items-center gap-3 mb-3\">\r\n                                <div class=\"ukt-procedure-icon-gold\">\r\n                                    <i class=\"bi bi-box-seam-fill\"></i>\r\n                                </div>\r\n                                <div>\r\n                                    <div class=\"ukt-procedure-kicker-amber\">\r\n                                        ESSENTIALS</div>\r\n                                    <h3 class=\"ukt-procedure-card-title\">\r\n                                        Materials Needed</h3>\r\n                                </div>\r\n                            </div>\r\n                            <div class=\"row g-2 mb-4\">\r\n                                <div class=\"col-sm-6\">\r\n                                    <div class=\"ukt-procedure-material-box\">\r\n                                        <i class=\"bi bi-triangle-fill ukt-procedure-icon-gold-sm\"></i>\r\n                                        <span>Copper pyramid (specifically designed for Agnihotra)</span>\r\n                                    </div>\r\n                                </div>\r\n                                <div class=\"col-sm-6\">\r\n                                    <div class=\"ukt-procedure-material-box\">\r\n                                        <i class=\"bi bi-droplet-fill ukt-procedure-icon-gold-sm\"></i>\r\n                                        <span>Ghee (clarified butter)</span>\r\n                                    </div>\r\n                                </div>\r\n                                <div class=\"col-sm-6\">\r\n                                    <div class=\"ukt-procedure-material-box\">\r\n                                        <i class=\"bi bi-circle-fill ukt-procedure-icon-gold-xs\"></i>\r\n                                        <span>Rice grains</span>\r\n                                    </div>\r\n                                </div>\r\n                                <div class=\"col-sm-6\">\r\n                                    <div class=\"ukt-procedure-material-box\">\r\n                                        <i class=\"bi bi-fire ukt-procedure-icon-gold-sm\"></i>\r\n                                        <span>Cow dung cakes</span>\r\n                                    </div>\r\n                                </div>\r\n                                <div class=\"col-sm-6\">\r\n                                    <div class=\"ukt-procedure-material-box\">\r\n                                        <i class=\"bi bi-lightning-charge-fill ukt-procedure-icon-gold-sm\"></i>\r\n                                        <span>Matches or a lighter</span>\r\n                                    </div>\r\n                                </div>\r\n                                <div class=\"col-sm-6\">\r\n                                    <div class=\"ukt-procedure-material-box\">\r\n                                        <i class=\"bi bi-clock-fill ukt-procedure-icon-gold-sm\"></i>\r\n                                        <span>Timing device (to synchronize with sunrise/sunset)</span>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n\r\n                            <!-- Divider -->\r\n                            <div class=\"ukt-procedure-divider\"></div>\r\n\r\n                            <!-- Preparation -->\r\n                            <div class=\"d-flex align-items-center gap-3 mb-3\">\r\n                                <div class=\"ukt-procedure-icon-teal\">\r\n                                    <i class=\"bi bi-clipboard2-check-fill\"></i>\r\n                                </div>\r\n                                <div>\r\n                                    <div class=\"ukt-procedure-kicker-cyan\">\r\n                                        SETTING UP</div>\r\n                                    <h3 class=\"ukt-procedure-card-title\">\r\n                                        Preparation</h3>\r\n                                </div>\r\n                            </div>\r\n                            <div class=\"ukt-procedure-steps-wrap\">\r\n                                <div class=\"ukt-procedure-step-row\">\r\n                                    <div class=\"ukt-procedure-step-badge-teal\">1</div>\r\n                                    <p class=\"ukt-procedure-step-desc\">\r\n                                        Choose a quiet, clean space for performing the ritual.</p>\r\n                                </div>\r\n                                <div class=\"ukt-procedure-step-row\">\r\n                                    <div class=\"ukt-procedure-step-badge-teal\">2</div>\r\n                                    <p class=\"ukt-procedure-step-desc\">\r\n                                        Set up the copper pyramid on a safe, heat-resistant surface.</p>\r\n                                </div>\r\n                                <div class=\"ukt-procedure-step-row\">\r\n                                    <div class=\"ukt-procedure-step-badge-teal\">3</div>\r\n                                    <p class=\"ukt-procedure-step-desc\">\r\n                                        Prepare ghee and rice grains beforehand.</p>\r\n                                </div>\r\n                                <div class=\"text-center pt-2\">\r\n                                    <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-world-record/31-U3L5RSFL-300x236-1.webp\"\r\n                                        alt=\"Agnihotra Copper Pyramid Kit\" title=\"Agnihotra Copper Pyramid Kit\"\r\n                                        class=\"img-fluid rounded ukt-procedure-kit-img\">\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- MERGED DIV 2: TIPS, PRECAUTIONS & BENEFITS -->\r\n                <div class=\"col-lg-6\">\r\n                    <div class=\"ukt-procedure-card-tips\">\r\n                        <div class=\"ukt-procedure-card-accent-multi\"></div>\r\n\r\n                        <div>\r\n                            <!-- Tips & Precautions -->\r\n                            <div class=\"d-flex align-items-center gap-3 mb-3\">\r\n                                <div class=\"ukt-procedure-icon-teal-cyan\">\r\n                                    <i class=\"bi bi-shield-fill-check\"></i>\r\n                                </div>\r\n                                <div>\r\n                                    <div class=\"ukt-procedure-kicker-cyan\">\r\n                                        GUIDELINES &amp; SAFETY</div>\r\n                                    <h3 class=\"ukt-procedure-card-title\">\r\n                                        Tips and Precautions</h3>\r\n                                </div>\r\n                            </div>\r\n                            <div class=\"ukt-procedure-guidelines-wrap\">\r\n                                <div class=\"ukt-procedure-guideline-item\">\r\n                                    <i class=\"bi bi-alarm-fill ukt-procedure-icon-cyan-sm\"></i>\r\n                                    <span>1. Use a timer to synchronize with sunrise/sunset.</span>\r\n                                </div>\r\n                                <div class=\"ukt-procedure-guideline-item\">\r\n                                    <i class=\"bi bi-calendar-check-fill ukt-procedure-icon-cyan-sm\"></i>\r\n                                    <span>2. Maintain a consistent schedule.</span>\r\n                                </div>\r\n                                <div class=\"ukt-procedure-guideline-item\">\r\n                                    <i class=\"bi bi-sparkles ukt-procedure-icon-cyan-sm\"></i>\r\n                                    <span>3. Keep the area clean and free from distractions.</span>\r\n                                </div>\r\n                                <div class=\"ukt-procedure-guideline-item-danger\">\r\n                                    <i class=\"bi bi-exclamation-triangle-fill ukt-procedure-icon-danger-sm\"></i>\r\n                                    <span>4. Avoid performing Agnihotra during menstruation or when feeling\r\n                                        unwell.</span>\r\n                                </div>\r\n                                <div class=\"ukt-procedure-guideline-item\">\r\n                                    <i class=\"bi bi-fire ukt-procedure-icon-gold-mid\"></i>\r\n                                    <span>5. Respect the fire and handle it carefully.</span>\r\n                                </div>\r\n                            </div>\r\n\r\n                            <!-- Divider -->\r\n                            <div class=\"ukt-procedure-divider\"></div>\r\n\r\n                            <!-- Benefits -->\r\n                            <div class=\"d-flex align-items-center gap-3 mb-3\">\r\n                                <div class=\"ukt-procedure-icon-gold-teal\">\r\n                                    <i class=\"bi bi-stars\"></i>\r\n                                </div>\r\n                                <div>\r\n                                    <div class=\"ukt-procedure-kicker-amber\">\r\n                                        TRANSFORMATION</div>\r\n                                    <h3 class=\"ukt-procedure-card-title\">\r\n                                        Benefits</h3>\r\n                                </div>\r\n                            </div>\r\n                            <div class=\"row g-2 mb-3\">\r\n                                <div class=\"col-sm-6\">\r\n                                    <div class=\"ukt-procedure-benefit-pill\">\r\n                                        <i class=\"bi bi-wind\"></i> 1. Purifies the environment\r\n                                    </div>\r\n                                </div>\r\n                                <div class=\"col-sm-6\">\r\n                                    <div class=\"ukt-procedure-benefit-pill\">\r\n                                        <i class=\"bi bi-brain\"></i> 2. Improves mental clarity and focus\r\n                                    </div>\r\n                                </div>\r\n                                <div class=\"col-sm-6\">\r\n                                    <div class=\"ukt-procedure-benefit-pill\">\r\n                                        <i class=\"bi bi-heart-pulse-fill\"></i> 3. Enhances physical health\r\n                                    </div>\r\n                                </div>\r\n                                <div class=\"col-sm-6\">\r\n                                    <div class=\"ukt-procedure-benefit-pill\">\r\n                                        <i class=\"bi bi-emoji-smile-fill\"></i> 4. Reduces stress and anxiety\r\n                                    </div>\r\n                                </div>\r\n                                <div class=\"col-12\">\r\n                                    <div class=\"ukt-procedure-benefit-pill\">\r\n                                        <i class=\"bi bi-flower2\"></i> 5. Promotes spiritual growth\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n            </div><!-- /.row 1 -->\r\n\r\n            <!-- ROW 2: PROCEDURES (SUNRISE & SUNSET) -->\r\n            <div class=\"row g-4 align-items-stretch text-start\">\r\n\r\n                <!-- SUNRISE AGNIHOTRA -->\r\n                <div class=\"col-lg-6\">\r\n                    <div class=\"ukt-procedure-card-sunrise text-start\">\r\n                        <div class=\"ukt-procedure-card-accent-orange\"></div>\r\n                        <div class=\"d-flex align-items-center gap-3 mb-4\">\r\n                            <div class=\"ukt-procedure-icon-orange\">\r\n                                <i class=\"bi bi-sunrise-fill\"></i>\r\n                            </div>\r\n                            <div>\r\n                                <div class=\"ukt-procedure-kicker-amber mb-1\">\r\n                                    MORNING RITUAL</div>\r\n                                <h3 class=\"ukt-procedure-card-title-lg\">\r\n                                    Sunrise Agnihotra</h3>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"ukt-procedure-steps-gap\">\r\n                            <div class=\"ukt-procedure-step-row\">\r\n                                <span class=\"ukt-procedure-step-badge-orange\">1</span>\r\n                                <p class=\"ukt-procedure-step-desc\">\r\n                                    Calculate local sunrise time.</p>\r\n                            </div>\r\n                            <div class=\"ukt-procedure-step-row\">\r\n                                <span class=\"ukt-procedure-step-badge-orange\">2</span>\r\n                                <p class=\"ukt-procedure-step-desc\">\r\n                                    Light the fire 10-15 minutes before sunrise.</p>\r\n                            </div>\r\n                            <div class=\"ukt-procedure-step-row\">\r\n                                <span class=\"ukt-procedure-step-badge-orange\">3</span>\r\n                                <p class=\"ukt-procedure-step-desc\">\r\n                                    Add 2-3 pinches of rice grains to the fire.</p>\r\n                            </div>\r\n                            <div class=\"ukt-procedure-step-row\">\r\n                                <span class=\"ukt-procedure-step-badge-orange\">4</span>\r\n                                <p class=\"ukt-procedure-step-desc\">\r\n                                    Add 2-3 drops of ghee to the fire.</p>\r\n                            </div>\r\n                            <div class=\"ukt-procedure-step-row\">\r\n                                <span class=\"ukt-procedure-step-badge-orange\">5</span>\r\n                                <p class=\"ukt-procedure-step-desc\">\r\n                                    Recite the 2 mantras:</p>\r\n                            </div>\r\n                            <div class=\"ukt-procedure-step-row\">\r\n                                <span class=\"ukt-procedure-step-badge-orange\">6</span>\r\n                                <p class=\"ukt-procedure-step-desc\">\r\n                                    . Repeat steps 3-5 for 10-15 minutes.</p>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- SUNSET AGNIHOTRA -->\r\n                <div class=\"col-lg-6\">\r\n                    <div class=\"ukt-procedure-card-sunset\">\r\n                        <div class=\"ukt-procedure-card-accent-purple\"></div>\r\n                        <div class=\"d-flex align-items-center gap-3 mb-4\">\r\n                            <div class=\"ukt-procedure-icon-purple\">\r\n                                <i class=\"bi bi-sunset-fill\"></i>\r\n                            </div>\r\n                            <div>\r\n                                <div class=\"ukt-procedure-kicker-purple\">\r\n                                    EVENING RITUAL</div>\r\n                                <h3 class=\"ukt-procedure-card-title-lg\">\r\n                                    Sunset Agnihotra</h3>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"ukt-procedure-steps-gap\">\r\n                            <div class=\"ukt-procedure-step-row\">\r\n                                <span class=\"ukt-procedure-step-badge-purple\">1</span>\r\n                                <p class=\"ukt-procedure-step-desc\">\r\n                                    Calculate local sunset time.</p>\r\n                            </div>\r\n                            <div class=\"ukt-procedure-step-row\">\r\n                                <span class=\"ukt-procedure-step-badge-purple\">2</span>\r\n                                <p class=\"ukt-procedure-step-desc\">\r\n                                    Light the fire 10-15 minutes before sunset.</p>\r\n                            </div>\r\n                            <div class=\"ukt-procedure-step-row\">\r\n                                <span class=\"ukt-procedure-step-badge-purple\">3</span>\r\n                                <p class=\"ukt-procedure-step-desc\">\r\n                                    Add 2-3 pinches of rice grains to the fire.</p>\r\n                            </div>\r\n                            <div class=\"ukt-procedure-step-row\">\r\n                                <span class=\"ukt-procedure-step-badge-purple\">4</span>\r\n                                <p class=\"ukt-procedure-step-desc\">\r\n                                    Add 2-3 drops of ghee to the fire.</p>\r\n                            </div>\r\n                            <div class=\"ukt-procedure-step-row\">\r\n                                <span class=\"ukt-procedure-step-badge-purple\">5</span>\r\n                                <p class=\"ukt-procedure-step-desc\">\r\n                                    Recite the 2 mantra:</p>\r\n                            </div>\r\n                            <div class=\"ukt-procedure-step-row\">\r\n                                <span class=\"ukt-procedure-step-badge-purple\">6</span>\r\n                                <p class=\"ukt-procedure-step-desc\">\r\n                                    Repeat steps 3-5 for 10-15 minutes.</p>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n            </div><!-- /.row 2 -->\r\n\r\n            <!-- RESOURCES -->\r\n            <div class=\"ukt-practical-unified-card mt-4 mb-3 text-start\">\r\n                <div class=\"ukt-practical-accent-bar\"></div>\r\n                <h3 class=\"ukt-practical-title ukt-practical-title-md mb-2\">\r\n                    <i class=\"bi bi-journal-bookmark-fill ukt-icon-gold\"></i> Resources:\r\n                </h3>\r\n                <ul class=\"ukt-practical-list-nomargin\">\r\n                    <li class=\"ukt-practical-list-item\">\r\n                        <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                        <div>1. Consult Vedic texts or experienced practitioners for guidance.</div>\r\n                    </li>\r\n                    <li class=\"ukt-practical-list-item\">\r\n                        <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                        <div>2. Visit <a href=\"http://localhost/universal-knowledge-trust-wordpress/agnihotra-procedures\"\r\n                                class=\"ukt-agnihotra-link-teal fw-bold text-decoration-none\">Agnihotra Procedure</a>\r\n                            for more information.</div>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n\r\n            <!-- CONSISTENCY CALLOUT -->\r\n            <div class=\"ukt-procedure-consistency-box\">\r\n                <i class=\"bi bi-fire me-2\"></i>\r\n                <span>Remember, consistency and sincerity are key to experiencing the benefits of Agnihotra.</span>\r\n            </div>\r\n\r\n            <!-- WORLD RECORD PARTICIPATION PARAGRAPHS -->\r\n            <div class=\"mt-4 text-start\">\r\n                <p class=\"ukt-agnihotra-record-text mb-2\">\r\n                    Gram Vikas Society (GVS) Powered by Universal Knowledge is creating a World Record by lighting\r\n                    Agnihotra at 11,000 + at single location.\r\n                </p>\r\n\r\n                <p class=\"ukt-agnihotra-record-text mb-3\">\r\n                    This is an unique program and we will join to have a Agnihotra done at 11,000 different houses /\r\n                    offices in and around Karnataka\r\n                </p>\r\n\r\n                <h4 class=\"ukt-agnihotra-record-subheading fw-bold mb-2\">\r\n                    How you can be a part of this world record?\r\n                </h4>\r\n\r\n                <p class=\"ukt-agnihotra-record-text mb-2\">\r\n                    If you are willing to participate and have agnihotra done at your house or office daily, you can\r\n                    apply at the link below;\r\n                </p>\r\n\r\n                <p class=\"ukt-agnihotra-record-text mb-2\">\r\n                    Gram Vikas Society (GVS) will provide you with free startup Agnihotra kit, which will include\r\n                    Copper pyramid Bowl, startup material for 4 days worth ₹ 1,250/-.\r\n                </p>\r\n\r\n                <p class=\"ukt-agnihotra-record-text mb-0\">\r\n                    You will need to have Cow Dung, Ghee and unbroken Rice, which is a daily consumption.\r\n                </p>\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         SECTION 5: PRACTICAL CONSIDERATIONS & ACADEMIC STUDIES\r\n    ========================================================== -->\r\n    <section class=\"py-5 ukt-practical-section\">\r\n        <div class=\"container py-lg-4\">\r\n\r\n            <!-- SECTION HEADER -->\r\n            <div class=\"ukt-section-header\">\r\n                <div class=\"ukt-section-eyebrow\">\r\n                    <span></span>\r\n                    RESEARCH &amp; GUIDELINES\r\n                    <span></span>\r\n                </div>\r\n                <h2 class=\"ukt-section-main-title\">\r\n                    Practical Considerations <span>&amp; Academic Studies</span>\r\n                </h2>\r\n                <div class=\"ukt-section-heading-design\">\r\n                    <span></span>\r\n                    <i class=\"bi bi-flower1\"></i>\r\n                    <span></span>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- SINGLE UNIFIED CONTAINER DIV (SIMPLE LIST FORMAT) -->\r\n            <div class=\"ukt-practical-unified-card\">\r\n                <div class=\"ukt-practical-accent-bar\"></div>\r\n\r\n                <div class=\"row g-4 g-lg-5 text-start\">\r\n\r\n                    <!-- LEFT COLUMN: MODERN GUIDES & ACADEMIC WORKS -->\r\n                    <div class=\"col-lg-6\">\r\n\r\n                        <!-- Modern Guides & Commentaries -->\r\n                        <h3 class=\"ukt-practical-title\">\r\n                            <i class=\"bi bi-book-half ukt-icon-gold\"></i> Modern Guides & Commentaries:\r\n                        </h3>\r\n                        <ul class=\"ukt-practical-list\">\r\n                            <li class=\"ukt-practical-list-item\">\r\n                                <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                                <div>\r\n                                    <strong class=\"ukt-text-highlight-teal\">Fivefold Path Mission:</strong> Founded\r\n                                    by Shree\r\n                                    Vasant Paranjpe, this organization promotes Agni Hotra. Their handbook,\r\n                                    “Agnihotra: The Ultimate Homa Therapy”, blends tradition with practical\r\n                                    guidance.\r\n                                </div>\r\n                            </li>\r\n                        </ul>\r\n\r\n                        <!-- Academic Works -->\r\n                        <h3 class=\"ukt-practical-title\">\r\n                            <i class=\"bi bi-mortarboard-fill ukt-icon-cyan\"></i> Academic Works:\r\n                        </h3>\r\n                        <ul class=\"ukt-practical-list\">\r\n                            <li class=\"ukt-practical-list-item\">\r\n                                <i class=\"bi bi-circle-fill ukt-practical-dot-cyan\"></i>\r\n                                <div>\r\n                                    “Agni: The Vedic Ritual of the Fire Altar” by Frits Staal (1983) analyzes ritual\r\n                                    structures.\r\n                                </div>\r\n                            </li>\r\n                            <li class=\"ukt-practical-list-item\">\r\n                                <i class=\"bi bi-circle-fill ukt-practical-dot-cyan\"></i>\r\n                                <div>\r\n                                    David Frawley’s “Wisdom of the Ancient Seers” (1992) contextualizes Vedic\r\n                                    practices.\r\n                                </div>\r\n                            </li>\r\n                        </ul>\r\n\r\n                        <!-- Key Takeaway -->\r\n                        <h3 class=\"ukt-practical-title\">\r\n                            <i class=\"bi bi-key-fill ukt-icon-gold\"></i> Key Takeaway:\r\n                        </h3>\r\n                        <p class=\"ukt-practical-list-item mb-3\">\r\n                            While written texts provide foundational knowledge, Agni Hotra’s authenticity relies on\r\n                            oral transmission (guru-shishya parampara). Cross-reference primary sources with\r\n                            reputable modern interpretations for a holistic understanding.\r\n                        </p>\r\n                        <p class=\"ukt-practical-list-item mb-0\">\r\n                            The Agnihotri practice originates from the Vedic period of ancient India and is closely\r\n                            linked to Vedic rituals and the Agnihotra fire sacrifice. The term Agnihotri refers to a\r\n                            Brahmin who performs the Agnihotra ritual daily and maintains the sacred fire (Agni) as\r\n                            part of their spiritual and priestly duties.\r\n                        </p>\r\n\r\n                    </div>\r\n\r\n                    <!-- RIGHT COLUMN: PRACTICAL CONSIDERATIONS -->\r\n                    <div class=\"col-lg-6\">\r\n\r\n                        <h3 class=\"ukt-practical-title\">\r\n                            <i class=\"bi bi-sliders ukt-icon-cyan\"></i> Practical Considerations:\r\n                        </h3>\r\n                        <ul class=\"ukt-practical-list-nomargin\">\r\n                            <li class=\"ukt-practical-list-item\">\r\n                                <i class=\"bi bi-circle-fill ukt-practical-dot-cyan\"></i>\r\n                                <div>\r\n                                    <strong class=\"ukt-text-highlight-teal\">Oral Tradition:</strong> The ritual\r\n                                    requires\r\n                                    precise mantras, timings (sunrise/sunset), and materials (cow dung, ghee, rice).\r\n                                    Seek guidance from a knowledgeable priest or practitioner.\r\n                                </div>\r\n                            </li>\r\n                            <li class=\"ukt-practical-list-item\">\r\n                                <i class=\"bi bi-circle-fill ukt-practical-dot-cyan\"></i>\r\n                                <div>\r\n                                    <strong class=\"ukt-text-highlight-teal\">Ethical Sourcing:</strong> Use organic\r\n                                    offerings\r\n                                    and copper pyramid-shaped pots as prescribed.\r\n                                </div>\r\n                            </li>\r\n                        </ul>\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         SECTION 7: FEATURED VIDEOS & IMAGES\r\n    ========================================================== -->\r\n    <section class=\"py-5 ukt-vedic-sources-section\" id=\"featured-videos\">\r\n        <div class=\"container py-lg-4\">\r\n\r\n            <!-- SECTION HEADER -->\r\n            <div class=\"ukt-section-header\">\r\n                <div class=\"ukt-section-eyebrow\">\r\n                    <span></span>\r\n                    MEDIA HIGHLIGHTS\r\n                    <span></span>\r\n                </div>\r\n                <h2 class=\"ukt-section-main-title\">\r\n                    Featured <span>Videos &amp; Images</span>\r\n                </h2>\r\n                <div class=\"ukt-section-heading-design\">\r\n                    <span></span>\r\n                    <i class=\"bi bi-collection-play-fill\"></i>\r\n                    <span></span>\r\n                </div>\r\n                <p class=\"ukt-section-lead-text\">\r\n                    Watch inspiring coverage and memorable moments from the Karnataka Agnihotra Spectacular and\r\n                    World Agnihotra Day celebrations.\r\n                </p>\r\n            </div>\r\n\r\n            <!-- VIDEO GRID (3 COLUMNS) -->\r\n            <div class=\"row g-4 justify-content-center\">\r\n\r\n                <!-- VIDEO 1: lOUeYL0SZ2k -->\r\n                <div class=\"col-lg-4 col-md-6 col-12\">\r\n                    <div class=\"ukt-featured-video-card\">\r\n                        <div>\r\n                            <div class=\"ratio ratio-16x9 ukt-featured-video-ratio\">\r\n                                <iframe src=\"https://www.youtube.com/embed/lOUeYL0SZ2k\"\r\n                                    title=\"Karnataka Agnihotra Spectacular Featured Video 1\"\r\n                                    allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\"\r\n                                    allowfullscreen loading=\"lazy\"></iframe>\r\n                            </div>\r\n                            <h3 class=\"ukt-featured-video-title\">\r\n                                Agnihotra Homa Ritual Insights &amp; Experience\r\n                            </h3>\r\n                        </div>\r\n                        <div class=\"ukt-featured-video-footer\">\r\n                            <span class=\"ukt-featured-video-source\">\r\n                                <i class=\"bi bi-youtube text-danger\"></i> YouTube\r\n                            </span>\r\n                            <a href=\"https://www.youtube.com/watch?v=lOUeYL0SZ2k\" target=\"_blank\"\r\n                                rel=\"noopener noreferrer\" class=\"ukt-featured-video-link\">\r\n                                Watch on YouTube <i class=\"bi bi-arrow-up-right\"></i>\r\n                            </a>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- VIDEO 2: MYZkAgtDMNU -->\r\n                <div class=\"col-lg-4 col-md-6 col-12\">\r\n                    <div class=\"ukt-featured-video-card\">\r\n                        <div>\r\n                            <div class=\"ratio ratio-16x9 ukt-featured-video-ratio\">\r\n                                <iframe width=\"560\" height=\"315\"\r\n                                    src=\"https://www.youtube.com/embed/MYZkAgtDMNU?si=M1Y2ooNpMQDFsLvC\"\r\n                                    title=\"YouTube video player\" frameborder=\"0\"\r\n                                    allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\"\r\n                                    referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe>\r\n                            </div>\r\n                            <h3 class=\"ukt-featured-video-title\">\r\n                                Karnataka Agnihotra Spectacular Highlights\r\n                            </h3>\r\n                        </div>\r\n                        <div class=\"ukt-featured-video-footer\">\r\n                            <span class=\"ukt-featured-video-source\">\r\n                                <i class=\"bi bi-youtube text-danger\"></i> YouTube\r\n                            </span>\r\n                            <a href=\"https://www.youtube.com/watch?v=MYZkAgtDMNU\" target=\"_blank\"\r\n                                rel=\"noopener noreferrer\" class=\"ukt-featured-video-link\">\r\n                                Watch on YouTube <i class=\"bi bi-arrow-up-right\"></i>\r\n                            </a>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- VIDEO 3: Ha0V48YbmUU -->\r\n                <div class=\"col-lg-4 col-md-6 col-12\">\r\n                    <div class=\"ukt-featured-video-card\">\r\n                        <div>\r\n                            <div class=\"ratio ratio-16x9 ukt-featured-video-ratio\">\r\n                                <iframe src=\"https://www.youtube.com/embed/Ha0V48YbmUU\"\r\n                                    title=\"Karnataka Agnihotra Spectacular Featured Video 3\"\r\n                                    allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\"\r\n                                    allowfullscreen loading=\"lazy\"></iframe>\r\n                            </div>\r\n                            <h3 class=\"ukt-featured-video-title\">\r\n                                World Agnihotra Day Celebration &amp; Message\r\n                            </h3>\r\n                        </div>\r\n                        <div class=\"ukt-featured-video-footer\">\r\n                            <span class=\"ukt-featured-video-source\">\r\n                                <i class=\"bi bi-youtube text-danger\"></i> YouTube\r\n                            </span>\r\n                            <a href=\"https://www.youtube.com/watch?v=Ha0V48YbmUU\" target=\"_blank\"\r\n                                rel=\"noopener noreferrer\" class=\"ukt-featured-video-link\">\r\n                                Watch on YouTube <i class=\"bi bi-arrow-up-right\"></i>\r\n                            </a>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n\r\n            <!-- FEATURED IMAGES GRID (2 STATIC CARDS + 1 IN-CARD CAROUSEL) -->\r\n            <div class=\"row g-4 justify-content-center mt-2\">\r\n\r\n                <!-- Image 1 (Static) -->\r\n                <div class=\"col-lg-4 col-md-6 col-12\">\r\n                    <div class=\"ukt-gallery-card\"\r\n                        data-preview=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-world-record/featured-images-and-videos/IMG-20250410-WA0000-1536x899.jpg\">\r\n                        <figure>\r\n                            <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-world-record/featured-images-and-videos/IMG-20250410-WA0000-1536x899.jpg\"\r\n                                alt=\"Karnataka Agnihotra Spectacular - World Record Ceremony\" loading=\"lazy\">\r\n                            <figcaption class=\"visually-hidden\">Karnataka Agnihotra Spectacular - World Record Ceremony</figcaption>\r\n                        </figure>\r\n                        <div class=\"ukt-gallery-overlay\">\r\n                            <span class=\"ukt-gallery-zoom-icon\">\r\n                                <i class=\"bi bi-zoom-in\"></i>\r\n                            </span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Image 2 (Static) -->\r\n                <div class=\"col-lg-4 col-md-6 col-12\">\r\n                    <div class=\"ukt-gallery-card\"\r\n                        data-preview=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-world-record/featured-images-and-videos/ukt-Image-2025-03-31-at-20.20.23_5750f658-e1743576911227.jpg\">\r\n                        <figure>\r\n                            <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-world-record/featured-images-and-videos/ukt-Image-2025-03-31-at-20.20.23_5750f658-e1743576911227.jpg\"\r\n                                alt=\"Karnataka Agnihotra Spectacular - Celebration Moment\" loading=\"lazy\">\r\n                            <figcaption class=\"visually-hidden\">Karnataka Agnihotra Spectacular - Celebration Moment</figcaption>\r\n                        </figure>\r\n                        <div class=\"ukt-gallery-overlay\">\r\n                            <span class=\"ukt-gallery-zoom-icon\">\r\n                                <i class=\"bi bi-zoom-in\"></i>\r\n                            </span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Image 3 (In-Card Carousel for universal_naland-trust images) -->\r\n                <div class=\"col-lg-4 col-md-6 col-12\">\r\n                    <div class=\"ukt-gallery-card ukt-gallery-carousel-card\">\r\n                        <div id=\"uktNalandTrustCarousel\" class=\"carousel slide\" data-bs-ride=\"carousel\" data-bs-interval=\"3500\">\r\n                            \r\n                            <!-- Carousel Indicators -->\r\n                            <div class=\"carousel-indicators\">\r\n                                <button type=\"button\" data-bs-target=\"#uktNalandTrustCarousel\" data-bs-slide-to=\"0\" class=\"active\" aria-current=\"true\" aria-label=\"Slide 1\"></button>\r\n                                <button type=\"button\" data-bs-target=\"#uktNalandTrustCarousel\" data-bs-slide-to=\"1\" aria-label=\"Slide 2\"></button>\r\n                                <button type=\"button\" data-bs-target=\"#uktNalandTrustCarousel\" data-bs-slide-to=\"2\" aria-label=\"Slide 3\"></button>\r\n                                <button type=\"button\" data-bs-target=\"#uktNalandTrustCarousel\" data-bs-slide-to=\"3\" aria-label=\"Slide 4\"></button>\r\n                            </div>\r\n\r\n                            <!-- Carousel Inner Slides -->\r\n                            <div class=\"carousel-inner\">\r\n                                <div class=\"carousel-item active\" data-preview=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-world-record/featured-images-and-videos/universal_naland-trust/1.png\">\r\n                                    <figure>\r\n                                        <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-world-record/featured-images-and-videos/universal_naland-trust/1.png\"\r\n                                            alt=\"Karnataka Agnihotra Spectacular Highlight 1\" loading=\"lazy\">\r\n                                        <figcaption class=\"visually-hidden\">Karnataka Agnihotra Spectacular Highlight 1</figcaption>\r\n                                    </figure>\r\n                                </div>\r\n                                <div class=\"carousel-item\" data-preview=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-world-record/featured-images-and-videos/universal_naland-trust/2.png\">\r\n                                    <figure>\r\n                                        <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-world-record/featured-images-and-videos/universal_naland-trust/2.png\"\r\n                                            alt=\"Karnataka Agnihotra Spectacular Highlight 2\" loading=\"lazy\">\r\n                                        <figcaption class=\"visually-hidden\">Karnataka Agnihotra Spectacular Highlight 2</figcaption>\r\n                                    </figure>\r\n                                </div>\r\n                                <div class=\"carousel-item\" data-preview=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-world-record/featured-images-and-videos/universal_naland-trust/3.png\">\r\n                                    <figure>\r\n                                        <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-world-record/featured-images-and-videos/universal_naland-trust/3.png\"\r\n                                            alt=\"Karnataka Agnihotra Spectacular Highlight 3\" loading=\"lazy\">\r\n                                        <figcaption class=\"visually-hidden\">Karnataka Agnihotra Spectacular Highlight 3</figcaption>\r\n                                    </figure>\r\n                                </div>\r\n                                <div class=\"carousel-item\" data-preview=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-world-record/featured-images-and-videos/universal_naland-trust/4.png\">\r\n                                    <figure>\r\n                                        <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-world-record/featured-images-and-videos/universal_naland-trust/4.png\"\r\n                                            alt=\"Karnataka Agnihotra Spectacular Highlight 4\" loading=\"lazy\">\r\n                                        <figcaption class=\"visually-hidden\">Karnataka Agnihotra Spectacular Highlight 4</figcaption>\r\n                                    </figure>\r\n                                </div>\r\n                            </div>\r\n\r\n                            <!-- Carousel Controls -->\r\n                            <button class=\"carousel-control-prev\" type=\"button\" data-bs-target=\"#uktNalandTrustCarousel\" data-bs-slide=\"prev\" aria-label=\"Previous Slide\">\r\n                                <span class=\"carousel-control-prev-icon\" aria-hidden=\"true\"></span>\r\n                            </button>\r\n                            <button class=\"carousel-control-next\" type=\"button\" data-bs-target=\"#uktNalandTrustCarousel\" data-bs-slide=\"next\" aria-label=\"Next Slide\">\r\n                                <span class=\"carousel-control-next-icon\" aria-hidden=\"true\"></span>\r\n                            </button>\r\n\r\n                            <!-- Gallery Overlay Zoom Icon -->\r\n                            <div class=\"ukt-gallery-overlay\">\r\n                                <span class=\"ukt-gallery-zoom-icon\">\r\n                                    <i class=\"bi bi-zoom-in\"></i>\r\n                                </span>\r\n                            </div>\r\n\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         SECTION 8: CTA CALLOUT BANNER\r\n    ========================================================== -->\r\n    <section class=\"ukt-cta-section\">\r\n\r\n        <!-- Decorative Elements -->\r\n        <div class=\"ukt-cta-orb ukt-cta-orb-left\"></div>\r\n        <div class=\"ukt-cta-orb ukt-cta-orb-right\"></div>\r\n\r\n        <div class=\"container position-relative\">\r\n            <div class=\"row justify-content-center\">\r\n                <div class=\"col-xl-9 col-lg-10\">\r\n                    <div class=\"ukt-cta-content text-center\">\r\n\r\n                        <span class=\"ukt-cta-kicker\">\r\n                            BE A PART OF THE MOVEMENT\r\n                        </span>\r\n\r\n                        <h2>\r\n                            Experience Agnihotra\r\n                            <span>With Universal Knowledge</span>\r\n                        </h2>\r\n\r\n                        <p>\r\n                            Learn authentic Agnihotra chanting, obtain verified sunrise-sunset timetables for your\r\n                            exact location, and participate in community Homa healing sessions led by experienced\r\n                            mentors.\r\n                        </p>\r\n\r\n                        <div class=\"ukt-cta-actions\">\r\n                            <a href=\"http://localhost/universal-knowledge-trust-wordpress/about-us\" rel=\"noopener noreferrer\" class=\"ukt-cta-primary-btn\">\r\n                                <span>KNOW ABOUT US</span>\r\n                                <i class=\"bi bi-arrow-up-right\"></i>\r\n                            </a>\r\n\r\n                            <a href=\"http://localhost/universal-knowledge-trust-wordpress/contact\" class=\"ukt-cta-secondary-btn\">\r\n                                <span>CONNECT WITH US</span>\r\n                            </a>\r\n                        </div>\r\n\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </section>\r\n\r\n</article>\r\n\r\n<!-- =========================================================\r\n     FULL SCREEN GALLERY LIGHTBOX MODAL\r\n========================================================== -->\r\n<div id=\"uktGalleryLightbox\" class=\"ukt-gallery-lightbox\" aria-hidden=\"true\" role=\"dialog\"\r\n    aria-label=\"Image Full Screen Preview\">\r\n    <div class=\"ukt-lightbox-backdrop\"></div>\r\n\r\n    <div class=\"ukt-lightbox-container\">\r\n        <!-- Top Controls -->\r\n        <div class=\"ukt-lightbox-header\">\r\n            <span class=\"ukt-lightbox-counter\" id=\"uktLightboxCounter\">1 / 6</span>\r\n            <button type=\"button\" class=\"ukt-lightbox-close\" id=\"uktLightboxClose\" aria-label=\"Close preview\">\r\n                <i class=\"bi bi-x-lg\"></i>\r\n            </button>\r\n        </div>\r\n\r\n        <!-- Main Image Wrapper -->\r\n        <div class=\"ukt-lightbox-content\">\r\n            <button type=\"button\" class=\"ukt-lightbox-nav ukt-lightbox-prev\" id=\"uktLightboxPrev\"\r\n                aria-label=\"Previous image\">\r\n                <i class=\"bi bi-chevron-left\"></i>\r\n            </button>\r\n\r\n            <div class=\"ukt-lightbox-image-wrap\">\r\n                <figure class=\"ukt-lightbox-figure\">\r\n                    <img id=\"uktLightboxImage\" src=\"\" alt=\"Full Screen Preview\" class=\"ukt-lightbox-img\">\r\n                    <figcaption class=\"visually-hidden\">Full Screen Gallery Image Preview</figcaption>\r\n                </figure>\r\n            </div>\r\n\r\n            <button type=\"button\" class=\"ukt-lightbox-nav ukt-lightbox-next\" id=\"uktLightboxNext\"\r\n                aria-label=\"Next image\">\r\n                <i class=\"bi bi-chevron-right\"></i>\r\n            </button>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<script>\r\ndocument.addEventListener(\"DOMContentLoaded\", function () {\r\n\r\n    /* =========================================================\r\n       FULL SCREEN GALLERY LIGHTBOX PREVIEW\r\n    ========================================================== */\r\n    const lightbox = document.getElementById(\"uktGalleryLightbox\");\r\n    if (lightbox) {\r\n        const lightboxImg = document.getElementById(\"uktLightboxImage\");\r\n        const counter = document.getElementById(\"uktLightboxCounter\");\r\n        const closeBtn = document.getElementById(\"uktLightboxClose\");\r\n        const prevBtn = document.getElementById(\"uktLightboxPrev\");\r\n        const nextBtn = document.getElementById(\"uktLightboxNext\");\r\n        const backdrop = lightbox.querySelector(\".ukt-lightbox-backdrop\");\r\n\r\n        const images = [\r\n            {\r\n                src: \"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-world-record/featured-images-and-videos/IMG-20250410-WA0000-1536x899.jpg\",\r\n                alt: \"Karnataka Agnihotra Spectacular - World Record Ceremony\"\r\n            },\r\n            {\r\n                src: \"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-world-record/featured-images-and-videos/ukt-Image-2025-03-31-at-20.20.23_5750f658-e1743576911227.jpg\",\r\n                alt: \"Karnataka Agnihotra Spectacular - Celebration Moment\"\r\n            },\r\n            {\r\n                src: \"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-world-record/featured-images-and-videos/universal_naland-trust/1.png\",\r\n                alt: \"Karnataka Agnihotra Spectacular Highlight 1\"\r\n            },\r\n            {\r\n                src: \"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-world-record/featured-images-and-videos/universal_naland-trust/2.png\",\r\n                alt: \"Karnataka Agnihotra Spectacular Highlight 2\"\r\n            },\r\n            {\r\n                src: \"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-world-record/featured-images-and-videos/universal_naland-trust/3.png\",\r\n                alt: \"Karnataka Agnihotra Spectacular Highlight 3\"\r\n            },\r\n            {\r\n                src: \"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-world-record/featured-images-and-videos/universal_naland-trust/4.png\",\r\n                alt: \"Karnataka Agnihotra Spectacular Highlight 4\"\r\n            }\r\n        ];\r\n\r\n        document.addEventListener(\"click\", function (e) {\r\n            if (e.target.closest(\".carousel-control-prev\") || e.target.closest(\".carousel-control-next\") || e.target.closest(\".carousel-indicators\")) {\r\n                return;\r\n            }\r\n            const card = e.target.closest(\".ukt-gallery-card\");\r\n            if (!card) return;\r\n\r\n            let previewSrc = \"\";\r\n            if (card.classList.contains(\"ukt-gallery-carousel-card\")) {\r\n                const activeItem = card.querySelector(\".carousel-item.active\");\r\n                if (activeItem) {\r\n                    previewSrc = activeItem.getAttribute(\"data-preview\") || (activeItem.querySelector(\"img\") ? activeItem.querySelector(\"img\").getAttribute(\"src\") : \"\");\r\n                }\r\n            } else {\r\n                previewSrc = card.getAttribute(\"data-preview\") || (card.querySelector(\"img\") ? card.querySelector(\"img\").getAttribute(\"src\") : \"\");\r\n            }\r\n\r\n            if (!previewSrc) return;\r\n            const foundIdx = images.findIndex(img => img.src === previewSrc);\r\n            openLightbox(foundIdx !== -1 ? foundIdx : 0);\r\n        });\r\n\r\n        document.addEventListener(\"keydown\", function (e) {\r\n            if ((e.key === \"Enter\" || e.key === \" \") && document.activeElement && document.activeElement.classList.contains(\"ukt-gallery-card\")) {\r\n                e.preventDefault();\r\n                const card = document.activeElement;\r\n                let previewSrc = \"\";\r\n                if (card.classList.contains(\"ukt-gallery-carousel-card\")) {\r\n                    const activeItem = card.querySelector(\".carousel-item.active\");\r\n                    if (activeItem) {\r\n                        previewSrc = activeItem.getAttribute(\"data-preview\") || (activeItem.querySelector(\"img\") ? activeItem.querySelector(\"img\").getAttribute(\"src\") : \"\");\r\n                    }\r\n                } else {\r\n                    previewSrc = card.getAttribute(\"data-preview\") || (card.querySelector(\"img\") ? card.querySelector(\"img\").getAttribute(\"src\") : \"\");\r\n                }\r\n                if (!previewSrc) return;\r\n                const foundIdx = images.findIndex(img => img.src === previewSrc);\r\n                openLightbox(foundIdx !== -1 ? foundIdx : 0);\r\n            }\r\n        });\r\n\r\n        let currentIndex = 0;\r\n\r\n        function openLightbox(index) {\r\n            if (images.length === 0) return;\r\n            currentIndex = index;\r\n            updateImage();\r\n            lightbox.classList.add(\"is-active\");\r\n            lightbox.setAttribute(\"aria-hidden\", \"false\");\r\n            document.body.style.overflow = \"hidden\";\r\n        }\r\n\r\n        function closeLightbox() {\r\n            lightbox.classList.remove(\"is-active\");\r\n            lightbox.setAttribute(\"aria-hidden\", \"true\");\r\n            document.body.style.overflow = \"\";\r\n        }\r\n\r\n        function updateImage() {\r\n            if (currentIndex < 0) currentIndex = images.length - 1;\r\n            if (currentIndex >= images.length) currentIndex = 0;\r\n\r\n            lightboxImg.style.opacity = \"0\";\r\n            lightboxImg.style.transform = \"scale(0.96)\";\r\n\r\n            setTimeout(() => {\r\n                lightboxImg.src = images[currentIndex].src;\r\n                lightboxImg.alt = images[currentIndex].alt;\r\n                counter.textContent = `${currentIndex + 1} / ${images.length}`;\r\n                lightboxImg.style.opacity = \"1\";\r\n                lightboxImg.style.transform = \"scale(1)\";\r\n            }, 100);\r\n        }\r\n\r\n        function showNext() {\r\n            currentIndex = (currentIndex + 1) % images.length;\r\n            updateImage();\r\n        }\r\n\r\n        function showPrev() {\r\n            currentIndex = (currentIndex - 1 + images.length) % images.length;\r\n            updateImage();\r\n        }\r\n\r\n        if (closeBtn) closeBtn.addEventListener(\"click\", closeLightbox);\r\n        if (backdrop) backdrop.addEventListener(\"click\", closeLightbox);\r\n        if (nextBtn) nextBtn.addEventListener(\"click\", showNext);\r\n        if (prevBtn) prevBtn.addEventListener(\"click\", showPrev);\r\n\r\n        document.addEventListener(\"keydown\", function (e) {\r\n            if (!lightbox.classList.contains(\"is-active\")) return;\r\n            if (e.key === \"Escape\") closeLightbox();\r\n            if (e.key === \"ArrowRight\") showNext();\r\n            if (e.key === \"ArrowLeft\") showPrev();\r\n        });\r\n\r\n        let touchStartX = 0;\r\n        let touchEndX = 0;\r\n        lightbox.addEventListener(\"touchstart\", function (e) {\r\n            touchStartX = e.changedTouches[0].screenX;\r\n        }, { passive: true });\r\n\r\n        lightbox.addEventListener(\"touchend\", function (e) {\r\n            touchEndX = e.changedTouches[0].screenX;\r\n            handleSwipe();\r\n        }, { passive: true });\r\n\r\n        function handleSwipe() {\r\n            const diff = touchEndX - touchStartX;\r\n            if (Math.abs(diff) > 50) {\r\n                if (diff > 0) {\r\n                    showPrev();\r\n                } else {\r\n                    showNext();\r\n                }\r\n            }\r\n        }\r\n    }\r\n\r\n});\r\n</script>', 'Karnataka Agnihotra Spectacular', '', 'inherit', 'closed', 'closed', '', '235-revision-v1', '', '', '2026-10-26 17:26:23', '2026-10-26 11:56:23', '', 235, 'http://localhost/universal-knowledge-trust-wordpress/?p=244', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(245, 1, '2026-10-26 17:30:50', '2026-10-26 12:00:50', '<article>\r\n    <!-- =========================================================\r\n         AGNIHOTRA PROCEDURES HERO SECTION (MATCHING INDEX HERO SHOWCASE)\r\n    ========================================================== -->\r\n    <section class=\"ukt-hero-showcase\">\r\n        <div class=\"ukt-hero-slide-layout\">\r\n            <div class=\"container-fluid\">\r\n                <div class=\"row g-0 align-items-stretch\">\r\n\r\n                    <!-- LEFT CONTENT AREA -->\r\n                    <div class=\"col-lg-5 d-flex align-items-center\">\r\n                        <div class=\"ukt-hero-copy-zone\">\r\n                            <div class=\"ukt-hero-left-decoration\"></div>\r\n\r\n                            <div class=\"ukt-hero-slide-kicker\">\r\n                                Universal Knowledge Trust\r\n                            </div>\r\n\r\n                            <h1 class=\"ukt-hero-main-title\">\r\n                                <span>An Ancient Practice</span>\r\n                                <span>for a Harmonious Way of Life.</span>\r\n                            </h1>\r\n\r\n                            <div class=\"ukt-hero-script-line\">\r\n                                Physical, Mental &amp; Spiritual Well-Being\r\n                            </div>\r\n\r\n                            <p class=\"ukt-hero-description\">\r\n                                Discover Agnihotra, an ancient Vedic fire practice traditionally performed at\r\n                                sunrise and sunset. Explore its purpose, the materials involved, the procedure, and\r\n                                how you can become part of a larger Agnihotra initiative.\r\n                            </p>\r\n\r\n                            <div class=\"ukt-hero-action-row\">\r\n                                <a href=\"#agnihotra_procedure\" class=\"ukt-hero-primary-action\">\r\n                                    Explore Procedure\r\n                                    <i class=\"bi bi-arrow-right\"></i>\r\n                                </a>\r\n                            </div>\r\n\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- RIGHT IMAGE AREA -->\r\n                    <div class=\"col-lg-7\">\r\n                        <div class=\"ukt-hero-visual-zone\">\r\n                            <div class=\"ukt-hero-image-frame\">\r\n                                <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-procedure-banner.jpg\"\r\n                                    alt=\"Agnihotra Procedure - An Ancient Practice for a Harmonious Way of Life\"\r\n                                    title=\"Agnihotra Procedure Banner\">\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         SECTION: WHAT IS AGNIHOTRA (OVERVIEW)\r\n    ========================================================== -->\r\n    <section class=\"ukt-agni-intro-section py-5\">\r\n        <div class=\"container py-lg-3\">\r\n            <div class=\"row align-items-center justify-content-between g-4\">\r\n                <div class=\"col-lg-7 col-md-12\">\r\n                    <div class=\"pe-0 pe-lg-3\">\r\n                        <div class=\"ukt-section-eyebrow text-start m-0 mb-2\">\r\n                            <span></span>\r\n                            ANCIENT VEDIC KNOWLEDGE\r\n                        </div>\r\n                        <h2 class=\"ukt-section-main-title mb-2\">\r\n                            What is <span>Agnihotra?</span>\r\n                        </h2>\r\n                        <div class=\"ukt-section-heading-design m-0 mb-3 justify-content-start\">\r\n                            <span></span>\r\n                            <i class=\"bi bi-flower1\"></i>\r\n                            <span></span>\r\n                        </div>\r\n\r\n                        <p class=\"ukt-agni-intro-lead\">\r\n                            Angihotra, also known as Agnihotra, is an ancient Vedic fire ritual originating from India. It’s a powerful practice for physical, mental, and spiritual well-being. Here’s a step-by-step guide:\r\n                        </p>\r\n\r\n                        <!-- <p class=\"ukt-agni-intro-text\">\r\n                            Performed at exact sunrise and sunset with authentic copper pyramid vessels, pure cow\r\n                            ghee, dry cow dung, and unbroken rice, Agnihotra creates a powerful purification field\r\n                            that revitalizes plant life, cleanses the surrounding air, reduces stress, and promotes\r\n                            holistic physical, mental, and spiritual well-being.\r\n                        </p> -->\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"col-lg-5 col-md-12 d-flex align-items-center justify-content-center\">\r\n                    <figure>\r\n                        <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-what-is-section1.jpg\"\r\n                            alt=\"Agnihotra Sacred Fire Ritual - Copper Pyramid with Sacred Fire at Sunrise\"\r\n                            title=\"What is Agnihotra Sacred Fire Ritual\" class=\"ukt-agnihotra-poster-img img-fluid\"\r\n                            loading=\"lazy\">\r\n                        <figcaption class=\"cr-only\">\r\n                            Agnihotra bio-energetic fire process to honor Agni and Surya, performed at exact sunrise\r\n                            and sunset for atmospheric purification and holistic well-being.\r\n                        </figcaption>\r\n                    </figure>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </section>\r\n\r\n\r\n    <!-- =========================================================\r\n         SECTION: STEP-BY-STEP AGNIHOTRA PROCEDURE\r\n    ========================================================== -->\r\n    <section id=\"agnihotra_procedure\" class=\"ukt-agni-procedure-section py-5\">\r\n        <div class=\"container py-lg-4\">\r\n\r\n            <!-- SECTION HEADER -->\r\n            <div class=\"ukt-section-header\">\r\n                <div class=\"ukt-section-eyebrow\">\r\n                    <span></span>\r\n                    STEP-BY-STEP RITUAL GUIDE\r\n                    <span></span>\r\n                </div>\r\n                <h2 class=\"ukt-section-main-title\">\r\n                    How to Perform <span>Agnihotra</span>\r\n                </h2>\r\n                <div class=\"ukt-section-heading-design\">\r\n                    <span></span>\r\n                    <i class=\"bi bi-flower1\"></i>\r\n                    <span></span>\r\n                </div>\r\n                <p class=\"ukt-agni-procedure-subtitle text-center mx-auto mt-2\">\r\n                    Comprehensive guide covering authentic materials, pre-ritual preparation, sunrise and sunset\r\n                    procedures, safety precautions, and holistic benefits.\r\n                </p>\r\n            </div>\r\n\r\n            <!-- ALL PROCEDURE CARDS (STACKED VERTICALLY) -->\r\n            <div class=\"ukt-agni-procedure-cards d-flex flex-column\">\r\n\r\n\r\n                <!-- ════════════════════════════════════════════════\r\n                     CARD 1: MATERIALS NEEDED\r\n                ════════════════════════════════════════════════ -->\r\n                <div class=\"ukt-agni-card ukt-agni-card-amber text-start\">\r\n                    <!-- Gradient top accent -->\r\n                    <div class=\"ukt-agni-card-accent\"></div>\r\n\r\n                    <!-- Header -->\r\n                    <div class=\"d-flex align-items-center gap-3 mb-4\">\r\n                        <div class=\"ukt-agni-card-icon\">\r\n                            <i class=\"bi bi-box-seam-fill\"></i>\r\n                        </div>\r\n                        <div>\r\n                            <div class=\"ukt-agni-card-badge\">Step 1</div>\r\n                            <h3 class=\"ukt-agni-card-title\">Materials Needed</h3>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- Items Grid -->\r\n                    <div class=\"row g-3\">\r\n                        <div class=\"col-lg-4 col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-material-item\">\r\n                                <div class=\"ukt-agni-material-icon\">\r\n                                    <i class=\"bi bi-triangle-fill\"></i>\r\n                                </div>\r\n                                <span class=\"ukt-agni-material-label\">Copper Pyramid</span>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-lg-4 col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-material-item\">\r\n                                <div class=\"ukt-agni-material-icon\">\r\n                                    <i class=\"bi bi-droplet-fill\"></i>\r\n                                </div>\r\n                                <span class=\"ukt-agni-material-label\">Ghee (Clarified Butter)</span>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-lg-4 col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-material-item\">\r\n                                <div class=\"ukt-agni-material-icon\">\r\n                                    <i class=\"bi bi-circle-fill\"></i>\r\n                                </div>\r\n                                <span class=\"ukt-agni-material-label\">Rice Grains</span>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-lg-4 col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-material-item\">\r\n                                <div class=\"ukt-agni-material-icon\">\r\n                                    <i class=\"bi bi-fire\"></i>\r\n                                </div>\r\n                                <span class=\"ukt-agni-material-label\">Cow Dung Cakes</span>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-lg-4 col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-material-item\">\r\n                                <div class=\"ukt-agni-material-icon\">\r\n                                    <i class=\"bi bi-lightning-charge-fill\"></i>\r\n                                </div>\r\n                                <span class=\"ukt-agni-material-label\">Matches / Lighter</span>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-lg-4 col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-material-item\">\r\n                                <div class=\"ukt-agni-material-icon\">\r\n                                    <i class=\"bi bi-clock-fill\"></i>\r\n                                </div>\r\n                                <span class=\"ukt-agni-material-label\">Timing Device</span>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n\r\n                <!-- ════════════════════════════════════════════════\r\n                     CARD 2: PREPARATION\r\n                ════════════════════════════════════════════════ -->\r\n                <div class=\"ukt-agni-card ukt-agni-card-teal text-start\">\r\n                    <div class=\"ukt-agni-card-accent\"></div>\r\n\r\n                    <div class=\"d-flex align-items-center gap-3 mb-4\">\r\n                        <div class=\"ukt-agni-card-icon\">\r\n                            <i class=\"bi bi-clipboard2-check-fill\"></i>\r\n                        </div>\r\n                        <div>\r\n                            <div class=\"ukt-agni-card-badge\">Step 2</div>\r\n                            <h3 class=\"ukt-agni-card-title\">Preparation</h3>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"ukt-agni-step-list d-flex flex-column\">\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <div class=\"ukt-agni-step-num\">1</div>\r\n                            <p class=\"ukt-agni-step-desc\">Choose a quiet, clean space for the ritual.</p>\r\n                        </div>\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <div class=\"ukt-agni-step-num\">2</div>\r\n                            <p class=\"ukt-agni-step-desc\">Set up the copper pyramid on a heat-resistant surface.</p>\r\n                        </div>\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <div class=\"ukt-agni-step-num\">3</div>\r\n                            <p class=\"ukt-agni-step-desc\">Prepare ghee and rice grains.</p>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"text-center pt-3\">\r\n                        <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-world-record/31-U3L5RSFL-300x236-1.webp\"\r\n                            alt=\"Agnihotra Copper Pyramid Kit\" title=\"Agnihotra Copper Pyramid Kit\"\r\n                            class=\"img-fluid rounded ukt-procedure-kit-img\" loading=\"lazy\">\r\n                    </div>\r\n                </div>\r\n\r\n\r\n                <!-- ════════════════════════════════════════════════\r\n                     CARD 3: SUNRISE AGNIHOTRA PROCEDURE\r\n                ════════════════════════════════════════════════ -->\r\n                <div class=\"ukt-agni-card ukt-agni-card-orange text-start\">\r\n                    <div class=\"ukt-agni-card-accent\"></div>\r\n\r\n                    <div class=\"d-flex align-items-center gap-3 mb-4\">\r\n                        <div class=\"ukt-agni-card-icon\">\r\n                            <i class=\"bi bi-sunrise-fill\"></i>\r\n                        </div>\r\n                        <div>\r\n                            <div class=\"ukt-agni-card-badge\">Step 3 · Morning Ritual</div>\r\n                            <h3 class=\"ukt-agni-card-title\">Sunrise Agnihotra</h3>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"ukt-agni-step-list d-flex flex-column\">\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <span class=\"ukt-agni-step-num\">1</span>\r\n                            <p class=\"ukt-agni-step-desc\">Calculate local sunrise time.</p>\r\n                        </div>\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <span class=\"ukt-agni-step-num\">2</span>\r\n                            <p class=\"ukt-agni-step-desc\">Light the fire 10–15 minutes before sunrise.</p>\r\n                        </div>\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <span class=\"ukt-agni-step-num\">3</span>\r\n                            <p class=\"ukt-agni-step-desc\">Add 2–3 pinches of rice grains to the fire.</p>\r\n                        </div>\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <span class=\"ukt-agni-step-num\">4</span>\r\n                            <p class=\"ukt-agni-step-desc\">Add 2–3 drops of ghee to the fire.</p>\r\n                        </div>\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <span class=\"ukt-agni-step-num\">5</span>\r\n                            <p class=\"ukt-agni-step-desc\">Recite the 2 mantras:</p>\r\n                        </div>\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <span class=\"ukt-agni-step-num\">6</span>\r\n                            <p class=\"ukt-agni-step-desc\">Repeat steps 3–5 for 10–15 minutes.</p>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n\r\n                <!-- ════════════════════════════════════════════════\r\n                     CARD 4: SUNSET AGNIHOTRA PROCEDURE\r\n                ════════════════════════════════════════════════ -->\r\n                <div class=\"ukt-agni-card ukt-agni-card-purple text-start\">\r\n                    <div class=\"ukt-agni-card-accent\"></div>\r\n\r\n                    <div class=\"d-flex align-items-center gap-3 mb-4\">\r\n                        <div class=\"ukt-agni-card-icon\">\r\n                            <i class=\"bi bi-sunset-fill\"></i>\r\n                        </div>\r\n                        <div>\r\n                            <div class=\"ukt-agni-card-badge\">Step 4 · Evening Ritual</div>\r\n                            <h3 class=\"ukt-agni-card-title\">Sunset Agnihotra</h3>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"ukt-agni-step-list d-flex flex-column\">\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <span class=\"ukt-agni-step-num\">1</span>\r\n                            <p class=\"ukt-agni-step-desc\">Calculate local sunset time.</p>\r\n                        </div>\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <span class=\"ukt-agni-step-num\">2</span>\r\n                            <p class=\"ukt-agni-step-desc\">Light the fire 10–15 minutes before sunset.</p>\r\n                        </div>\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <span class=\"ukt-agni-step-num\">3</span>\r\n                            <p class=\"ukt-agni-step-desc\">Add 2–3 pinches of rice grains to the fire.</p>\r\n                        </div>\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <span class=\"ukt-agni-step-num\">4</span>\r\n                            <p class=\"ukt-agni-step-desc\">Add 2–3 drops of ghee to the fire.</p>\r\n                        </div>\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <span class=\"ukt-agni-step-num\">5</span>\r\n                            <p class=\"ukt-agni-step-desc\">Recite the 2 mantras:</p>\r\n                        </div>\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <span class=\"ukt-agni-step-num\">6</span>\r\n                            <p class=\"ukt-agni-step-desc\">Repeat steps 3–5 for 10–15 minutes.</p>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n\r\n                <!-- ════════════════════════════════════════════════\r\n                     CARD 5: TIPS & PRECAUTIONS\r\n                ════════════════════════════════════════════════ -->\r\n                <div class=\"ukt-agni-card ukt-agni-card-emerald text-start\">\r\n                    <div class=\"ukt-agni-card-accent\"></div>\r\n\r\n                    <div class=\"d-flex align-items-center gap-3 mb-4\">\r\n                        <div class=\"ukt-agni-card-icon\">\r\n                            <i class=\"bi bi-shield-fill-check\"></i>\r\n                        </div>\r\n                        <div>\r\n                            <div class=\"ukt-agni-card-badge\">Guidelines &amp; Safety</div>\r\n                            <h3 class=\"ukt-agni-card-title\">Tips &amp; Precautions</h3>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"row g-3\">\r\n                        <div class=\"col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-tip-item\">\r\n                                <i class=\"bi bi-alarm-fill ukt-agni-tip-icon\"></i>\r\n                                <span class=\"ukt-agni-tip-text\">Use a timer to synchronize with sunrise/sunset.</span>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-tip-item\">\r\n                                <i class=\"bi bi-calendar-check-fill ukt-agni-tip-icon\"></i>\r\n                                <span class=\"ukt-agni-tip-text\">Maintain a consistent schedule.</span>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-tip-item\">\r\n                                <i class=\"bi bi-house-check-fill ukt-agni-tip-icon\"></i>\r\n                                <span class=\"ukt-agni-tip-text\">Keep the area clean and free from distractions.</span>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-tip-item\">\r\n                                <i class=\"bi bi-heart-pulse-fill ukt-agni-tip-icon\"></i>\r\n                                <span class=\"ukt-agni-tip-text\">Avoid performing Agnihotra during menstruation or when feeling unwell.</span>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-12\">\r\n                            <div class=\"ukt-agni-tip-item\">\r\n                                <i class=\"bi bi-exclamation-triangle-fill ukt-agni-tip-icon\"></i>\r\n                                <span class=\"ukt-agni-tip-text\">Respect the fire and handle it carefully.</span>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n\r\n                <!-- ════════════════════════════════════════════════\r\n                     CARD 6: BENEFITS\r\n                ════════════════════════════════════════════════ -->\r\n                <div class=\"ukt-agni-card ukt-agni-card-gold text-start\">\r\n                    <div class=\"ukt-agni-card-accent\"></div>\r\n\r\n                    <div class=\"d-flex align-items-center gap-3 mb-4\">\r\n                        <div class=\"ukt-agni-card-icon\">\r\n                            <i class=\"bi bi-stars\"></i>\r\n                        </div>\r\n                        <div>\r\n                            <div class=\"ukt-agni-card-badge\">Transformation</div>\r\n                            <h3 class=\"ukt-agni-card-title\">Benefits</h3>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"row g-3\">\r\n                        <div class=\"col-lg-4 col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-benefit-item\">\r\n                                <div class=\"ukt-agni-benefit-icon\">\r\n                                    <i class=\"bi bi-cloud-sun-fill\"></i>\r\n                                </div>\r\n                                <span class=\"ukt-agni-benefit-label\">Purifies the Environment</span>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-lg-4 col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-benefit-item\">\r\n                                <div class=\"ukt-agni-benefit-icon\">\r\n                                    <i class=\"bi bi-brain\"></i>\r\n                                </div>\r\n                                <span class=\"ukt-agni-benefit-label\">Mental Clarity &amp; Focus</span>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-lg-4 col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-benefit-item\">\r\n                                <div class=\"ukt-agni-benefit-icon\">\r\n                                    <i class=\"bi bi-activity\"></i>\r\n                                </div>\r\n                                <span class=\"ukt-agni-benefit-label\">Enhances Physical Health</span>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-lg-6 col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-benefit-item\">\r\n                                <div class=\"ukt-agni-benefit-icon\">\r\n                                    <i class=\"bi bi-heart-pulse-fill\"></i>\r\n                                </div>\r\n                                <span class=\"ukt-agni-benefit-label\">Reduces Stress &amp; Anxiety</span>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-lg-6 col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-benefit-item\">\r\n                                <div class=\"ukt-agni-benefit-icon\">\r\n                                    <i class=\"bi bi-peace\"></i>\r\n                                </div>\r\n                                <span class=\"ukt-agni-benefit-label\">Promotes Spiritual Growth</span>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n            </div><!-- /.d-flex flex-column -->\r\n\r\n\r\n            <!-- ════════════════════════════════════════════════\r\n                 RESOURCES\r\n            ════════════════════════════════════════════════ -->\r\n            <div class=\"ukt-practical-unified-card mt-4 mb-3 text-start\">\r\n                <div class=\"ukt-practical-accent-bar\"></div>\r\n                <h3 class=\"ukt-practical-title ukt-practical-title-md mb-2\">\r\n                    <i class=\"bi bi-journal-bookmark-fill ukt-icon-gold\"></i> Resources:\r\n                </h3>\r\n                <ul class=\"ukt-practical-list-nomargin\">\r\n                    <li class=\"ukt-practical-list-item\">\r\n                        <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                        <div>1. Consult Vedic texts or experienced practitioners for guidance.</div>\r\n                    </li>\r\n                    <li class=\"ukt-practical-list-item\">\r\n                        <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                        <div>2. Visit <a href=\"#\" class=\"ukt-agnihotra-link-teal fw-bold text-decoration-none\">Agnihotra Procedure</a> for more information.</div>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n\r\n            <!-- ════════════════════════════════════════════════\r\n                 CONSISTENCY CALLOUT\r\n            ════════════════════════════════════════════════ -->\r\n            <div class=\"ukt-agni-consistency-callout\">\r\n                <i class=\"bi bi-fire ukt-agni-consistency-icon me-2\"></i>\r\n                <span class=\"ukt-agni-consistency-text\">\r\n                    Remember, consistency and sincerity are key to experiencing the benefits of Agnihotra.\r\n                </span>\r\n            </div>\r\n\r\n            <!-- ════════════════════════════════════════════════\r\n                 WORLD RECORD PARTICIPATION PARAGRAPHS\r\n            ════════════════════════════════════════════════ -->\r\n            <div class=\"mt-4 text-start\">\r\n                <p class=\"ukt-agnihotra-record-text mb-2\">\r\n                    Gram Vikas Society (GVS) creating a World Record by lighting Agnihotra at 11,000 + at single location.Powered by Universal Knowledge.\r\n                </p>\r\n\r\n                <p class=\"ukt-agnihotra-record-text mb-3\">\r\n                    This is an unique program and we will join to have a Agnihotra done at 11,000 different houses / offices in and around Karnataka\r\n                </p>\r\n\r\n                <h4 class=\"ukt-agnihotra-record-subheading fw-bold mb-2\">\r\n                    How you can be a part of this world record?\r\n                </h4>\r\n\r\n                <p class=\"ukt-agnihotra-record-text mb-2\">\r\n                    If you are willing to participate and have agnihotra done at your house or office daily, you can apply at the link below;\r\n                </p>\r\n\r\n                <p class=\"ukt-agnihotra-record-text mb-2\">\r\n                    GVS will provide you with free startup Agnihotra kit, which will include Copper pyramid Bowl, startup material for 4 days worth ₹ 1,250/-.\r\n                </p>\r\n\r\n                <p class=\"ukt-agnihotra-record-text mb-0\">\r\n                    You will need to have Cow Dung, Ghee and unbroken Rice, which is a daily consumption.\r\n                </p>\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n</article>', 'Agnihotra Procedure', '', 'publish', 'closed', 'closed', '', 'agnihotra-procedure', '', '', '2026-10-26 17:30:50', '2026-10-26 12:00:50', '', 0, 'http://localhost/universal-knowledge-trust-wordpress/?page_id=245', 0, 'page', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(246, 1, '2026-10-26 17:30:50', '2026-10-26 12:00:50', '<article>\r\n    <!-- =========================================================\r\n         AGNIHOTRA PROCEDURES HERO SECTION (MATCHING INDEX HERO SHOWCASE)\r\n    ========================================================== -->\r\n    <section class=\"ukt-hero-showcase\">\r\n        <div class=\"ukt-hero-slide-layout\">\r\n            <div class=\"container-fluid\">\r\n                <div class=\"row g-0 align-items-stretch\">\r\n\r\n                    <!-- LEFT CONTENT AREA -->\r\n                    <div class=\"col-lg-5 d-flex align-items-center\">\r\n                        <div class=\"ukt-hero-copy-zone\">\r\n                            <div class=\"ukt-hero-left-decoration\"></div>\r\n\r\n                            <div class=\"ukt-hero-slide-kicker\">\r\n                                Universal Knowledge Trust\r\n                            </div>\r\n\r\n                            <h1 class=\"ukt-hero-main-title\">\r\n                                <span>An Ancient Practice</span>\r\n                                <span>for a Harmonious Way of Life.</span>\r\n                            </h1>\r\n\r\n                            <div class=\"ukt-hero-script-line\">\r\n                                Physical, Mental &amp; Spiritual Well-Being\r\n                            </div>\r\n\r\n                            <p class=\"ukt-hero-description\">\r\n                                Discover Agnihotra, an ancient Vedic fire practice traditionally performed at\r\n                                sunrise and sunset. Explore its purpose, the materials involved, the procedure, and\r\n                                how you can become part of a larger Agnihotra initiative.\r\n                            </p>\r\n\r\n                            <div class=\"ukt-hero-action-row\">\r\n                                <a href=\"#agnihotra_procedure\" class=\"ukt-hero-primary-action\">\r\n                                    Explore Procedure\r\n                                    <i class=\"bi bi-arrow-right\"></i>\r\n                                </a>\r\n                            </div>\r\n\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- RIGHT IMAGE AREA -->\r\n                    <div class=\"col-lg-7\">\r\n                        <div class=\"ukt-hero-visual-zone\">\r\n                            <div class=\"ukt-hero-image-frame\">\r\n                                <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-procedure-banner.jpg\"\r\n                                    alt=\"Agnihotra Procedure - An Ancient Practice for a Harmonious Way of Life\"\r\n                                    title=\"Agnihotra Procedure Banner\">\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         SECTION: WHAT IS AGNIHOTRA (OVERVIEW)\r\n    ========================================================== -->\r\n    <section class=\"ukt-agni-intro-section py-5\">\r\n        <div class=\"container py-lg-3\">\r\n            <div class=\"row align-items-center justify-content-between g-4\">\r\n                <div class=\"col-lg-7 col-md-12\">\r\n                    <div class=\"pe-0 pe-lg-3\">\r\n                        <div class=\"ukt-section-eyebrow text-start m-0 mb-2\">\r\n                            <span></span>\r\n                            ANCIENT VEDIC KNOWLEDGE\r\n                        </div>\r\n                        <h2 class=\"ukt-section-main-title mb-2\">\r\n                            What is <span>Agnihotra?</span>\r\n                        </h2>\r\n                        <div class=\"ukt-section-heading-design m-0 mb-3 justify-content-start\">\r\n                            <span></span>\r\n                            <i class=\"bi bi-flower1\"></i>\r\n                            <span></span>\r\n                        </div>\r\n\r\n                        <p class=\"ukt-agni-intro-lead\">\r\n                            Angihotra, also known as Agnihotra, is an ancient Vedic fire ritual originating from India. It’s a powerful practice for physical, mental, and spiritual well-being. Here’s a step-by-step guide:\r\n                        </p>\r\n\r\n                        <!-- <p class=\"ukt-agni-intro-text\">\r\n                            Performed at exact sunrise and sunset with authentic copper pyramid vessels, pure cow\r\n                            ghee, dry cow dung, and unbroken rice, Agnihotra creates a powerful purification field\r\n                            that revitalizes plant life, cleanses the surrounding air, reduces stress, and promotes\r\n                            holistic physical, mental, and spiritual well-being.\r\n                        </p> -->\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"col-lg-5 col-md-12 d-flex align-items-center justify-content-center\">\r\n                    <figure>\r\n                        <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-what-is-section1.jpg\"\r\n                            alt=\"Agnihotra Sacred Fire Ritual - Copper Pyramid with Sacred Fire at Sunrise\"\r\n                            title=\"What is Agnihotra Sacred Fire Ritual\" class=\"ukt-agnihotra-poster-img img-fluid\"\r\n                            loading=\"lazy\">\r\n                        <figcaption class=\"cr-only\">\r\n                            Agnihotra bio-energetic fire process to honor Agni and Surya, performed at exact sunrise\r\n                            and sunset for atmospheric purification and holistic well-being.\r\n                        </figcaption>\r\n                    </figure>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </section>\r\n\r\n\r\n    <!-- =========================================================\r\n         SECTION: STEP-BY-STEP AGNIHOTRA PROCEDURE\r\n    ========================================================== -->\r\n    <section id=\"agnihotra_procedure\" class=\"ukt-agni-procedure-section py-5\">\r\n        <div class=\"container py-lg-4\">\r\n\r\n            <!-- SECTION HEADER -->\r\n            <div class=\"ukt-section-header\">\r\n                <div class=\"ukt-section-eyebrow\">\r\n                    <span></span>\r\n                    STEP-BY-STEP RITUAL GUIDE\r\n                    <span></span>\r\n                </div>\r\n                <h2 class=\"ukt-section-main-title\">\r\n                    How to Perform <span>Agnihotra</span>\r\n                </h2>\r\n                <div class=\"ukt-section-heading-design\">\r\n                    <span></span>\r\n                    <i class=\"bi bi-flower1\"></i>\r\n                    <span></span>\r\n                </div>\r\n                <p class=\"ukt-agni-procedure-subtitle text-center mx-auto mt-2\">\r\n                    Comprehensive guide covering authentic materials, pre-ritual preparation, sunrise and sunset\r\n                    procedures, safety precautions, and holistic benefits.\r\n                </p>\r\n            </div>\r\n\r\n            <!-- ALL PROCEDURE CARDS (STACKED VERTICALLY) -->\r\n            <div class=\"ukt-agni-procedure-cards d-flex flex-column\">\r\n\r\n\r\n                <!-- ════════════════════════════════════════════════\r\n                     CARD 1: MATERIALS NEEDED\r\n                ════════════════════════════════════════════════ -->\r\n                <div class=\"ukt-agni-card ukt-agni-card-amber text-start\">\r\n                    <!-- Gradient top accent -->\r\n                    <div class=\"ukt-agni-card-accent\"></div>\r\n\r\n                    <!-- Header -->\r\n                    <div class=\"d-flex align-items-center gap-3 mb-4\">\r\n                        <div class=\"ukt-agni-card-icon\">\r\n                            <i class=\"bi bi-box-seam-fill\"></i>\r\n                        </div>\r\n                        <div>\r\n                            <div class=\"ukt-agni-card-badge\">Step 1</div>\r\n                            <h3 class=\"ukt-agni-card-title\">Materials Needed</h3>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- Items Grid -->\r\n                    <div class=\"row g-3\">\r\n                        <div class=\"col-lg-4 col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-material-item\">\r\n                                <div class=\"ukt-agni-material-icon\">\r\n                                    <i class=\"bi bi-triangle-fill\"></i>\r\n                                </div>\r\n                                <span class=\"ukt-agni-material-label\">Copper Pyramid</span>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-lg-4 col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-material-item\">\r\n                                <div class=\"ukt-agni-material-icon\">\r\n                                    <i class=\"bi bi-droplet-fill\"></i>\r\n                                </div>\r\n                                <span class=\"ukt-agni-material-label\">Ghee (Clarified Butter)</span>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-lg-4 col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-material-item\">\r\n                                <div class=\"ukt-agni-material-icon\">\r\n                                    <i class=\"bi bi-circle-fill\"></i>\r\n                                </div>\r\n                                <span class=\"ukt-agni-material-label\">Rice Grains</span>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-lg-4 col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-material-item\">\r\n                                <div class=\"ukt-agni-material-icon\">\r\n                                    <i class=\"bi bi-fire\"></i>\r\n                                </div>\r\n                                <span class=\"ukt-agni-material-label\">Cow Dung Cakes</span>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-lg-4 col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-material-item\">\r\n                                <div class=\"ukt-agni-material-icon\">\r\n                                    <i class=\"bi bi-lightning-charge-fill\"></i>\r\n                                </div>\r\n                                <span class=\"ukt-agni-material-label\">Matches / Lighter</span>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-lg-4 col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-material-item\">\r\n                                <div class=\"ukt-agni-material-icon\">\r\n                                    <i class=\"bi bi-clock-fill\"></i>\r\n                                </div>\r\n                                <span class=\"ukt-agni-material-label\">Timing Device</span>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n\r\n                <!-- ════════════════════════════════════════════════\r\n                     CARD 2: PREPARATION\r\n                ════════════════════════════════════════════════ -->\r\n                <div class=\"ukt-agni-card ukt-agni-card-teal text-start\">\r\n                    <div class=\"ukt-agni-card-accent\"></div>\r\n\r\n                    <div class=\"d-flex align-items-center gap-3 mb-4\">\r\n                        <div class=\"ukt-agni-card-icon\">\r\n                            <i class=\"bi bi-clipboard2-check-fill\"></i>\r\n                        </div>\r\n                        <div>\r\n                            <div class=\"ukt-agni-card-badge\">Step 2</div>\r\n                            <h3 class=\"ukt-agni-card-title\">Preparation</h3>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"ukt-agni-step-list d-flex flex-column\">\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <div class=\"ukt-agni-step-num\">1</div>\r\n                            <p class=\"ukt-agni-step-desc\">Choose a quiet, clean space for the ritual.</p>\r\n                        </div>\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <div class=\"ukt-agni-step-num\">2</div>\r\n                            <p class=\"ukt-agni-step-desc\">Set up the copper pyramid on a heat-resistant surface.</p>\r\n                        </div>\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <div class=\"ukt-agni-step-num\">3</div>\r\n                            <p class=\"ukt-agni-step-desc\">Prepare ghee and rice grains.</p>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"text-center pt-3\">\r\n                        <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/agnihotra-world-record/31-U3L5RSFL-300x236-1.webp\"\r\n                            alt=\"Agnihotra Copper Pyramid Kit\" title=\"Agnihotra Copper Pyramid Kit\"\r\n                            class=\"img-fluid rounded ukt-procedure-kit-img\" loading=\"lazy\">\r\n                    </div>\r\n                </div>\r\n\r\n\r\n                <!-- ════════════════════════════════════════════════\r\n                     CARD 3: SUNRISE AGNIHOTRA PROCEDURE\r\n                ════════════════════════════════════════════════ -->\r\n                <div class=\"ukt-agni-card ukt-agni-card-orange text-start\">\r\n                    <div class=\"ukt-agni-card-accent\"></div>\r\n\r\n                    <div class=\"d-flex align-items-center gap-3 mb-4\">\r\n                        <div class=\"ukt-agni-card-icon\">\r\n                            <i class=\"bi bi-sunrise-fill\"></i>\r\n                        </div>\r\n                        <div>\r\n                            <div class=\"ukt-agni-card-badge\">Step 3 · Morning Ritual</div>\r\n                            <h3 class=\"ukt-agni-card-title\">Sunrise Agnihotra</h3>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"ukt-agni-step-list d-flex flex-column\">\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <span class=\"ukt-agni-step-num\">1</span>\r\n                            <p class=\"ukt-agni-step-desc\">Calculate local sunrise time.</p>\r\n                        </div>\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <span class=\"ukt-agni-step-num\">2</span>\r\n                            <p class=\"ukt-agni-step-desc\">Light the fire 10–15 minutes before sunrise.</p>\r\n                        </div>\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <span class=\"ukt-agni-step-num\">3</span>\r\n                            <p class=\"ukt-agni-step-desc\">Add 2–3 pinches of rice grains to the fire.</p>\r\n                        </div>\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <span class=\"ukt-agni-step-num\">4</span>\r\n                            <p class=\"ukt-agni-step-desc\">Add 2–3 drops of ghee to the fire.</p>\r\n                        </div>\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <span class=\"ukt-agni-step-num\">5</span>\r\n                            <p class=\"ukt-agni-step-desc\">Recite the 2 mantras:</p>\r\n                        </div>\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <span class=\"ukt-agni-step-num\">6</span>\r\n                            <p class=\"ukt-agni-step-desc\">Repeat steps 3–5 for 10–15 minutes.</p>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n\r\n                <!-- ════════════════════════════════════════════════\r\n                     CARD 4: SUNSET AGNIHOTRA PROCEDURE\r\n                ════════════════════════════════════════════════ -->\r\n                <div class=\"ukt-agni-card ukt-agni-card-purple text-start\">\r\n                    <div class=\"ukt-agni-card-accent\"></div>\r\n\r\n                    <div class=\"d-flex align-items-center gap-3 mb-4\">\r\n                        <div class=\"ukt-agni-card-icon\">\r\n                            <i class=\"bi bi-sunset-fill\"></i>\r\n                        </div>\r\n                        <div>\r\n                            <div class=\"ukt-agni-card-badge\">Step 4 · Evening Ritual</div>\r\n                            <h3 class=\"ukt-agni-card-title\">Sunset Agnihotra</h3>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"ukt-agni-step-list d-flex flex-column\">\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <span class=\"ukt-agni-step-num\">1</span>\r\n                            <p class=\"ukt-agni-step-desc\">Calculate local sunset time.</p>\r\n                        </div>\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <span class=\"ukt-agni-step-num\">2</span>\r\n                            <p class=\"ukt-agni-step-desc\">Light the fire 10–15 minutes before sunset.</p>\r\n                        </div>\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <span class=\"ukt-agni-step-num\">3</span>\r\n                            <p class=\"ukt-agni-step-desc\">Add 2–3 pinches of rice grains to the fire.</p>\r\n                        </div>\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <span class=\"ukt-agni-step-num\">4</span>\r\n                            <p class=\"ukt-agni-step-desc\">Add 2–3 drops of ghee to the fire.</p>\r\n                        </div>\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <span class=\"ukt-agni-step-num\">5</span>\r\n                            <p class=\"ukt-agni-step-desc\">Recite the 2 mantras:</p>\r\n                        </div>\r\n                        <div class=\"ukt-agni-step-item\">\r\n                            <span class=\"ukt-agni-step-num\">6</span>\r\n                            <p class=\"ukt-agni-step-desc\">Repeat steps 3–5 for 10–15 minutes.</p>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n\r\n                <!-- ════════════════════════════════════════════════\r\n                     CARD 5: TIPS & PRECAUTIONS\r\n                ════════════════════════════════════════════════ -->\r\n                <div class=\"ukt-agni-card ukt-agni-card-emerald text-start\">\r\n                    <div class=\"ukt-agni-card-accent\"></div>\r\n\r\n                    <div class=\"d-flex align-items-center gap-3 mb-4\">\r\n                        <div class=\"ukt-agni-card-icon\">\r\n                            <i class=\"bi bi-shield-fill-check\"></i>\r\n                        </div>\r\n                        <div>\r\n                            <div class=\"ukt-agni-card-badge\">Guidelines &amp; Safety</div>\r\n                            <h3 class=\"ukt-agni-card-title\">Tips &amp; Precautions</h3>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"row g-3\">\r\n                        <div class=\"col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-tip-item\">\r\n                                <i class=\"bi bi-alarm-fill ukt-agni-tip-icon\"></i>\r\n                                <span class=\"ukt-agni-tip-text\">Use a timer to synchronize with sunrise/sunset.</span>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-tip-item\">\r\n                                <i class=\"bi bi-calendar-check-fill ukt-agni-tip-icon\"></i>\r\n                                <span class=\"ukt-agni-tip-text\">Maintain a consistent schedule.</span>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-tip-item\">\r\n                                <i class=\"bi bi-house-check-fill ukt-agni-tip-icon\"></i>\r\n                                <span class=\"ukt-agni-tip-text\">Keep the area clean and free from distractions.</span>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-tip-item\">\r\n                                <i class=\"bi bi-heart-pulse-fill ukt-agni-tip-icon\"></i>\r\n                                <span class=\"ukt-agni-tip-text\">Avoid performing Agnihotra during menstruation or when feeling unwell.</span>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-12\">\r\n                            <div class=\"ukt-agni-tip-item\">\r\n                                <i class=\"bi bi-exclamation-triangle-fill ukt-agni-tip-icon\"></i>\r\n                                <span class=\"ukt-agni-tip-text\">Respect the fire and handle it carefully.</span>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n\r\n                <!-- ════════════════════════════════════════════════\r\n                     CARD 6: BENEFITS\r\n                ════════════════════════════════════════════════ -->\r\n                <div class=\"ukt-agni-card ukt-agni-card-gold text-start\">\r\n                    <div class=\"ukt-agni-card-accent\"></div>\r\n\r\n                    <div class=\"d-flex align-items-center gap-3 mb-4\">\r\n                        <div class=\"ukt-agni-card-icon\">\r\n                            <i class=\"bi bi-stars\"></i>\r\n                        </div>\r\n                        <div>\r\n                            <div class=\"ukt-agni-card-badge\">Transformation</div>\r\n                            <h3 class=\"ukt-agni-card-title\">Benefits</h3>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"row g-3\">\r\n                        <div class=\"col-lg-4 col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-benefit-item\">\r\n                                <div class=\"ukt-agni-benefit-icon\">\r\n                                    <i class=\"bi bi-cloud-sun-fill\"></i>\r\n                                </div>\r\n                                <span class=\"ukt-agni-benefit-label\">Purifies the Environment</span>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-lg-4 col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-benefit-item\">\r\n                                <div class=\"ukt-agni-benefit-icon\">\r\n                                    <i class=\"bi bi-brain\"></i>\r\n                                </div>\r\n                                <span class=\"ukt-agni-benefit-label\">Mental Clarity &amp; Focus</span>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-lg-4 col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-benefit-item\">\r\n                                <div class=\"ukt-agni-benefit-icon\">\r\n                                    <i class=\"bi bi-activity\"></i>\r\n                                </div>\r\n                                <span class=\"ukt-agni-benefit-label\">Enhances Physical Health</span>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-lg-6 col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-benefit-item\">\r\n                                <div class=\"ukt-agni-benefit-icon\">\r\n                                    <i class=\"bi bi-heart-pulse-fill\"></i>\r\n                                </div>\r\n                                <span class=\"ukt-agni-benefit-label\">Reduces Stress &amp; Anxiety</span>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-lg-6 col-md-6 col-12\">\r\n                            <div class=\"ukt-agni-benefit-item\">\r\n                                <div class=\"ukt-agni-benefit-icon\">\r\n                                    <i class=\"bi bi-peace\"></i>\r\n                                </div>\r\n                                <span class=\"ukt-agni-benefit-label\">Promotes Spiritual Growth</span>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n            </div><!-- /.d-flex flex-column -->\r\n\r\n\r\n            <!-- ════════════════════════════════════════════════\r\n                 RESOURCES\r\n            ════════════════════════════════════════════════ -->\r\n            <div class=\"ukt-practical-unified-card mt-4 mb-3 text-start\">\r\n                <div class=\"ukt-practical-accent-bar\"></div>\r\n                <h3 class=\"ukt-practical-title ukt-practical-title-md mb-2\">\r\n                    <i class=\"bi bi-journal-bookmark-fill ukt-icon-gold\"></i> Resources:\r\n                </h3>\r\n                <ul class=\"ukt-practical-list-nomargin\">\r\n                    <li class=\"ukt-practical-list-item\">\r\n                        <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                        <div>1. Consult Vedic texts or experienced practitioners for guidance.</div>\r\n                    </li>\r\n                    <li class=\"ukt-practical-list-item\">\r\n                        <i class=\"bi bi-circle-fill ukt-practical-dot-gold\"></i>\r\n                        <div>2. Visit <a href=\"#\" class=\"ukt-agnihotra-link-teal fw-bold text-decoration-none\">Agnihotra Procedure</a> for more information.</div>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n\r\n            <!-- ════════════════════════════════════════════════\r\n                 CONSISTENCY CALLOUT\r\n            ════════════════════════════════════════════════ -->\r\n            <div class=\"ukt-agni-consistency-callout\">\r\n                <i class=\"bi bi-fire ukt-agni-consistency-icon me-2\"></i>\r\n                <span class=\"ukt-agni-consistency-text\">\r\n                    Remember, consistency and sincerity are key to experiencing the benefits of Agnihotra.\r\n                </span>\r\n            </div>\r\n\r\n            <!-- ════════════════════════════════════════════════\r\n                 WORLD RECORD PARTICIPATION PARAGRAPHS\r\n            ════════════════════════════════════════════════ -->\r\n            <div class=\"mt-4 text-start\">\r\n                <p class=\"ukt-agnihotra-record-text mb-2\">\r\n                    Gram Vikas Society (GVS) creating a World Record by lighting Agnihotra at 11,000 + at single location.Powered by Universal Knowledge.\r\n                </p>\r\n\r\n                <p class=\"ukt-agnihotra-record-text mb-3\">\r\n                    This is an unique program and we will join to have a Agnihotra done at 11,000 different houses / offices in and around Karnataka\r\n                </p>\r\n\r\n                <h4 class=\"ukt-agnihotra-record-subheading fw-bold mb-2\">\r\n                    How you can be a part of this world record?\r\n                </h4>\r\n\r\n                <p class=\"ukt-agnihotra-record-text mb-2\">\r\n                    If you are willing to participate and have agnihotra done at your house or office daily, you can apply at the link below;\r\n                </p>\r\n\r\n                <p class=\"ukt-agnihotra-record-text mb-2\">\r\n                    GVS will provide you with free startup Agnihotra kit, which will include Copper pyramid Bowl, startup material for 4 days worth ₹ 1,250/-.\r\n                </p>\r\n\r\n                <p class=\"ukt-agnihotra-record-text mb-0\">\r\n                    You will need to have Cow Dung, Ghee and unbroken Rice, which is a daily consumption.\r\n                </p>\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n</article>', 'Agnihotra Procedure', '', 'inherit', 'closed', 'closed', '', '245-revision-v1', '', '', '2026-10-26 17:30:50', '2026-10-26 12:00:50', '', 245, 'http://localhost/universal-knowledge-trust-wordpress/?p=246', 0, 'revision', '', 0),
(247, 1, '2026-10-26 17:31:09', '2026-10-26 12:01:09', ' ', '', '', 'publish', 'closed', 'closed', '', '247', '', '', '2026-10-26 17:31:09', '2026-10-26 12:01:09', '', 0, 'http://localhost/universal-knowledge-trust-wordpress/?p=247', 2, 'nav_menu_item', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(248, 1, '2026-10-26 17:38:43', '2026-10-26 12:08:43', '<article>\r\n\r\n    <!-- =========================================================\r\n         DONATIONS & SEVA BANNER / HERO SECTION\r\n         (Matches index showcase hero layout)\r\n    ========================================================== -->\r\n    <section class=\"ukt-hero-showcase\">\r\n        <div class=\"ukt-hero-slide-layout\">\r\n            <div class=\"container-fluid\">\r\n                <div class=\"row g-0 align-items-stretch\">\r\n\r\n                    <!-- LEFT CONTENT AREA -->\r\n                    <div class=\"col-lg-5 d-flex align-items-center\">\r\n                        <div class=\"ukt-hero-copy-zone\">\r\n                            <div class=\"ukt-hero-left-decoration\"></div>\r\n\r\n                            <div class=\"ukt-hero-slide-kicker\">\r\n                                <i class=\"bi bi-heart-fill me-1 ukt-hero-kicker-icon\"></i> Universal Knowledge Trust • Seva &amp; Giving\r\n                            </div>\r\n\r\n                            <h1 class=\"ukt-hero-main-title\">\r\n                                <span>Empower Lives.</span>\r\n                                <span>Share the Light.</span>\r\n                            </h1>\r\n\r\n                            <div class=\"ukt-hero-script-line\">\r\n                                Compassion · Annadana · Upliftment\r\n                            </div>\r\n\r\n                            <p class=\"ukt-hero-description\">\r\n                                Dedicated to selfless service and holistic well-being. Your compassionate contributions support daily nutritious food distribution (Annadana), values-based school training programs, environmental tree plantations, and free positive energy healing for underprivileged communities.\r\n                            </p>\r\n\r\n                            <div class=\"ukt-hero-action-row\">\r\n                                <a href=\"#bank-details\" class=\"ukt-hero-primary-action\">\r\n                                    Contribute Online <i class=\"bi bi-arrow-down-circle-fill ms-1\"></i>\r\n                                </a>\r\n\r\n                                <a href=\"#seva-causes\" class=\"ukt-hero-secondary-action\">\r\n                                    Our Seva Causes\r\n                                </a>\r\n                            </div>\r\n\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- RIGHT IMAGE AREA -->\r\n                    <div class=\"col-lg-7\">\r\n                        <div class=\"ukt-hero-visual-zone\">\r\n                            <div class=\"ukt-hero-image-frame\">\r\n                                <figure class=\"ukt-hero-image-figure\">\r\n                                    <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/donations-banner.jpg\"\r\n                                        alt=\"Universal Knowledge Trust - Selfless Giving, Annadana and Humanitarian Seva\"\r\n                                        loading=\"eager\">\r\n                                    <figcaption class=\"visually-hidden\">Universal Knowledge Trust - Selfless Giving, Annadana and Humanitarian Seva</figcaption>\r\n                                </figure>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         CORE SEVA INITIATIVES / CAUSES\r\n    ========================================================== -->\r\n    <section class=\"py-5 ukt-donations-causes-section\" id=\"seva-causes\">\r\n        <div class=\"container py-lg-4\">\r\n\r\n            <!-- HEADER -->\r\n            <div class=\"text-center mb-5\">\r\n                <span class=\"ukt-donations-section-kicker\">\r\n                    &mdash;&mdash; &nbsp; WAYS YOUR GENEROSITY HELPS &nbsp; &mdash;&mdash;\r\n                </span>\r\n                <h2 class=\"mt-2 mb-3 ukt-donations-section-title\">\r\n                    Our Core Seva Initiatives\r\n                </h2>\r\n                <p class=\"ukt-donations-section-desc\">\r\n                    Every rupee contributed is dedicated with absolute purity, transparency, and reverence toward the holistic upliftment of human lives and nature.\r\n                </p>\r\n            </div>\r\n\r\n            <!-- 4 CAUSES GRID -->\r\n            <div class=\"row g-4\">\r\n\r\n                <!-- CAUSE 1: ANNADANA -->\r\n                <div class=\"col-lg-6 col-md-6\">\r\n                    <div class=\"card h-100 border-0 rounded-4 shadow-sm p-4 p-lg-5 ukt-donation-cause-card\">\r\n                        <div class=\"d-flex align-items-center justify-content-between mb-4\">\r\n                            <div class=\"ukt-donation-cause-icon ukt-cause-icon-food\">\r\n                                <i class=\"bi bi-cup-hot-fill\"></i>\r\n                            </div>\r\n                            <span class=\"badge rounded-pill fw-semibold ukt-cause-badge\">\r\n                                Daily Food Relief\r\n                            </span>\r\n                        </div>\r\n                        <h3 class=\"h4 mb-3 ukt-cause-card-title\">\r\n                            Annadana Seva &mdash; Nutritious Meals\r\n                        </h3>\r\n                        <p class=\"ukt-cause-card-desc\">\r\n                            Serving wholesome, hot vegetarian meals and fresh grains to impoverished families, disadvantaged children, and elderly citizens. Your support ensures no one in our reach sleeps hungry.\r\n                        </p>\r\n                        <div class=\"mt-auto pt-3 border-top border-light-subtle d-flex align-items-center justify-content-between\">\r\n                            <span class=\"small text-muted\"><i class=\"bi bi-check2-circle text-success me-1\"></i> Cooked with love &amp; hygiene</span>\r\n                            <a href=\"#bank-details\" class=\"text-decoration-none fw-semibold small ukt-cause-card-link-food\">\r\n                                Sponsor Meals <i class=\"bi bi-arrow-right\"></i>\r\n                            </a>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- CAUSE 2: SCHOOL & YOUTH -->\r\n                <div class=\"col-lg-6 col-md-6\">\r\n                    <div class=\"card h-100 border-0 rounded-4 shadow-sm p-4 p-lg-5 ukt-donation-cause-card\">\r\n                        <div class=\"d-flex align-items-center justify-content-between mb-4\">\r\n                            <div class=\"ukt-donation-cause-icon ukt-cause-icon-school\">\r\n                                <i class=\"bi bi-mortarboard-fill\"></i>\r\n                            </div>\r\n                            <span class=\"badge rounded-pill fw-semibold ukt-cause-badge\">\r\n                                200,000+ Students Reached\r\n                            </span>\r\n                        </div>\r\n                        <h3 class=\"h4 mb-3 ukt-cause-card-title\">\r\n                            Youth &amp; School Value Education\r\n                        </h3>\r\n                        <p class=\"ukt-cause-card-desc\">\r\n                            Providing free workshops, Super Brain Yoga, concentration tools, positive habit modules, and educational materials to government and rural school children across Karnataka.\r\n                        </p>\r\n                        <div class=\"mt-auto pt-3 border-top border-light-subtle d-flex align-items-center justify-content-between\">\r\n                            <span class=\"small text-muted\"><i class=\"bi bi-check2-circle text-success me-1\"></i> Inspiring young leaders</span>\r\n                            <a href=\"#bank-details\" class=\"text-decoration-none fw-semibold small ukt-cause-card-link-school\">\r\n                                Sponsor Students <i class=\"bi bi-arrow-right\"></i>\r\n                            </a>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- CAUSE 3: VRIKSHA SEVA -->\r\n                <div class=\"col-lg-6 col-md-6\">\r\n                    <div class=\"card h-100 border-0 rounded-4 shadow-sm p-4 p-lg-5 ukt-donation-cause-card\">\r\n                        <div class=\"d-flex align-items-center justify-content-between mb-4\">\r\n                            <div class=\"ukt-donation-cause-icon ukt-cause-icon-green\">\r\n                                <i class=\"bi bi-tree-fill\"></i>\r\n                            </div>\r\n                            <span class=\"badge rounded-pill fw-semibold ukt-cause-badge-green\">\r\n                                Mother Earth Harmony\r\n                            </span>\r\n                        </div>\r\n                        <h3 class=\"h4 mb-3 ukt-cause-card-title\">\r\n                            Tree Plantations &amp; Environmental Seva\r\n                        </h3>\r\n                        <p class=\"ukt-cause-card-desc\">\r\n                            Afforestation drives, planting indigenous and medicinal saplings, conducting Vedic Agnihotra atmospheric purification, and spreading ecological conservation awareness.\r\n                        </p>\r\n                        <div class=\"mt-auto pt-3 border-top border-light-subtle d-flex align-items-center justify-content-between\">\r\n                            <span class=\"small text-muted\"><i class=\"bi bi-check2-circle text-success me-1\"></i> Green eco-initiatives</span>\r\n                            <a href=\"#bank-details\" class=\"text-decoration-none fw-semibold small ukt-cause-card-link-green\">\r\n                                Sponsor a Tree <i class=\"bi bi-arrow-right\"></i>\r\n                            </a>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- CAUSE 4: NATURAL HEALING -->\r\n                <div class=\"col-lg-6 col-md-6\">\r\n                    <div class=\"card h-100 border-0 rounded-4 shadow-sm p-4 p-lg-5 ukt-donation-cause-card\">\r\n                        <div class=\"d-flex align-items-center justify-content-between mb-4\">\r\n                            <div class=\"ukt-donation-cause-icon ukt-cause-icon-healing\">\r\n                                <i class=\"bi bi-flower1\"></i>\r\n                            </div>\r\n                            <span class=\"badge rounded-pill fw-semibold ukt-cause-badge\">\r\n                                Healing &amp; Wellness\r\n                            </span>\r\n                        </div>\r\n                        <h3 class=\"h4 mb-3 ukt-cause-card-title\">\r\n                            Free Positive Energy Healing Camps\r\n                        </h3>\r\n                        <p class=\"ukt-cause-card-desc\">\r\n                            Conducting free Natural Positive Energy Healing (NPEH), chakra balancing, meditation, and stress alleviation sessions for individuals, families, and senior citizens needing care.\r\n                        </p>\r\n                        <div class=\"mt-auto pt-3 border-top border-light-subtle d-flex align-items-center justify-content-between\">\r\n                            <span class=\"small text-muted\"><i class=\"bi bi-check2-circle text-success me-1\"></i> Certified healers &amp; mentors</span>\r\n                            <a href=\"#bank-details\" class=\"text-decoration-none fw-semibold small ukt-cause-card-link-school\">\r\n                                Support Healing <i class=\"bi bi-arrow-right\"></i>\r\n                            </a>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         OFFICIAL TRUST BANK & PAYMENT DETAILS SECTION\r\n    ========================================================== -->\r\n    <section class=\"py-5 ukt-donations-banking-section\" id=\"bank-details\">\r\n        <div class=\"container py-lg-4\">\r\n\r\n            <!-- HEADER -->\r\n            <div class=\"text-center mb-5\">\r\n                <span class=\"ukt-donations-gold-kicker\">\r\n                    &mdash;&mdash; &nbsp; SECURE &amp; DIRECT DONATION &nbsp; &mdash;&mdash;\r\n                </span>\r\n                <h2 class=\"mt-2 mb-3 ukt-banking-section-title\">\r\n                    Official Trust <span>Banking Details</span>\r\n                </h2>\r\n                <p class=\"ukt-banking-section-desc\">\r\n                    Contributions can be transferred directly via NEFT, RTGS, IMPS, or UPI to the official registered account of Universal Knowledge Trust.\r\n                </p>\r\n            </div>\r\n\r\n            <!-- MAIN BANKING & UPI CARDS CONTAINER -->\r\n            <div class=\"row g-4 justify-content-center\">\r\n\r\n                <!-- LEFT: OFFICIAL BANK ACCOUNT CARD -->\r\n                <div class=\"col-lg-7\">\r\n                    <div class=\"card border-0 rounded-4 shadow-sm h-100 p-4 p-md-5 ukt-banking-details-card\">\r\n\r\n                        <div class=\"d-flex align-items-center gap-3 mb-4 pb-3 border-bottom ukt-banking-card-header\">\r\n                            <div class=\"ukt-banking-header-icon\">\r\n                                <i class=\"bi bi-bank2\"></i>\r\n                            </div>\r\n                            <div>\r\n                                <h3 class=\"h5 mb-1 ukt-banking-card-title\">\r\n                                    Direct Bank Transfer (NEFT / RTGS / IMPS)\r\n                                </h3>\r\n                                <span class=\"badge text-bg-light border small\">Public Charitable Trust Account</span>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <!-- BANK DETAILS LIST -->\r\n                        <div class=\"d-flex flex-column gap-3 mb-4\">\r\n\r\n                            <!-- Field 1: Account Name -->\r\n                            <div class=\"p-3 rounded-3 ukt-banking-item-box\">\r\n                                <div class=\"small text-muted text-uppercase fw-semibold ukt-banking-item-label\">Account Name</div>\r\n                                <div class=\"d-flex align-items-center justify-content-between mt-1\">\r\n                                    <strong class=\"fs-6 text-dark\" id=\"accNameText\">Universal knowledge Trust</strong>\r\n                                    <button type=\"button\" class=\"btn btn-sm btn-outline-secondary py-0 px-2\" onclick=\"copyText(\'accNameText\', this)\" title=\"Copy Account Name\">\r\n                                        <i class=\"bi bi-clipboard me-1\"></i>Copy\r\n                                    </button>\r\n                                </div>\r\n                            </div>\r\n\r\n                            <!-- Field 2: Account Number -->\r\n                            <div class=\"p-3 rounded-3 ukt-banking-item-box\">\r\n                                <div class=\"small text-muted text-uppercase fw-semibold ukt-banking-item-label\">Account Number</div>\r\n                                <div class=\"d-flex align-items-center justify-content-between mt-1\">\r\n                                    <strong class=\"fs-5 fw-bold ukt-banking-acc-number\" id=\"accNumText\">4792000100073301</strong>\r\n                                    <button type=\"button\" class=\"btn btn-sm btn-outline-secondary py-0 px-2\" onclick=\"copyText(\'accNumText\', this)\" title=\"Copy Account Number\">\r\n                                        <i class=\"bi bi-clipboard me-1\"></i>Copy\r\n                                    </button>\r\n                                </div>\r\n                            </div>\r\n\r\n                            <!-- Field 3: Bank Name & Account Type -->\r\n                            <div class=\"row g-2\">\r\n                                <div class=\"col-sm-6\">\r\n                                    <div class=\"p-3 rounded-3 h-100 ukt-banking-item-box\">\r\n                                        <div class=\"small text-muted text-uppercase fw-semibold ukt-banking-item-label\">Bank Name</div>\r\n                                        <strong class=\"text-dark d-block mt-1\">Karnataka Bank</strong>\r\n                                    </div>\r\n                                </div>\r\n                                <div class=\"col-sm-6\">\r\n                                    <div class=\"p-3 rounded-3 h-100 ukt-banking-item-box\">\r\n                                        <div class=\"small text-muted text-uppercase fw-semibold ukt-banking-item-label\">Account Type</div>\r\n                                        <strong class=\"text-dark d-block mt-1\">Current account</strong>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n\r\n                            <!-- Field 4: IFSC Code -->\r\n                            <div class=\"p-3 rounded-3 ukt-banking-item-box\">\r\n                                <div class=\"small text-muted text-uppercase fw-semibold ukt-banking-item-label\">IFSC Code</div>\r\n                                <div class=\"d-flex align-items-center justify-content-between mt-1\">\r\n                                    <strong class=\"fs-6 fw-bold ukt-banking-ifsc\" id=\"ifscText\">KARB0000479</strong>\r\n                                    <button type=\"button\" class=\"btn btn-sm btn-outline-secondary py-0 px-2\" onclick=\"copyText(\'ifscText\', this)\" title=\"Copy IFSC Code\">\r\n                                        <i class=\"bi bi-clipboard me-1\"></i>Copy\r\n                                    </button>\r\n                                </div>\r\n                            </div>\r\n\r\n                            <!-- Field 5: Branch -->\r\n                            <div class=\"p-3 rounded-3 ukt-banking-item-box\">\r\n                                <div class=\"small text-muted text-uppercase fw-semibold ukt-banking-item-label\">Branch Location</div>\r\n                                <strong class=\"text-dark d-block mt-1\">Mannagudda Branch</strong>\r\n                            </div>\r\n\r\n                        </div>\r\n\r\n                        <!-- RECEIPT NOTE -->\r\n                        <div class=\"alert alert-light border rounded-3 p-3 mb-0 ukt-banking-receipt-alert\">\r\n                            <div class=\"d-flex gap-2\">\r\n                                <i class=\"bi bi-shield-check text-success fs-5\"></i>\r\n                                <div class=\"small text-dark\">\r\n                                    <strong>Official Trust Receipts:</strong> Please share your transfer screenshot along with your full name and address via WhatsApp at <a href=\"https://wa.me/919632171156\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"fw-bold text-success text-decoration-none\">+91 96321 71156</a> or email <a href=\"mailto:UniversalknowledgR@gmail.com\" class=\"fw-bold text-dark text-decoration-underline\">UniversalknowledgR@gmail.com</a> to receive an official receipt.\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- RIGHT: UPI & QR SCAN CARD -->\r\n                <div class=\"col-lg-5\">\r\n                    <div class=\"card border-0 rounded-4 shadow-sm h-100 p-4 p-md-5 text-center d-flex flex-column justify-content-between ukt-upi-card\">\r\n\r\n                        <div>\r\n                            <div class=\"mx-auto mb-3 ukt-upi-icon\">\r\n                                <i class=\"bi bi-qr-code-scan\"></i>\r\n                            </div>\r\n\r\n                            <h3 class=\"h5 mb-2 ukt-banking-card-title\">\r\n                                Instant UPI Contribution\r\n                            </h3>\r\n                            <p class=\"small text-muted mb-4\">\r\n                                Scan &amp; contribute instantly using GPay, PhonePe, Paytm, BHIM, or any UPI app.\r\n                            </p>\r\n\r\n                            <!-- STYLISH QR DISPLAY CONTAINER -->\r\n                            <div class=\"rounded-4 mb-4 mx-auto position-relative ukt-qr-outer-frame\">\r\n                                <div class=\"bg-white p-1 rounded-3 shadow-sm mx-auto mb-2 ukt-qr-inner-box\">\r\n                                    <figure class=\"ukt-qr-figure\">\r\n                                        <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/donations-qr-code.jpg\" alt=\"Universal knowledge Trust Official UPI QR Code\" class=\"img-fluid rounded-2 ukt-qr-img\">\r\n                                        <figcaption class=\"visually-hidden\">Universal knowledge Trust Official UPI QR Code</figcaption>\r\n                                    </figure>\r\n                                </div>\r\n                                <span class=\"badge ukt-qr-badge\">\r\n                                    <i class=\"bi bi-shield-fill-check me-1\"></i> Verified Trust UPI QR\r\n                                </span>\r\n                            </div>\r\n\r\n                            <!-- UPI ID DISPLAY -->\r\n                            <div class=\"p-3 rounded-3 mb-3 text-start ukt-upi-id-box\">\r\n                                <div class=\"small text-muted text-uppercase fw-semibold ukt-banking-item-label\">Official UPI ID</div>\r\n                                <div class=\"d-flex align-items-center justify-content-between mt-1\">\r\n                                    <strong class=\"fs-6 ukt-upi-id-text\" id=\"upiIdText\">adminuniversal@kbl</strong>\r\n                                    <button type=\"button\" class=\"btn btn-sm btn-outline-secondary py-0 px-2\" onclick=\"copyText(\'upiIdText\', this)\" title=\"Copy UPI ID\">\r\n                                        <i class=\"bi bi-clipboard me-1\"></i>Copy\r\n                                    </button>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <!-- SUPPORT APPS -->\r\n                        <div class=\"pt-3 border-top border-light-subtle\">\r\n                            <span class=\"small text-muted d-block mb-2\">Accepted via all secure payment apps:</span>\r\n                            <div class=\"d-flex align-items-center justify-content-center gap-3 text-secondary ukt-upi-apps-list\">\r\n                                <span><i class=\"bi bi-check-circle-fill text-success me-1\"></i> Google Pay</span>\r\n                                <span><i class=\"bi bi-check-circle-fill text-success me-1\"></i> PhonePe</span>\r\n                                <span><i class=\"bi bi-check-circle-fill text-success me-1\"></i> Paytm</span>\r\n                                <span><i class=\"bi bi-check-circle-fill text-success me-1\"></i> BHIM</span>\r\n                            </div>\r\n                        </div>\r\n\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         WHY DONATE TO UKT / TRUST PILLARS\r\n    ========================================================== -->\r\n    <section class=\"py-5 ukt-donations-causes-section\">\r\n        <div class=\"container py-lg-3\">\r\n\r\n            <div class=\"text-center mb-5\">\r\n                <span class=\"ukt-donations-section-kicker\">\r\n                    &mdash;&mdash; &nbsp; OUR SACRED PROMISE &nbsp; &mdash;&mdash;\r\n                </span>\r\n                <h2 class=\"mt-2 mb-3 ukt-donations-section-title\">\r\n                    Purity, Integrity &amp; Transparency\r\n                </h2>\r\n                <p class=\"ukt-donations-section-desc\">\r\n                    Universal Knowledge Trust was established to uplift every soul with sincerity and unconditional love.\r\n                </p>\r\n            </div>\r\n\r\n            <div class=\"row g-4 text-center\">\r\n\r\n                <div class=\"col-md-3 col-sm-6\">\r\n                    <div class=\"p-4 rounded-4 h-100 bg-white shadow-sm border border-light-subtle\">\r\n                        <div class=\"ukt-donation-pillar-icon ukt-pillar-icon-gold\">\r\n                            <i class=\"bi bi-people-fill\"></i>\r\n                        </div>\r\n                        <h4 class=\"h6 fw-bold mb-2 text-dark\">100% Volunteer Seva</h4>\r\n                        <p class=\"small text-muted mb-0\">Direct on-ground deployment with minimal administrative overhead.</p>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"col-md-3 col-sm-6\">\r\n                    <div class=\"p-4 rounded-4 h-100 bg-white shadow-sm border border-light-subtle\">\r\n                        <div class=\"ukt-donation-pillar-icon ukt-pillar-icon-teal\">\r\n                            <i class=\"bi bi-file-earmark-check-fill\"></i>\r\n                        </div>\r\n                        <h4 class=\"h6 fw-bold mb-2 text-dark\">Registered Trust</h4>\r\n                        <p class=\"small text-muted mb-0\">Formally registered as a public charitable trust governed by official statutes.</p>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"col-md-3 col-sm-6\">\r\n                    <div class=\"p-4 rounded-4 h-100 bg-white shadow-sm border border-light-subtle\">\r\n                        <div class=\"ukt-donation-pillar-icon ukt-pillar-icon-green\">\r\n                            <i class=\"bi bi-journal-album\"></i>\r\n                        </div>\r\n                        <h4 class=\"h6 fw-bold mb-2 text-dark\">Documented Impact</h4>\r\n                        <p class=\"small text-muted mb-0\">Regular event videos, photo journals, and verified news coverages of programs.</p>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"col-md-3 col-sm-6\">\r\n                    <div class=\"p-4 rounded-4 h-100 bg-white shadow-sm border border-light-subtle\">\r\n                        <div class=\"ukt-donation-pillar-icon ukt-pillar-icon-gold\">\r\n                            <i class=\"bi bi-receipt-cutoff\"></i>\r\n                        </div>\r\n                        <h4 class=\"h6 fw-bold mb-2 text-dark\">Official Receipts</h4>\r\n                        <p class=\"small text-muted mb-0\">Every donation is acknowledged with an authentic digital receipt and blessing.</p>\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         DONATIONS FAQ SECTION\r\n    ========================================================== -->\r\n    <section class=\"py-5\" id=\"donations-faq\">\r\n        <div class=\"container py-lg-3\">\r\n\r\n            <div class=\"text-center mb-5\">\r\n                <span class=\"ukt-donations-section-kicker\">\r\n                    &mdash;&mdash; &nbsp; CLARIFICATIONS &nbsp; &mdash;&mdash;\r\n                </span>\r\n                <h2 class=\"mt-2 mb-3 ukt-donations-section-title\">\r\n                    Frequently Asked Questions\r\n                </h2>\r\n            </div>\r\n\r\n            <div class=\"row justify-content-center\">\r\n                <div class=\"col-lg-8\">\r\n                    <div class=\"accordion accordion-flush\" id=\"uktDonationFaqAccordion\">\r\n\r\n                        <!-- FAQ 1 -->\r\n                        <div class=\"accordion-item mb-3 rounded-3 overflow-hidden border\">\r\n                            <h2 class=\"accordion-header\" id=\"headingOne\">\r\n                                <button class=\"accordion-button collapsed fw-semibold ukt-donation-faq-btn\" type=\"button\" data-bs-toggle=\"collapse\"\r\n                                    data-bs-target=\"#collapseOne\" aria-expanded=\"false\" aria-controls=\"collapseOne\">\r\n                                    How are my contributions utilized by Universal Knowledge Trust?\r\n                                </button>\r\n                            </h2>\r\n                            <div id=\"collapseOne\" class=\"accordion-collapse collapse\" aria-labelledby=\"headingOne\"\r\n                                data-bs-parent=\"#uktDonationFaqAccordion\">\r\n                                <div class=\"accordion-body text-secondary ukt-donation-faq-body\">\r\n                                    Your contributions go directly into funding our active community initiatives: purchasing groceries and fresh vegetables for free Annadana (community meal distribution), printing and distributing educational booklets for school programs, procuring saplings for environmental greening drives, and hosting free positive energy healing sessions.\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <!-- FAQ 2 -->\r\n                        <div class=\"accordion-item mb-3 rounded-3 overflow-hidden border\">\r\n                            <h2 class=\"accordion-header\" id=\"headingTwo\">\r\n                                <button class=\"accordion-button collapsed fw-semibold ukt-donation-faq-btn\" type=\"button\" data-bs-toggle=\"collapse\"\r\n                                    data-bs-target=\"#collapseTwo\" aria-expanded=\"false\" aria-controls=\"collapseTwo\">\r\n                                    Can I sponsor Annadana on a specific date (e.g., birthday or memorial)?\r\n                                </button>\r\n                            </h2>\r\n                            <div id=\"collapseTwo\" class=\"accordion-collapse collapse\" aria-labelledby=\"headingTwo\"\r\n                                data-bs-parent=\"#uktDonationFaqAccordion\">\r\n                                <div class=\"accordion-body text-secondary ukt-donation-faq-body\">\r\n                                    Yes! Many well-wishers sponsor Annadana meals or tree saplings in memory of their loved ones, or to celebrate birthdays, weddings, and anniversaries. Please notify us at least 3 days in advance via phone or WhatsApp at +91 96321 71156 so we can schedule the drive and share photos of the seva with your family.\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <!-- FAQ 3 -->\r\n                        <div class=\"accordion-item mb-3 rounded-3 overflow-hidden border\">\r\n                            <h2 class=\"accordion-header\" id=\"headingThree\">\r\n                                <button class=\"accordion-button collapsed fw-semibold ukt-donation-faq-btn\" type=\"button\" data-bs-toggle=\"collapse\"\r\n                                    data-bs-target=\"#collapseThree\" aria-expanded=\"false\" aria-controls=\"collapseThree\">\r\n                                    Can I donate in kind (grains, books, tree saplings) instead of money?\r\n                                </button>\r\n                            </h2>\r\n                            <div id=\"collapseThree\" class=\"accordion-collapse collapse\" aria-labelledby=\"headingThree\"\r\n                                data-bs-parent=\"#uktDonationFaqAccordion\">\r\n                                <div class=\"accordion-body text-secondary ukt-donation-faq-body\">\r\n                                    Certainly. We gratefully accept in-kind donations such as bags of rice, lentils, oil, educational stationery, or saplings for our environmental drives. Please contact us to coordinate delivery at our trust centers in Mangalore or program locations across Karnataka.\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <!-- FAQ 4 -->\r\n                        <div class=\"accordion-item mb-3 rounded-3 overflow-hidden border\">\r\n                            <h2 class=\"accordion-header\" id=\"headingFour\">\r\n                                <button class=\"accordion-button collapsed fw-semibold ukt-donation-faq-btn\" type=\"button\" data-bs-toggle=\"collapse\"\r\n                                    data-bs-target=\"#collapseFour\" aria-expanded=\"false\" aria-controls=\"collapseFour\">\r\n                                    How quickly will I receive an official acknowledgment receipt?\r\n                                </button>\r\n                            </h2>\r\n                            <div id=\"collapseFour\" class=\"accordion-collapse collapse\" aria-labelledby=\"headingFour\"\r\n                                data-bs-parent=\"#uktDonationFaqAccordion\">\r\n                                <div class=\"accordion-body text-secondary ukt-donation-faq-body\">\r\n                                    Once you share your transaction reference or screenshot via WhatsApp (+91 96321 71156) or Email (UniversalknowledgR@gmail.com) along with your full legal name and address, our accounts team will verify the credit and send your formal digital receipt within 24 to 48 hours.\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         GRATITUDE CALL TO ACTION BANNER\r\n    ========================================================== -->\r\n    <section class=\"py-5 text-center text-white position-relative ukt-donations-cta-section\">\r\n        <div class=\"container py-lg-4\">\r\n            <span class=\"ukt-donations-cta-kicker\">\r\n                DIVINE ABUNDANCE &amp; GRATITUDE\r\n            </span>\r\n            <h2 class=\"my-3 ukt-donations-cta-title\">\r\n                “Positive Energy is the Currency of the Universe”\r\n            </h2>\r\n            <p class=\"ukt-donations-cta-desc\">\r\n                When you share from the heart, the blessings return multiplied in health, peace, and spiritual harmony. Thank you for walking this sacred path with us.\r\n            </p>\r\n            <div class=\"d-flex flex-wrap justify-content-center gap-3\">\r\n                <a href=\"tel:+919632171156\" class=\"ukt-hero-primary-action ukt-donations-cta-btn-primary\">\r\n                    <i class=\"bi bi-telephone-fill me-1\"></i> Speak With A Trustee: +91 96321 71156\r\n                </a>\r\n                <a href=\"mailto:UniversalknowledgR@gmail.com\" class=\"ukt-hero-secondary-action ukt-donations-cta-btn-secondary\">\r\n                    <i class=\"bi bi-envelope-fill me-1\"></i> Email: UniversalknowledgR@gmail.com\r\n                </a>\r\n            </div>\r\n        </div>\r\n    </section>\r\n\r\n</article>\r\n\r\n<script>\r\n    // Copy to clipboard helper function with visual feedback\r\n    function copyText(elementId, btn) {\r\n        const text = document.getElementById(elementId).innerText.trim();\r\n        navigator.clipboard.writeText(text).then(function () {\r\n            const originalHTML = btn.innerHTML;\r\n            btn.innerHTML = \'<i class=\"bi bi-check2 text-success me-1\"></i>Copied!\';\r\n            btn.classList.remove(\'btn-outline-secondary\');\r\n            btn.classList.add(\'btn-success\', \'text-white\');\r\n            setTimeout(function () {\r\n                btn.innerHTML = originalHTML;\r\n                btn.classList.remove(\'btn-success\', \'text-white\');\r\n                btn.classList.add(\'btn-outline-secondary\');\r\n            }, 2000);\r\n        }).catch(function (err) {\r\n            console.error(\'Could not copy text: \', err);\r\n        });\r\n    }\r\n</script>', 'Donations', '', 'publish', 'closed', 'closed', '', 'donations', '', '', '2026-10-26 17:38:43', '2026-10-26 12:08:43', '', 0, 'http://localhost/universal-knowledge-trust-wordpress/?page_id=248', 0, 'page', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(249, 1, '2026-10-26 17:38:43', '2026-10-26 12:08:43', '<article>\r\n\r\n    <!-- =========================================================\r\n         DONATIONS & SEVA BANNER / HERO SECTION\r\n         (Matches index showcase hero layout)\r\n    ========================================================== -->\r\n    <section class=\"ukt-hero-showcase\">\r\n        <div class=\"ukt-hero-slide-layout\">\r\n            <div class=\"container-fluid\">\r\n                <div class=\"row g-0 align-items-stretch\">\r\n\r\n                    <!-- LEFT CONTENT AREA -->\r\n                    <div class=\"col-lg-5 d-flex align-items-center\">\r\n                        <div class=\"ukt-hero-copy-zone\">\r\n                            <div class=\"ukt-hero-left-decoration\"></div>\r\n\r\n                            <div class=\"ukt-hero-slide-kicker\">\r\n                                <i class=\"bi bi-heart-fill me-1 ukt-hero-kicker-icon\"></i> Universal Knowledge Trust • Seva &amp; Giving\r\n                            </div>\r\n\r\n                            <h1 class=\"ukt-hero-main-title\">\r\n                                <span>Empower Lives.</span>\r\n                                <span>Share the Light.</span>\r\n                            </h1>\r\n\r\n                            <div class=\"ukt-hero-script-line\">\r\n                                Compassion · Annadana · Upliftment\r\n                            </div>\r\n\r\n                            <p class=\"ukt-hero-description\">\r\n                                Dedicated to selfless service and holistic well-being. Your compassionate contributions support daily nutritious food distribution (Annadana), values-based school training programs, environmental tree plantations, and free positive energy healing for underprivileged communities.\r\n                            </p>\r\n\r\n                            <div class=\"ukt-hero-action-row\">\r\n                                <a href=\"#bank-details\" class=\"ukt-hero-primary-action\">\r\n                                    Contribute Online <i class=\"bi bi-arrow-down-circle-fill ms-1\"></i>\r\n                                </a>\r\n\r\n                                <a href=\"#seva-causes\" class=\"ukt-hero-secondary-action\">\r\n                                    Our Seva Causes\r\n                                </a>\r\n                            </div>\r\n\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- RIGHT IMAGE AREA -->\r\n                    <div class=\"col-lg-7\">\r\n                        <div class=\"ukt-hero-visual-zone\">\r\n                            <div class=\"ukt-hero-image-frame\">\r\n                                <figure class=\"ukt-hero-image-figure\">\r\n                                    <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/donations-banner.jpg\"\r\n                                        alt=\"Universal Knowledge Trust - Selfless Giving, Annadana and Humanitarian Seva\"\r\n                                        loading=\"eager\">\r\n                                    <figcaption class=\"visually-hidden\">Universal Knowledge Trust - Selfless Giving, Annadana and Humanitarian Seva</figcaption>\r\n                                </figure>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         CORE SEVA INITIATIVES / CAUSES\r\n    ========================================================== -->\r\n    <section class=\"py-5 ukt-donations-causes-section\" id=\"seva-causes\">\r\n        <div class=\"container py-lg-4\">\r\n\r\n            <!-- HEADER -->\r\n            <div class=\"text-center mb-5\">\r\n                <span class=\"ukt-donations-section-kicker\">\r\n                    &mdash;&mdash; &nbsp; WAYS YOUR GENEROSITY HELPS &nbsp; &mdash;&mdash;\r\n                </span>\r\n                <h2 class=\"mt-2 mb-3 ukt-donations-section-title\">\r\n                    Our Core Seva Initiatives\r\n                </h2>\r\n                <p class=\"ukt-donations-section-desc\">\r\n                    Every rupee contributed is dedicated with absolute purity, transparency, and reverence toward the holistic upliftment of human lives and nature.\r\n                </p>\r\n            </div>\r\n\r\n            <!-- 4 CAUSES GRID -->\r\n            <div class=\"row g-4\">\r\n\r\n                <!-- CAUSE 1: ANNADANA -->\r\n                <div class=\"col-lg-6 col-md-6\">\r\n                    <div class=\"card h-100 border-0 rounded-4 shadow-sm p-4 p-lg-5 ukt-donation-cause-card\">\r\n                        <div class=\"d-flex align-items-center justify-content-between mb-4\">\r\n                            <div class=\"ukt-donation-cause-icon ukt-cause-icon-food\">\r\n                                <i class=\"bi bi-cup-hot-fill\"></i>\r\n                            </div>\r\n                            <span class=\"badge rounded-pill fw-semibold ukt-cause-badge\">\r\n                                Daily Food Relief\r\n                            </span>\r\n                        </div>\r\n                        <h3 class=\"h4 mb-3 ukt-cause-card-title\">\r\n                            Annadana Seva &mdash; Nutritious Meals\r\n                        </h3>\r\n                        <p class=\"ukt-cause-card-desc\">\r\n                            Serving wholesome, hot vegetarian meals and fresh grains to impoverished families, disadvantaged children, and elderly citizens. Your support ensures no one in our reach sleeps hungry.\r\n                        </p>\r\n                        <div class=\"mt-auto pt-3 border-top border-light-subtle d-flex align-items-center justify-content-between\">\r\n                            <span class=\"small text-muted\"><i class=\"bi bi-check2-circle text-success me-1\"></i> Cooked with love &amp; hygiene</span>\r\n                            <a href=\"#bank-details\" class=\"text-decoration-none fw-semibold small ukt-cause-card-link-food\">\r\n                                Sponsor Meals <i class=\"bi bi-arrow-right\"></i>\r\n                            </a>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- CAUSE 2: SCHOOL & YOUTH -->\r\n                <div class=\"col-lg-6 col-md-6\">\r\n                    <div class=\"card h-100 border-0 rounded-4 shadow-sm p-4 p-lg-5 ukt-donation-cause-card\">\r\n                        <div class=\"d-flex align-items-center justify-content-between mb-4\">\r\n                            <div class=\"ukt-donation-cause-icon ukt-cause-icon-school\">\r\n                                <i class=\"bi bi-mortarboard-fill\"></i>\r\n                            </div>\r\n                            <span class=\"badge rounded-pill fw-semibold ukt-cause-badge\">\r\n                                200,000+ Students Reached\r\n                            </span>\r\n                        </div>\r\n                        <h3 class=\"h4 mb-3 ukt-cause-card-title\">\r\n                            Youth &amp; School Value Education\r\n                        </h3>\r\n                        <p class=\"ukt-cause-card-desc\">\r\n                            Providing free workshops, Super Brain Yoga, concentration tools, positive habit modules, and educational materials to government and rural school children across Karnataka.\r\n                        </p>\r\n                        <div class=\"mt-auto pt-3 border-top border-light-subtle d-flex align-items-center justify-content-between\">\r\n                            <span class=\"small text-muted\"><i class=\"bi bi-check2-circle text-success me-1\"></i> Inspiring young leaders</span>\r\n                            <a href=\"#bank-details\" class=\"text-decoration-none fw-semibold small ukt-cause-card-link-school\">\r\n                                Sponsor Students <i class=\"bi bi-arrow-right\"></i>\r\n                            </a>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- CAUSE 3: VRIKSHA SEVA -->\r\n                <div class=\"col-lg-6 col-md-6\">\r\n                    <div class=\"card h-100 border-0 rounded-4 shadow-sm p-4 p-lg-5 ukt-donation-cause-card\">\r\n                        <div class=\"d-flex align-items-center justify-content-between mb-4\">\r\n                            <div class=\"ukt-donation-cause-icon ukt-cause-icon-green\">\r\n                                <i class=\"bi bi-tree-fill\"></i>\r\n                            </div>\r\n                            <span class=\"badge rounded-pill fw-semibold ukt-cause-badge-green\">\r\n                                Mother Earth Harmony\r\n                            </span>\r\n                        </div>\r\n                        <h3 class=\"h4 mb-3 ukt-cause-card-title\">\r\n                            Tree Plantations &amp; Environmental Seva\r\n                        </h3>\r\n                        <p class=\"ukt-cause-card-desc\">\r\n                            Afforestation drives, planting indigenous and medicinal saplings, conducting Vedic Agnihotra atmospheric purification, and spreading ecological conservation awareness.\r\n                        </p>\r\n                        <div class=\"mt-auto pt-3 border-top border-light-subtle d-flex align-items-center justify-content-between\">\r\n                            <span class=\"small text-muted\"><i class=\"bi bi-check2-circle text-success me-1\"></i> Green eco-initiatives</span>\r\n                            <a href=\"#bank-details\" class=\"text-decoration-none fw-semibold small ukt-cause-card-link-green\">\r\n                                Sponsor a Tree <i class=\"bi bi-arrow-right\"></i>\r\n                            </a>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- CAUSE 4: NATURAL HEALING -->\r\n                <div class=\"col-lg-6 col-md-6\">\r\n                    <div class=\"card h-100 border-0 rounded-4 shadow-sm p-4 p-lg-5 ukt-donation-cause-card\">\r\n                        <div class=\"d-flex align-items-center justify-content-between mb-4\">\r\n                            <div class=\"ukt-donation-cause-icon ukt-cause-icon-healing\">\r\n                                <i class=\"bi bi-flower1\"></i>\r\n                            </div>\r\n                            <span class=\"badge rounded-pill fw-semibold ukt-cause-badge\">\r\n                                Healing &amp; Wellness\r\n                            </span>\r\n                        </div>\r\n                        <h3 class=\"h4 mb-3 ukt-cause-card-title\">\r\n                            Free Positive Energy Healing Camps\r\n                        </h3>\r\n                        <p class=\"ukt-cause-card-desc\">\r\n                            Conducting free Natural Positive Energy Healing (NPEH), chakra balancing, meditation, and stress alleviation sessions for individuals, families, and senior citizens needing care.\r\n                        </p>\r\n                        <div class=\"mt-auto pt-3 border-top border-light-subtle d-flex align-items-center justify-content-between\">\r\n                            <span class=\"small text-muted\"><i class=\"bi bi-check2-circle text-success me-1\"></i> Certified healers &amp; mentors</span>\r\n                            <a href=\"#bank-details\" class=\"text-decoration-none fw-semibold small ukt-cause-card-link-school\">\r\n                                Support Healing <i class=\"bi bi-arrow-right\"></i>\r\n                            </a>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         OFFICIAL TRUST BANK & PAYMENT DETAILS SECTION\r\n    ========================================================== -->\r\n    <section class=\"py-5 ukt-donations-banking-section\" id=\"bank-details\">\r\n        <div class=\"container py-lg-4\">\r\n\r\n            <!-- HEADER -->\r\n            <div class=\"text-center mb-5\">\r\n                <span class=\"ukt-donations-gold-kicker\">\r\n                    &mdash;&mdash; &nbsp; SECURE &amp; DIRECT DONATION &nbsp; &mdash;&mdash;\r\n                </span>\r\n                <h2 class=\"mt-2 mb-3 ukt-banking-section-title\">\r\n                    Official Trust <span>Banking Details</span>\r\n                </h2>\r\n                <p class=\"ukt-banking-section-desc\">\r\n                    Contributions can be transferred directly via NEFT, RTGS, IMPS, or UPI to the official registered account of Universal Knowledge Trust.\r\n                </p>\r\n            </div>\r\n\r\n            <!-- MAIN BANKING & UPI CARDS CONTAINER -->\r\n            <div class=\"row g-4 justify-content-center\">\r\n\r\n                <!-- LEFT: OFFICIAL BANK ACCOUNT CARD -->\r\n                <div class=\"col-lg-7\">\r\n                    <div class=\"card border-0 rounded-4 shadow-sm h-100 p-4 p-md-5 ukt-banking-details-card\">\r\n\r\n                        <div class=\"d-flex align-items-center gap-3 mb-4 pb-3 border-bottom ukt-banking-card-header\">\r\n                            <div class=\"ukt-banking-header-icon\">\r\n                                <i class=\"bi bi-bank2\"></i>\r\n                            </div>\r\n                            <div>\r\n                                <h3 class=\"h5 mb-1 ukt-banking-card-title\">\r\n                                    Direct Bank Transfer (NEFT / RTGS / IMPS)\r\n                                </h3>\r\n                                <span class=\"badge text-bg-light border small\">Public Charitable Trust Account</span>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <!-- BANK DETAILS LIST -->\r\n                        <div class=\"d-flex flex-column gap-3 mb-4\">\r\n\r\n                            <!-- Field 1: Account Name -->\r\n                            <div class=\"p-3 rounded-3 ukt-banking-item-box\">\r\n                                <div class=\"small text-muted text-uppercase fw-semibold ukt-banking-item-label\">Account Name</div>\r\n                                <div class=\"d-flex align-items-center justify-content-between mt-1\">\r\n                                    <strong class=\"fs-6 text-dark\" id=\"accNameText\">Universal knowledge Trust</strong>\r\n                                    <button type=\"button\" class=\"btn btn-sm btn-outline-secondary py-0 px-2\" onclick=\"copyText(\'accNameText\', this)\" title=\"Copy Account Name\">\r\n                                        <i class=\"bi bi-clipboard me-1\"></i>Copy\r\n                                    </button>\r\n                                </div>\r\n                            </div>\r\n\r\n                            <!-- Field 2: Account Number -->\r\n                            <div class=\"p-3 rounded-3 ukt-banking-item-box\">\r\n                                <div class=\"small text-muted text-uppercase fw-semibold ukt-banking-item-label\">Account Number</div>\r\n                                <div class=\"d-flex align-items-center justify-content-between mt-1\">\r\n                                    <strong class=\"fs-5 fw-bold ukt-banking-acc-number\" id=\"accNumText\">4792000100073301</strong>\r\n                                    <button type=\"button\" class=\"btn btn-sm btn-outline-secondary py-0 px-2\" onclick=\"copyText(\'accNumText\', this)\" title=\"Copy Account Number\">\r\n                                        <i class=\"bi bi-clipboard me-1\"></i>Copy\r\n                                    </button>\r\n                                </div>\r\n                            </div>\r\n\r\n                            <!-- Field 3: Bank Name & Account Type -->\r\n                            <div class=\"row g-2\">\r\n                                <div class=\"col-sm-6\">\r\n                                    <div class=\"p-3 rounded-3 h-100 ukt-banking-item-box\">\r\n                                        <div class=\"small text-muted text-uppercase fw-semibold ukt-banking-item-label\">Bank Name</div>\r\n                                        <strong class=\"text-dark d-block mt-1\">Karnataka Bank</strong>\r\n                                    </div>\r\n                                </div>\r\n                                <div class=\"col-sm-6\">\r\n                                    <div class=\"p-3 rounded-3 h-100 ukt-banking-item-box\">\r\n                                        <div class=\"small text-muted text-uppercase fw-semibold ukt-banking-item-label\">Account Type</div>\r\n                                        <strong class=\"text-dark d-block mt-1\">Current account</strong>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n\r\n                            <!-- Field 4: IFSC Code -->\r\n                            <div class=\"p-3 rounded-3 ukt-banking-item-box\">\r\n                                <div class=\"small text-muted text-uppercase fw-semibold ukt-banking-item-label\">IFSC Code</div>\r\n                                <div class=\"d-flex align-items-center justify-content-between mt-1\">\r\n                                    <strong class=\"fs-6 fw-bold ukt-banking-ifsc\" id=\"ifscText\">KARB0000479</strong>\r\n                                    <button type=\"button\" class=\"btn btn-sm btn-outline-secondary py-0 px-2\" onclick=\"copyText(\'ifscText\', this)\" title=\"Copy IFSC Code\">\r\n                                        <i class=\"bi bi-clipboard me-1\"></i>Copy\r\n                                    </button>\r\n                                </div>\r\n                            </div>\r\n\r\n                            <!-- Field 5: Branch -->\r\n                            <div class=\"p-3 rounded-3 ukt-banking-item-box\">\r\n                                <div class=\"small text-muted text-uppercase fw-semibold ukt-banking-item-label\">Branch Location</div>\r\n                                <strong class=\"text-dark d-block mt-1\">Mannagudda Branch</strong>\r\n                            </div>\r\n\r\n                        </div>\r\n\r\n                        <!-- RECEIPT NOTE -->\r\n                        <div class=\"alert alert-light border rounded-3 p-3 mb-0 ukt-banking-receipt-alert\">\r\n                            <div class=\"d-flex gap-2\">\r\n                                <i class=\"bi bi-shield-check text-success fs-5\"></i>\r\n                                <div class=\"small text-dark\">\r\n                                    <strong>Official Trust Receipts:</strong> Please share your transfer screenshot along with your full name and address via WhatsApp at <a href=\"https://wa.me/919632171156\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"fw-bold text-success text-decoration-none\">+91 96321 71156</a> or email <a href=\"mailto:UniversalknowledgR@gmail.com\" class=\"fw-bold text-dark text-decoration-underline\">UniversalknowledgR@gmail.com</a> to receive an official receipt.\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- RIGHT: UPI & QR SCAN CARD -->\r\n                <div class=\"col-lg-5\">\r\n                    <div class=\"card border-0 rounded-4 shadow-sm h-100 p-4 p-md-5 text-center d-flex flex-column justify-content-between ukt-upi-card\">\r\n\r\n                        <div>\r\n                            <div class=\"mx-auto mb-3 ukt-upi-icon\">\r\n                                <i class=\"bi bi-qr-code-scan\"></i>\r\n                            </div>\r\n\r\n                            <h3 class=\"h5 mb-2 ukt-banking-card-title\">\r\n                                Instant UPI Contribution\r\n                            </h3>\r\n                            <p class=\"small text-muted mb-4\">\r\n                                Scan &amp; contribute instantly using GPay, PhonePe, Paytm, BHIM, or any UPI app.\r\n                            </p>\r\n\r\n                            <!-- STYLISH QR DISPLAY CONTAINER -->\r\n                            <div class=\"rounded-4 mb-4 mx-auto position-relative ukt-qr-outer-frame\">\r\n                                <div class=\"bg-white p-1 rounded-3 shadow-sm mx-auto mb-2 ukt-qr-inner-box\">\r\n                                    <figure class=\"ukt-qr-figure\">\r\n                                        <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/donations-qr-code.jpg\" alt=\"Universal knowledge Trust Official UPI QR Code\" class=\"img-fluid rounded-2 ukt-qr-img\">\r\n                                        <figcaption class=\"visually-hidden\">Universal knowledge Trust Official UPI QR Code</figcaption>\r\n                                    </figure>\r\n                                </div>\r\n                                <span class=\"badge ukt-qr-badge\">\r\n                                    <i class=\"bi bi-shield-fill-check me-1\"></i> Verified Trust UPI QR\r\n                                </span>\r\n                            </div>\r\n\r\n                            <!-- UPI ID DISPLAY -->\r\n                            <div class=\"p-3 rounded-3 mb-3 text-start ukt-upi-id-box\">\r\n                                <div class=\"small text-muted text-uppercase fw-semibold ukt-banking-item-label\">Official UPI ID</div>\r\n                                <div class=\"d-flex align-items-center justify-content-between mt-1\">\r\n                                    <strong class=\"fs-6 ukt-upi-id-text\" id=\"upiIdText\">adminuniversal@kbl</strong>\r\n                                    <button type=\"button\" class=\"btn btn-sm btn-outline-secondary py-0 px-2\" onclick=\"copyText(\'upiIdText\', this)\" title=\"Copy UPI ID\">\r\n                                        <i class=\"bi bi-clipboard me-1\"></i>Copy\r\n                                    </button>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <!-- SUPPORT APPS -->\r\n                        <div class=\"pt-3 border-top border-light-subtle\">\r\n                            <span class=\"small text-muted d-block mb-2\">Accepted via all secure payment apps:</span>\r\n                            <div class=\"d-flex align-items-center justify-content-center gap-3 text-secondary ukt-upi-apps-list\">\r\n                                <span><i class=\"bi bi-check-circle-fill text-success me-1\"></i> Google Pay</span>\r\n                                <span><i class=\"bi bi-check-circle-fill text-success me-1\"></i> PhonePe</span>\r\n                                <span><i class=\"bi bi-check-circle-fill text-success me-1\"></i> Paytm</span>\r\n                                <span><i class=\"bi bi-check-circle-fill text-success me-1\"></i> BHIM</span>\r\n                            </div>\r\n                        </div>\r\n\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         WHY DONATE TO UKT / TRUST PILLARS\r\n    ========================================================== -->\r\n    <section class=\"py-5 ukt-donations-causes-section\">\r\n        <div class=\"container py-lg-3\">\r\n\r\n            <div class=\"text-center mb-5\">\r\n                <span class=\"ukt-donations-section-kicker\">\r\n                    &mdash;&mdash; &nbsp; OUR SACRED PROMISE &nbsp; &mdash;&mdash;\r\n                </span>\r\n                <h2 class=\"mt-2 mb-3 ukt-donations-section-title\">\r\n                    Purity, Integrity &amp; Transparency\r\n                </h2>\r\n                <p class=\"ukt-donations-section-desc\">\r\n                    Universal Knowledge Trust was established to uplift every soul with sincerity and unconditional love.\r\n                </p>\r\n            </div>\r\n\r\n            <div class=\"row g-4 text-center\">\r\n\r\n                <div class=\"col-md-3 col-sm-6\">\r\n                    <div class=\"p-4 rounded-4 h-100 bg-white shadow-sm border border-light-subtle\">\r\n                        <div class=\"ukt-donation-pillar-icon ukt-pillar-icon-gold\">\r\n                            <i class=\"bi bi-people-fill\"></i>\r\n                        </div>\r\n                        <h4 class=\"h6 fw-bold mb-2 text-dark\">100% Volunteer Seva</h4>\r\n                        <p class=\"small text-muted mb-0\">Direct on-ground deployment with minimal administrative overhead.</p>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"col-md-3 col-sm-6\">\r\n                    <div class=\"p-4 rounded-4 h-100 bg-white shadow-sm border border-light-subtle\">\r\n                        <div class=\"ukt-donation-pillar-icon ukt-pillar-icon-teal\">\r\n                            <i class=\"bi bi-file-earmark-check-fill\"></i>\r\n                        </div>\r\n                        <h4 class=\"h6 fw-bold mb-2 text-dark\">Registered Trust</h4>\r\n                        <p class=\"small text-muted mb-0\">Formally registered as a public charitable trust governed by official statutes.</p>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"col-md-3 col-sm-6\">\r\n                    <div class=\"p-4 rounded-4 h-100 bg-white shadow-sm border border-light-subtle\">\r\n                        <div class=\"ukt-donation-pillar-icon ukt-pillar-icon-green\">\r\n                            <i class=\"bi bi-journal-album\"></i>\r\n                        </div>\r\n                        <h4 class=\"h6 fw-bold mb-2 text-dark\">Documented Impact</h4>\r\n                        <p class=\"small text-muted mb-0\">Regular event videos, photo journals, and verified news coverages of programs.</p>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"col-md-3 col-sm-6\">\r\n                    <div class=\"p-4 rounded-4 h-100 bg-white shadow-sm border border-light-subtle\">\r\n                        <div class=\"ukt-donation-pillar-icon ukt-pillar-icon-gold\">\r\n                            <i class=\"bi bi-receipt-cutoff\"></i>\r\n                        </div>\r\n                        <h4 class=\"h6 fw-bold mb-2 text-dark\">Official Receipts</h4>\r\n                        <p class=\"small text-muted mb-0\">Every donation is acknowledged with an authentic digital receipt and blessing.</p>\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         DONATIONS FAQ SECTION\r\n    ========================================================== -->\r\n    <section class=\"py-5\" id=\"donations-faq\">\r\n        <div class=\"container py-lg-3\">\r\n\r\n            <div class=\"text-center mb-5\">\r\n                <span class=\"ukt-donations-section-kicker\">\r\n                    &mdash;&mdash; &nbsp; CLARIFICATIONS &nbsp; &mdash;&mdash;\r\n                </span>\r\n                <h2 class=\"mt-2 mb-3 ukt-donations-section-title\">\r\n                    Frequently Asked Questions\r\n                </h2>\r\n            </div>\r\n\r\n            <div class=\"row justify-content-center\">\r\n                <div class=\"col-lg-8\">\r\n                    <div class=\"accordion accordion-flush\" id=\"uktDonationFaqAccordion\">\r\n\r\n                        <!-- FAQ 1 -->\r\n                        <div class=\"accordion-item mb-3 rounded-3 overflow-hidden border\">\r\n                            <h2 class=\"accordion-header\" id=\"headingOne\">\r\n                                <button class=\"accordion-button collapsed fw-semibold ukt-donation-faq-btn\" type=\"button\" data-bs-toggle=\"collapse\"\r\n                                    data-bs-target=\"#collapseOne\" aria-expanded=\"false\" aria-controls=\"collapseOne\">\r\n                                    How are my contributions utilized by Universal Knowledge Trust?\r\n                                </button>\r\n                            </h2>\r\n                            <div id=\"collapseOne\" class=\"accordion-collapse collapse\" aria-labelledby=\"headingOne\"\r\n                                data-bs-parent=\"#uktDonationFaqAccordion\">\r\n                                <div class=\"accordion-body text-secondary ukt-donation-faq-body\">\r\n                                    Your contributions go directly into funding our active community initiatives: purchasing groceries and fresh vegetables for free Annadana (community meal distribution), printing and distributing educational booklets for school programs, procuring saplings for environmental greening drives, and hosting free positive energy healing sessions.\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <!-- FAQ 2 -->\r\n                        <div class=\"accordion-item mb-3 rounded-3 overflow-hidden border\">\r\n                            <h2 class=\"accordion-header\" id=\"headingTwo\">\r\n                                <button class=\"accordion-button collapsed fw-semibold ukt-donation-faq-btn\" type=\"button\" data-bs-toggle=\"collapse\"\r\n                                    data-bs-target=\"#collapseTwo\" aria-expanded=\"false\" aria-controls=\"collapseTwo\">\r\n                                    Can I sponsor Annadana on a specific date (e.g., birthday or memorial)?\r\n                                </button>\r\n                            </h2>\r\n                            <div id=\"collapseTwo\" class=\"accordion-collapse collapse\" aria-labelledby=\"headingTwo\"\r\n                                data-bs-parent=\"#uktDonationFaqAccordion\">\r\n                                <div class=\"accordion-body text-secondary ukt-donation-faq-body\">\r\n                                    Yes! Many well-wishers sponsor Annadana meals or tree saplings in memory of their loved ones, or to celebrate birthdays, weddings, and anniversaries. Please notify us at least 3 days in advance via phone or WhatsApp at +91 96321 71156 so we can schedule the drive and share photos of the seva with your family.\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <!-- FAQ 3 -->\r\n                        <div class=\"accordion-item mb-3 rounded-3 overflow-hidden border\">\r\n                            <h2 class=\"accordion-header\" id=\"headingThree\">\r\n                                <button class=\"accordion-button collapsed fw-semibold ukt-donation-faq-btn\" type=\"button\" data-bs-toggle=\"collapse\"\r\n                                    data-bs-target=\"#collapseThree\" aria-expanded=\"false\" aria-controls=\"collapseThree\">\r\n                                    Can I donate in kind (grains, books, tree saplings) instead of money?\r\n                                </button>\r\n                            </h2>\r\n                            <div id=\"collapseThree\" class=\"accordion-collapse collapse\" aria-labelledby=\"headingThree\"\r\n                                data-bs-parent=\"#uktDonationFaqAccordion\">\r\n                                <div class=\"accordion-body text-secondary ukt-donation-faq-body\">\r\n                                    Certainly. We gratefully accept in-kind donations such as bags of rice, lentils, oil, educational stationery, or saplings for our environmental drives. Please contact us to coordinate delivery at our trust centers in Mangalore or program locations across Karnataka.\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <!-- FAQ 4 -->\r\n                        <div class=\"accordion-item mb-3 rounded-3 overflow-hidden border\">\r\n                            <h2 class=\"accordion-header\" id=\"headingFour\">\r\n                                <button class=\"accordion-button collapsed fw-semibold ukt-donation-faq-btn\" type=\"button\" data-bs-toggle=\"collapse\"\r\n                                    data-bs-target=\"#collapseFour\" aria-expanded=\"false\" aria-controls=\"collapseFour\">\r\n                                    How quickly will I receive an official acknowledgment receipt?\r\n                                </button>\r\n                            </h2>\r\n                            <div id=\"collapseFour\" class=\"accordion-collapse collapse\" aria-labelledby=\"headingFour\"\r\n                                data-bs-parent=\"#uktDonationFaqAccordion\">\r\n                                <div class=\"accordion-body text-secondary ukt-donation-faq-body\">\r\n                                    Once you share your transaction reference or screenshot via WhatsApp (+91 96321 71156) or Email (UniversalknowledgR@gmail.com) along with your full legal name and address, our accounts team will verify the credit and send your formal digital receipt within 24 to 48 hours.\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         GRATITUDE CALL TO ACTION BANNER\r\n    ========================================================== -->\r\n    <section class=\"py-5 text-center text-white position-relative ukt-donations-cta-section\">\r\n        <div class=\"container py-lg-4\">\r\n            <span class=\"ukt-donations-cta-kicker\">\r\n                DIVINE ABUNDANCE &amp; GRATITUDE\r\n            </span>\r\n            <h2 class=\"my-3 ukt-donations-cta-title\">\r\n                “Positive Energy is the Currency of the Universe”\r\n            </h2>\r\n            <p class=\"ukt-donations-cta-desc\">\r\n                When you share from the heart, the blessings return multiplied in health, peace, and spiritual harmony. Thank you for walking this sacred path with us.\r\n            </p>\r\n            <div class=\"d-flex flex-wrap justify-content-center gap-3\">\r\n                <a href=\"tel:+919632171156\" class=\"ukt-hero-primary-action ukt-donations-cta-btn-primary\">\r\n                    <i class=\"bi bi-telephone-fill me-1\"></i> Speak With A Trustee: +91 96321 71156\r\n                </a>\r\n                <a href=\"mailto:UniversalknowledgR@gmail.com\" class=\"ukt-hero-secondary-action ukt-donations-cta-btn-secondary\">\r\n                    <i class=\"bi bi-envelope-fill me-1\"></i> Email: UniversalknowledgR@gmail.com\r\n                </a>\r\n            </div>\r\n        </div>\r\n    </section>\r\n\r\n</article>\r\n\r\n<script>\r\n    // Copy to clipboard helper function with visual feedback\r\n    function copyText(elementId, btn) {\r\n        const text = document.getElementById(elementId).innerText.trim();\r\n        navigator.clipboard.writeText(text).then(function () {\r\n            const originalHTML = btn.innerHTML;\r\n            btn.innerHTML = \'<i class=\"bi bi-check2 text-success me-1\"></i>Copied!\';\r\n            btn.classList.remove(\'btn-outline-secondary\');\r\n            btn.classList.add(\'btn-success\', \'text-white\');\r\n            setTimeout(function () {\r\n                btn.innerHTML = originalHTML;\r\n                btn.classList.remove(\'btn-success\', \'text-white\');\r\n                btn.classList.add(\'btn-outline-secondary\');\r\n            }, 2000);\r\n        }).catch(function (err) {\r\n            console.error(\'Could not copy text: \', err);\r\n        });\r\n    }\r\n</script>', 'Donations', '', 'inherit', 'closed', 'closed', '', '248-revision-v1', '', '', '2026-10-26 17:38:43', '2026-10-26 12:08:43', '', 248, 'http://localhost/universal-knowledge-trust-wordpress/?p=249', 0, 'revision', '', 0),
