INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(255, 1, '2026-10-26 17:47:14', '2026-10-26 12:17:14', '<article>\r\n    <!-- =========================================================\r\n         PARIVARTHAN APP BANNER / HERO SECTION\r\n         (Matches index showcase hero layout & spacing)\r\n    ========================================================== -->\r\n    <section class=\"ukt-hero-showcase\">\r\n        <div class=\"ukt-hero-carousel-shell\">\r\n            <div class=\"carousel-inner\">\r\n                <div class=\"carousel-item active ukt-hero-carousel-item\">\r\n                    <div class=\"ukt-hero-slide-layout\">\r\n                        <div class=\"container-fluid\">\r\n                            <div class=\"row g-0 align-items-stretch\">\r\n\r\n                                <!-- LEFT CONTENT AREA (REDUCED TEXT) -->\r\n                                <div class=\"col-lg-5 d-flex align-items-center\">\r\n                                    <div class=\"ukt-hero-copy-zone\">\r\n                                        <div class=\"ukt-hero-left-decoration\"></div>\r\n\r\n                                        <div class=\"ukt-hero-slide-kicker\">\r\n                                            Universal Knowledge Trust\r\n                                        </div>\r\n\r\n                                        <h1 class=\"ukt-hero-main-title\">\r\n                                            <span>Parivarthan App</span>\r\n                                        </h1>\r\n\r\n                                        <div class=\"ukt-hero-script-line\">\r\n                                            Positive Change From Within\r\n                                        </div>\r\n\r\n                                        <p class=\"ukt-hero-description\">\r\n                                            Experience Natural Positive Energy Healing (NPEH) and distance mode healing from dedicated healers—completely free.\r\n                                        </p>\r\n\r\n                                        <div class=\"ukt-hero-action-row\">\r\n                                            <a href=\"#about-app\" class=\"ukt-hero-primary-action\">\r\n                                                Explore App\r\n                                                <i class=\"bi bi-arrow-down\"></i>\r\n                                            </a>\r\n                                            <a href=\"#download\" class=\"ukt-hero-secondary-action\">\r\n                                                <i class=\"bi bi-download me-1\"></i> Get the App\r\n                                            </a>\r\n                                        </div>\r\n\r\n                                    </div>\r\n                                </div>\r\n\r\n                                <!-- RIGHT IMAGE AREA -->\r\n                                <div class=\"col-lg-7\">\r\n                                    <div class=\"ukt-hero-visual-zone\">\r\n                                        <div class=\"ukt-hero-image-frame\">\r\n                                            <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/parivarthan-apps-banner.jpg\"\r\n                                                alt=\"Parivarthan App - Universal Knowledge Trust\"\r\n                                                loading=\"eager\">\r\n                                        </div>\r\n                                    </div>\r\n                                </div>\r\n\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         SECTION: INTRODUCTION TO PARIVARTHAN APP\r\n    ========================================================== -->\r\n    <section id=\"about-app\" class=\"py-5 ukt-section-bg-white ukt-pv-section\">\r\n        <div class=\"container py-lg-4\">\r\n            <div class=\"row align-items-center g-4 g-lg-5\">\r\n\r\n                <!-- LEFT COLUMN: APP SHOWCASE IMAGE & BADGE -->\r\n                <div class=\"col-lg-5 text-center mb-4 mb-lg-0 d-flex align-items-center justify-content-center\">\r\n                    <div class=\"ukt-pv-intro-frame\">\r\n                        <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/parivarthan-app-intro.jpg\" \r\n                             id=\"parivarthan-app-img\"\r\n                             alt=\"Parivarthan App - Remote Positive Energy Healing\" \r\n                             class=\"img-fluid\" \r\n                             loading=\"lazy\">\r\n                        <div class=\"ukt-pv-intro-badge\">\r\n                            <i class=\"bi bi-shield-check\"></i>\r\n                            <span>100% Non-Invasive &bull; Remote Distance Mode</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- RIGHT COLUMN: INTRODUCTION CONTENT -->\r\n                <div class=\"col-lg-7\" id=\"about-app-text\">\r\n                    <div class=\"ukt-section-eyebrow mb-2\">\r\n                        <span></span>\r\n                        INTRODUCTION\r\n                        <span></span>\r\n                    </div>\r\n\r\n                    <h2 class=\"ukt-section-main-title mb-3\">\r\n                        Parivarthan<span> App</span>\r\n                    </h2>\r\n\r\n                    <div class=\"ukt-section-heading-design ms-0 mb-3 justify-content-start\">\r\n                        <span></span>\r\n                        <i class=\"bi bi-flower1\"></i>\r\n                        <span></span>\r\n                    </div>\r\n\r\n                    <p class=\"ukt-pv-lead\">\r\n                        Remote Positive Energy Healing & Spiritual Wellbeing\r\n                        \r\n                    </p>\r\n\r\n                    <p class=\"ukt-pv-text\">\r\n                        A Healer offers Positive Energy Healing remotely through distance mode, with the intention of promoting relaxation, balance, and overall wellbeing.<br>\r\n                        The practice is natural and non-invasive, focusing on helping the recipient feel more relaxed, release tension, and restore balance across the physical body, aura, and energy chakras.\r\n                    </p>\r\n\r\n                    <!-- 4 Dimension Pillars -->\r\n                    <div class=\"ukt-pv-pillar-grid\">\r\n                        <div class=\"ukt-pv-pillar-box\">\r\n                            <h3 class=\"ukt-pv-pillar-title\">\r\n                                <i class=\"bi bi-broadcast-pin\"></i>\r\n                                <span>Distance Mode Healing</span>\r\n                            </h3>\r\n                            <p class=\"ukt-pv-pillar-desc\">Positive energy channeled remotely to promote healing and vitality across any distance.</p>\r\n                        </div>\r\n\r\n                        <div class=\"ukt-pv-pillar-box\">\r\n                            <h3 class=\"ukt-pv-pillar-title\">\r\n                                <i class=\"bi bi-flower1\"></i>\r\n                                <span>Natural &amp; Non-Invasive</span>\r\n                            </h3>\r\n                            <p class=\"ukt-pv-pillar-desc\">Safe, gentle energetic alignment designed to nurture complete inner balance.</p>\r\n                        </div>\r\n\r\n                        <div class=\"ukt-pv-pillar-box\">\r\n                            <h3 class=\"ukt-pv-pillar-title\">\r\n                                <i class=\"bi bi-heart-pulse\"></i>\r\n                                <span>Release Tension &amp; Relax</span>\r\n                            </h3>\r\n                            <p class=\"ukt-pv-pillar-desc\">Helping the recipient release stress, unwind, and activate natural relaxation.</p>\r\n                        </div>\r\n\r\n                        <div class=\"ukt-pv-pillar-box\">\r\n                            <h3 class=\"ukt-pv-pillar-title\">\r\n                                <i class=\"bi bi-stars\"></i>\r\n                                <span>Body, Aura &amp; Chakras</span>\r\n                            </h3>\r\n                            <p class=\"ukt-pv-pillar-desc\">Harmonizing subtle energy centers across the physical body and energetic aura.</p>\r\n                        </div>\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         SECTION 2: EASY-TO-USE APP & HEALING CONCERNS\r\n    ========================================================== -->\r\n    <section id=\"easy-to-use-app\" class=\"py-5 ukt-pv-section ukt-pv-cream-bg\">\r\n        <div class=\"container py-lg-4\">\r\n\r\n            <!-- Section Header -->\r\n            <div class=\"ukt-section-header mb-5 text-center\">\r\n                <div class=\"ukt-section-eyebrow justify-content-center\">\r\n                    <span></span>\r\n                    SIMPLE &amp; CONVENIENT\r\n                    <span></span>\r\n                </div>\r\n                <h2 class=\"ukt-section-main-title\">\r\n                    Easy-to-Use <span>App</span>\r\n                </h2>\r\n                <div class=\"ukt-section-heading-design\">\r\n                    <span></span>\r\n                    <i class=\"bi bi-flower1\"></i>\r\n                    <span></span>\r\n                </div>\r\n                <p class=\"ukt-section-lead-text\">\r\n                    The app is simple and convenient to use. Sign up as a new user, verify your mobile number with an OTP, and get started.\r\n                </p>\r\n            </div>\r\n\r\n            <!-- 3-Step Process Flow -->\r\n            <div class=\"row g-4 mb-5 justify-content-center\">\r\n                <!-- Step 1 -->\r\n                <div class=\"col-lg-4 col-md-6\">\r\n                    <div class=\"ukt-pv-step-card\">\r\n                        <div class=\"ukt-pv-step-header\">\r\n                            <div class=\"ukt-pv-step-icon\">\r\n                                <i class=\"bi bi-phone-vibrate\"></i>\r\n                            </div>\r\n                            <span class=\"ukt-pv-step-num\">01</span>\r\n                        </div>\r\n                        <h3 class=\"ukt-pv-step-title\">Quick OTP Sign-Up</h3>\r\n                        <p class=\"ukt-pv-step-desc\">\r\n                            Sign up as a new user, verify your mobile number with an OTP, and get started instantly.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Step 2 -->\r\n                <div class=\"col-lg-4 col-md-6\">\r\n                    <div class=\"ukt-pv-step-card\">\r\n                        <div class=\"ukt-pv-step-header\">\r\n                            <div class=\"ukt-pv-step-icon\">\r\n                                <i class=\"bi bi-card-checklist\"></i>\r\n                            </div>\r\n                            <span class=\"ukt-pv-step-num\">02</span>\r\n                        </div>\r\n                        <h3 class=\"ukt-pv-step-title\">Submit Healing Request</h3>\r\n                        <p class=\"ukt-pv-step-desc\">\r\n                            Request healing for yourself or eligible immediate family members for specific health and life concerns.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Step 3 -->\r\n                <div class=\"col-lg-4 col-md-6\">\r\n                    <div class=\"ukt-pv-step-card\">\r\n                        <div class=\"ukt-pv-step-header\">\r\n                            <div class=\"ukt-pv-step-icon\">\r\n                                <i class=\"bi bi-chat-heart\"></i>\r\n                            </div>\r\n                            <span class=\"ukt-pv-step-num\">03</span>\r\n                        </div>\r\n                        <h3 class=\"ukt-pv-step-title\">Connect with Healer</h3>\r\n                        <p class=\"ukt-pv-step-desc\">\r\n                            Connect directly with dedicated healers through the in-app chat facility for guidance and healing support.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- Concerns Grid Header -->\r\n            <div class=\"text-center mb-4\">\r\n                <h3 class=\"ukt-section-main-title ukt-pv-sub-main-title\">\r\n                    Request Healing for <span>Yourself or Immediate Family</span>\r\n                </h3>\r\n                <p class=\"ukt-section-lead-text mt-2\">\r\n                    Users can request healing for themselves or eligible immediate family members for concerns related to:\r\n                </p>\r\n            </div>\r\n\r\n            <!-- 4 Concern Cards -->\r\n            <div class=\"row g-4 justify-content-center\">\r\n\r\n                <!-- Physical Wellbeing -->\r\n                <div class=\"col-lg-3 col-md-6\">\r\n                    <div class=\"ukt-pv-concern-card\">\r\n                        <div class=\"ukt-pv-concern-icon\">\r\n                            <i class=\"bi bi-heart-pulse-fill\"></i>\r\n                        </div>\r\n                        <h4 class=\"ukt-pv-concern-title\">Physical Wellbeing</h4>\r\n                        <p class=\"ukt-pv-concern-desc\">\r\n                            Support for physical comfort, restoring bodily balance, releasing fatigue, and strengthening natural vitality.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Mental and Emotional Wellbeing -->\r\n                <div class=\"col-lg-3 col-md-6\">\r\n                    <div class=\"ukt-pv-concern-card\">\r\n                        <div class=\"ukt-pv-concern-icon\">\r\n                            <i class=\"bi bi-emoji-smile-fill\"></i>\r\n                        </div>\r\n                        <h4 class=\"ukt-pv-concern-title\">Mental &amp; Emotional Wellbeing</h4>\r\n                        <p class=\"ukt-pv-concern-desc\">\r\n                            Calming mental strain, soothing emotional unrest, releasing anxiety, and restoring tranquility and positivity.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Financial Concerns -->\r\n                <div class=\"col-lg-3 col-md-6\">\r\n                    <div class=\"ukt-pv-concern-card\">\r\n                        <div class=\"ukt-pv-concern-icon\">\r\n                            <i class=\"bi bi-coin\"></i>\r\n                        </div>\r\n                        <h4 class=\"ukt-pv-concern-title\">Financial Concerns</h4>\r\n                        <p class=\"ukt-pv-concern-desc\">\r\n                            Dissolving subtle energetic blockages, promoting mental clarity, positive outlook, and confident decision making.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Relationship Concerns -->\r\n                <div class=\"col-lg-3 col-md-6\">\r\n                    <div class=\"ukt-pv-concern-card\">\r\n                        <div class=\"ukt-pv-concern-icon\">\r\n                            <i class=\"bi bi-people-fill\"></i>\r\n                        </div>\r\n                        <h4 class=\"ukt-pv-concern-title\">Relationship Concerns</h4>\r\n                        <p class=\"ukt-pv-concern-desc\">\r\n                            Harmonizing interpersonal connections, resolving emotional conflicts, and cultivating mutual understanding and peace.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n\r\n            <!-- Chat & Blood Relatives Highlight Callout -->\r\n            <div class=\"ukt-pv-callout-banner\">\r\n                <div class=\"ukt-pv-callout-icon\">\r\n                    <i class=\"bi bi-chat-dots-fill\"></i>\r\n                </div>\r\n                <div class=\"ukt-pv-callout-text\">\r\n                    <h4>Direct In-App Healer Chat &amp; Family Requests</h4>\r\n                    <p>\r\n                        Recipients can also connect directly with a Healer through the in-app chat facility. Users may submit healing requests on behalf of immediate blood relatives for their wellbeing.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         SECTION 3: LEARN, PRACTISE & GROW (RESOURCES)\r\n    ========================================================== -->\r\n    <section id=\"learn-practise-grow\" class=\"py-5 ukt-pv-section ukt-pv-dark-section\">\r\n        <div class=\"container py-lg-5\">\r\n\r\n            <!-- Section Header -->\r\n            <div class=\"ukt-section-header mb-5 text-center\">\r\n                <div class=\"ukt-section-eyebrow justify-content-center\">\r\n                    <span></span>\r\n                    LEARN &amp; GROW\r\n                    <span></span>\r\n                </div>\r\n                <h2 class=\"ukt-section-main-title\">\r\n                    Learn, Practise &amp; <span>Grow</span>\r\n                </h2>\r\n                <div class=\"ukt-section-heading-design\">\r\n                    <span></span>\r\n                    <i class=\"bi bi-flower1\"></i>\r\n                    <span></span>\r\n                </div>\r\n                <p class=\"ukt-section-lead-text\">\r\n                    The app provides access to a range of resources designed to support spiritual development and positive living, including:\r\n                </p>\r\n            </div>\r\n\r\n            <!-- 7 Resource Grid Cards -->\r\n            <div class=\"row g-4 justify-content-center\">\r\n\r\n                <!-- 1. Daily Inspirational Quotes -->\r\n                <div class=\"col-lg-3 col-md-6\">\r\n                    <div class=\"ukt-pv-resource-card\">\r\n                        <div class=\"ukt-pv-resource-icon\">\r\n                            <i class=\"bi bi-quote\"></i>\r\n                        </div>\r\n                        <h3 class=\"ukt-pv-resource-title\">Daily Inspirational Quotes</h3>\r\n                        <p class=\"ukt-pv-resource-desc\">\r\n                            Inspiring daily quotes and positive wisdom to start each morning with focus, mindfulness, and clarity.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- 2. Daily Routine Videos & Exercises -->\r\n                <div class=\"col-lg-3 col-md-6\">\r\n                    <div class=\"ukt-pv-resource-card\">\r\n                        <div class=\"ukt-pv-resource-icon\">\r\n                            <i class=\"bi bi-play-circle-fill\"></i>\r\n                        </div>\r\n                        <h3 class=\"ukt-pv-resource-title\">Daily Routine Videos &amp; Exercises</h3>\r\n                        <p class=\"ukt-pv-resource-desc\">\r\n                            Daily routine exercises and guided workout videos crafted to sustain physical fitness and energy flow.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- 3. Breathing Techniques & Practices -->\r\n                <div class=\"col-lg-3 col-md-6\">\r\n                    <div class=\"ukt-pv-resource-card\">\r\n                        <div class=\"ukt-pv-resource-icon\">\r\n                            <i class=\"bi bi-wind\"></i>\r\n                        </div>\r\n                        <h3 class=\"ukt-pv-resource-title\">Breathing Techniques &amp; Practices</h3>\r\n                        <p class=\"ukt-pv-resource-desc\">\r\n                            Simple and effective breathing practices designed to calm the nervous system and build inner peace.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- 4. Live Classes -->\r\n                <div class=\"col-lg-3 col-md-6\">\r\n                    <div class=\"ukt-pv-resource-card\">\r\n                        <div class=\"ukt-pv-resource-icon\">\r\n                            <i class=\"bi bi-camera-video-fill\"></i>\r\n                        </div>\r\n                        <h3 class=\"ukt-pv-resource-title\">Live Classes</h3>\r\n                        <p class=\"ukt-pv-resource-desc\">\r\n                            Interactive live spiritual sessions, masterclasses, and group practices conducted by experienced teachers.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- 5. Educational PDFs -->\r\n                <div class=\"col-lg-4 col-md-6\">\r\n                    <div class=\"ukt-pv-resource-card\">\r\n                        <div class=\"ukt-pv-resource-icon\">\r\n                            <i class=\"bi bi-file-earmark-pdf-fill\"></i>\r\n                        </div>\r\n                        <h3 class=\"ukt-pv-resource-title\">Educational PDFs</h3>\r\n                        <p class=\"ukt-pv-resource-desc\">\r\n                            Downloadable reading materials, educational handbooks, and spiritual guides for deeper learning.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- 6. Spiritual Growth Programmes -->\r\n                <div class=\"col-lg-4 col-md-6\">\r\n                    <div class=\"ukt-pv-resource-card\">\r\n                        <div class=\"ukt-pv-resource-icon\">\r\n                            <i class=\"bi bi-compass-fill\"></i>\r\n                        </div>\r\n                        <h3 class=\"ukt-pv-resource-title\">Spiritual Growth Programmes</h3>\r\n                        <p class=\"ukt-pv-resource-desc\">\r\n                            Structured pathways and programmes to expand spiritual awareness, consciousness, and self-mastery.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- 7. Remote Positive Energy Healing -->\r\n                <div class=\"col-lg-4 col-md-6\">\r\n                    <div class=\"ukt-pv-resource-card\">\r\n                        <div class=\"ukt-pv-resource-icon\">\r\n                            <i class=\"bi bi-heart-pulse-fill\"></i>\r\n                        </div>\r\n                        <h3 class=\"ukt-pv-resource-title\">Remote Positive Energy Healing</h3>\r\n                        <p class=\"ukt-pv-resource-desc\">\r\n                            Dedicated distance healing sessions facilitated by compassionate healers to restore body and energy balance.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         SECTION 4: FEATURED PROGRAMMES\r\n    ========================================================== -->\r\n    <section id=\"featured-programmes\" class=\"py-5 ukt-section-bg-white ukt-pv-section\">\r\n        <div class=\"container py-lg-5\">\r\n\r\n            <!-- Section Header -->\r\n            <div class=\"ukt-section-header mb-5 text-center\">\r\n                <div class=\"ukt-section-eyebrow justify-content-center\">\r\n                    <span></span>\r\n                    SIGNATURE INITIATIVES\r\n                    <span></span>\r\n                </div>\r\n                <h2 class=\"ukt-section-main-title\">\r\n                    Featured <span>Programmes</span>\r\n                </h2>\r\n                <div class=\"ukt-section-heading-design\">\r\n                    <span></span>\r\n                    <i class=\"bi bi-flower1\"></i>\r\n                    <span></span>\r\n                </div>\r\n                <p class=\"ukt-section-lead-text\">\r\n                    Explore guided transformational programmes designed to nurture positive habits, cultivate inner resilience, and awaken your higher potential.\r\n                </p>\r\n            </div>\r\n\r\n            <!-- 2 Grand Programme Cards -->\r\n            <div class=\"row g-4 justify-content-center align-items-stretch\">\r\n\r\n                <!-- Programme 1: 21-Day Upliftment Programme -->\r\n                <div class=\"col-lg-6\">\r\n                    <div class=\"ukt-pv-prog-card\">\r\n                        <div class=\"ukt-pv-prog-header\">\r\n                            <span class=\"ukt-pv-prog-badge\">\r\n                                <i class=\"bi bi-calendar2-check-fill\"></i> 21-Day Guided Journey\r\n                            </span>\r\n                            <h3 class=\"ukt-pv-prog-title\">\r\n                                21-Day Upliftment Programme\r\n                            </h3>\r\n                            <div class=\"ukt-pv-prog-meta\">\r\n                                <i class=\"bi bi-clock-history\"></i>\r\n                                <span>10–15 Minutes Daily &bull; Within 24 Hours</span>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <div class=\"ukt-pv-prog-body\">\r\n                            <p class=\"ukt-pv-prog-desc\">\r\n                                A guided 21-day programme conducted by different Healers