INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(278, 1, '2026-10-26 22:39:52', '2026-10-26 17:09:52', '<article>\r\n    <!-- =========================================================\r\n         CAREERS & OPPORTUNITIES HERO / BANNER SECTION\r\n         (Standardized 45px rhythm & single row hero actions)\r\n    ========================================================== -->\r\n    <section class=\"ukt-hero-showcase\">\r\n        <div class=\"ukt-hero-slide-layout\">\r\n            <div class=\"container-fluid\">\r\n                <div class=\"row g-0 align-items-stretch\">\r\n\r\n                    <!-- LEFT CONTENT AREA -->\r\n                    <div class=\"col-lg-5 d-flex align-items-center\">\r\n                        <div class=\"ukt-hero-copy-zone\">\r\n                            <div class=\"ukt-hero-left-decoration\"></div>\r\n\r\n                            <div class=\"ukt-hero-slide-kicker\">\r\n                                <i class=\"bi bi-briefcase-fill me-1 ukt-text-green\"></i> Universal\r\n                                Knowledge Trust &bull; Careers &amp; Service\r\n                            </div>\r\n\r\n                            <h1 class=\"ukt-hero-main-title\">\r\n                                <span>Careers &amp;</span>\r\n                                <span>Opportunities</span>\r\n                            </h1>\r\n\r\n                            <div class=\"ukt-hero-script-line\">\r\n                                Current Opportunities at Universal Knowledge Trust &reg;\r\n                            </div>\r\n\r\n                            <p class=\"ukt-hero-description\">\r\n                                Be a catalyst of positive transformation. Join Universal Knowledge Trust as a School\r\n                                Trainer to awaken young minds, or offer your time and effort as a Volunteer serving\r\n                                children, the environment, and all living beings.\r\n                            </p>\r\n\r\n                            <div class=\"ukt-hero-action-row\">\r\n                                <a href=\"#trainers\" class=\"ukt-hero-primary-action\">\r\n                                    <i class=\"bi bi-mortarboard-fill me-1\"></i> Trainer Openings\r\n                                </a>\r\n                                <a href=\"#volunteers\" class=\"ukt-hero-secondary-action\">\r\n                                    <i class=\"bi bi-heart-fill me-1 text-danger\"></i> Volunteer With Us\r\n                                </a>\r\n                            </div>\r\n\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- RIGHT IMAGE AREA -->\r\n                    <div class=\"col-lg-7\">\r\n                        <div class=\"ukt-hero-visual-zone\">\r\n                            <div class=\"ukt-hero-image-frame\">\r\n                                <figure class=\"ukt-hero-image-figure\">\r\n                                    <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/download-for-school-training-program-banner.png\"\r\n                                        alt=\"Universal Knowledge Trust Careers &amp; Opportunities - School Training and Community Volunteering\"\r\n                                        loading=\"eager\" class=\"ukt-hero-image-cover\">\r\n                                    <figcaption class=\"visually-hidden\">Universal Knowledge Trust Careers &amp;\r\n                                        Opportunities - School Training and Community Volunteering</figcaption>\r\n                                </figure>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         SECTION: CURRENT OPPORTUNITIES (Standardized 55px rhythm)\r\n    ========================================================== -->\r\n    <section id=\"opportunities\" class=\"ukt-section-gap py-0 ukt-careers-opportunities-section\">\r\n        <div class=\"container-fluid px-3 px-md-4\">\r\n            <div class=\"ukt-career-container\">\r\n\r\n                <!-- SECTION HEADER -->\r\n                <div class=\"ukt-section-header text-center mb-4\">\r\n                    <div class=\"ukt-section-eyebrow\">\r\n                        <span></span>\r\n                        JOIN OUR NOBLE MISSION\r\n                        <span></span>\r\n                    </div>\r\n                    <h2 class=\"ukt-section-main-title\">\r\n                        Current Opportunities at <span>Universal Knowledge Trust &reg;</span>\r\n                    </h2>\r\n                    <div class=\"ukt-section-heading-design\">\r\n                        <span></span>\r\n                        <i class=\"bi bi-flower1\"></i>\r\n                        <span></span>\r\n                    </div>\r\n                    <p class=\"text-muted mx-auto mb-0 ukt-career-lead-text\">\r\n                        We invite compassionate, dedicated individuals to enrich themselves and society through\r\n                        teaching, conscious youth mentorship, and selfless service.\r\n                    </p>\r\n                </div>\r\n\r\n                <!-- OPPORTUNITY 1: TRAINER FOR SCHOOLS -->\r\n                <div id=\"trainers\" class=\"ukt-career-card ukt-career-card-accent-green\">\r\n                    <div class=\"row g-4 align-items-center\">\r\n\r\n                        <div class=\"col-lg-7\">\r\n                            <!-- Badge Header -->\r\n                            <div class=\"ukt-career-badge-bar\">\r\n                                <span class=\"badge ukt-badge-mentorship\">\r\n                                    <i class=\"bi bi-mortarboard-fill me-1\"></i> Teaching &amp; Youth Mentorship\r\n                                </span>\r\n                                <span class=\"badge ukt-badge-part-time\">\r\n                                    Part-Time Role\r\n                                </span>\r\n                                <span class=\"badge ukt-badge-trainers\">\r\n                                    UKT Trainers\r\n                                </span>\r\n                            </div>\r\n\r\n                            <!-- Title -->\r\n                            <h3 class=\"fw-bold mb-3 ukt-career-item-title\">\r\n                                1. Trainer for schools:\r\n                            </h3>\r\n\r\n                            <!-- Verbatim Opening Paragraph -->\r\n                            <p class=\"lead fw-semibold mb-3 ukt-career-lead-text\">\r\n                                We Invite applications from candidates to become trainers and train school children.\r\n                                Training for selected candidates starts from the first week of December 2022.\r\n                            </p>\r\n\r\n                            <!-- Key Highlights Pills -->\r\n                            <div class=\"d-flex flex-wrap gap-2 mb-3\">\r\n                                <div class=\"ukt-career-pill\">\r\n                                    <i class=\"bi bi-calendar-check text-success fs-5\"></i>\r\n                                    <div>\r\n                                        <div class=\"ukt-career-pill-label\">\r\n                                            Training Starts</div>\r\n                                        <strong>First week of December 2022</strong>\r\n                                    </div>\r\n                                </div>\r\n                                <div class=\"ukt-career-pill\">\r\n                                    <i class=\"bi bi-clock-history text-primary fs-5\"></i>\r\n                                    <div>\r\n                                        <div class=\"ukt-career-pill-label\">\r\n                                            Program Structure</div>\r\n                                        <strong>15 Days (5 Onsite + 10 Online)</strong>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n\r\n                            <!-- Verbatim Job Profile Box -->\r\n                            <div class=\"ukt-job-profile-box\">\r\n                                <div class=\"d-flex align-items-center gap-2 mb-1\">\r\n                                    <i class=\"bi bi-person-workspace text-success\"></i>\r\n                                    <strong class=\"ukt-job-profile-label\">Job Profile:</strong>\r\n                                </div>\r\n                                <p class=\"mb-0 ukt-job-profile-text\">\r\n                                    Conduct training program for school children for 15 days which includes 5 days\r\n                                    onsite at school and 10 days online classes.\r\n                                </p>\r\n                            </div>\r\n\r\n                            <!-- Verbatim Requirements & Contact Instruction -->\r\n                            <p class=\"mb-4 ukt-career-requirements-text\">\r\n                                If you have any experience in teaching and want to be a part of UKT Trainers as a\r\n                                part time trainers then send your biodata to <strong>Hlr. Shammy Shiri</strong> via\r\n                                <a href=\"http://wa.me/9880043056\" target=\"_blank\" rel=\"noopener noreferrer\"\r\n                                    class=\"fw-bold text-success text-decoration-none\"><i class=\"bi bi-whatsapp\"></i>\r\n                                    whattsapp</a> and for more details call <a href=\"tel:9880043056\"\r\n                                    class=\"fw-bold text-decoration-none ukt-volunteer-pillar-title\"><i\r\n                                        class=\"bi bi-telephone-fill\"></i> 9880043056</a>.\r\n                            </p>\r\n\r\n                            <!-- Direct Action Buttons in a Single Row -->\r\n                            <div class=\"d-flex flex-wrap gap-2 pt-2\">\r\n                                <a href=\"http://wa.me/9880043056\" target=\"_blank\" rel=\"noopener noreferrer\"\r\n                                    class=\"btn fw-bold px-3 py-2 text-white ukt-btn-whatsapp-action\">\r\n                                    <i class=\"bi bi-whatsapp fs-5\"></i> Send Biodata via WhatsApp\r\n                                </a>\r\n                                <a href=\"tel:9880043056\" class=\"btn fw-bold px-3 py-2 text-white ukt-btn-call-action\">\r\n                                    <i class=\"bi bi-telephone-fill\"></i> Call 9880043056\r\n                                </a>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <!-- Visual Column -->\r\n                        <div class=\"col-lg-5\">\r\n                            <div class=\"p-3 rounded-4 ukt-career-visual-card\">\r\n                                <figure class=\"ukt-career-visual-figure\">\r\n                                    <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/training-programs-for-scool/training-programs-for-school-4.jpg\"\r\n                                        alt=\"Universal Knowledge Trust School Children Training Session\">\r\n                                    <figcaption class=\"visually-hidden\">Universal Knowledge Trust School Children\r\n                                        Training Session</figcaption>\r\n                                </figure>\r\n                                <div class=\"mt-3\">\r\n                                    <div class=\"d-flex align-items-center gap-2 mb-2\">\r\n                                        <span class=\"badge ukt-badge-impact\">Impact Spotlight</span>\r\n                                        <span class=\"text-muted small\">School Transformation</span>\r\n                                    </div>\r\n                                    <p class=\"mb-0 text-muted ukt-career-visual-desc\">\r\n                                        UKT School Training programs help children develop mental focus, emotional\r\n                                        equilibrium, values, and inner resilience through guided workshops and\r\n                                        interactive online sessions.\r\n                                    </p>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Clean Subtle Divider -->\r\n                <hr class=\"ukt-career-divider\">\r\n\r\n                <!-- OPPORTUNITY 2: VOLUNTEERS -->\r\n                <div id=\"volunteers\" class=\"ukt-career-card ukt-career-card-accent-gold\">\r\n                    <div class=\"row g-4 align-items-center\">\r\n\r\n                        <div class=\"col-lg-7\">\r\n                            <!-- Badge Header -->\r\n                            <div class=\"ukt-career-badge-bar\">\r\n                                <span class=\"badge ukt-badge-seva\">\r\n                                    <i class=\"bi bi-heart-fill me-1 text-danger\"></i> Selfless Service &bull; Seva\r\n                                </span>\r\n                                <span class=\"badge ukt-badge-donation\">\r\n                                    Time &amp; Effort Donation\r\n                                </span>\r\n                                <span class=\"badge ukt-badge-open-all\">\r\n                                    Open to All\r\n                                </span>\r\n                            </div>\r\n\r\n                            <!-- Title -->\r\n                            <h3 class=\"fw-bold mb-3 ukt-career-item-title\">\r\n                                2. Volunteers:\r\n                            </h3>\r\n\r\n                            <!-- Verbatim Opening Paragraph -->\r\n                            <p class=\"lead fw-semibold mb-3 ukt-career-lead-text\">\r\n                                We are always welcoming like minded individuals who have a wide open mindset to\r\n                                enrich themselves via time and effort donation and serving humanity, environment and\r\n                                all living beings. This will resolve most karmatic issues and lay the foundation for\r\n                                future events to unfold.\r\n                            </p>\r\n\r\n                            <!-- Verbatim Focus & Link -->\r\n                            <p class=\"mb-4 ukt-career-requirements-text\">\r\n                                We are big on training children and tree plantations as well as other activites in\r\n                                the link <a href=\"http://localhost/universal-knowledge-trust-wordpress/all-our-events\" target=\"_blank\"\r\n                                    rel=\"noopener noreferrer\" class=\"fw-bold text-decoration-none ukt-btn-events-action\"><i class=\"bi bi-box-arrow-up-right me-1\"></i> Our\r\n                                    events</a> Connect with us to further your life goals.\r\n                            </p>\r\n\r\n                            <!-- Volunteer Service Focus Areas -->\r\n                            <div class=\"row g-2 mb-4\">\r\n                                <div class=\"col-sm-6\">\r\n                                    <div class=\"ukt-volunteer-pillar-card\">\r\n                                        <div class=\"ukt-volunteer-icon ukt-volunteer-icon-green\">\r\n                                            <i class=\"bi bi-tree-fill\"></i>\r\n                                        </div>\r\n                                        <h4 class=\"fw-bold mb-1 ukt-volunteer-pillar-title\">Tree Plantations</h4>\r\n                                        <p class=\"mb-0 text-muted ukt-volunteer-pillar-desc\">\r\n                                            Project Green initiatives, sapling planting drives, and environmental\r\n                                            restoration.\r\n                                        </p>\r\n                                    </div>\r\n                                </div>\r\n                                <div class=\"col-sm-6\">\r\n                                    <div class=\"ukt-volunteer-pillar-card\">\r\n                                        <div class=\"ukt-volunteer-icon ukt-volunteer-icon-blue\">\r\n                                            <i class=\"bi bi-backpack-fill\"></i>\r\n                                        </div>\r\n                                        <h4 class=\"fw-bold mb-1 ukt-volunteer-pillar-title\">Training Children</h4>\r\n                                        <p class=\"mb-0 text-muted ukt-volunteer-pillar-desc\">\r\n                                            Supporting values education, student wellness, and school programs.\r\n                                        </p>\r\n                                    </div>\r\n                                </div>\r\n                                <div class=\"col-sm-6\">\r\n                                    <div class=\"ukt-volunteer-pillar-card\">\r\n                                        <div class=\"ukt-volunteer-icon ukt-volunteer-icon-gold\">\r\n                                            <i class=\"bi bi-cup-hot-fill\"></i>\r\n                                        </div>\r\n                                        <h4 class=\"fw-bold mb-1 ukt-volunteer-pillar-title\">Serving Humanity</h4>\r\n                                        <p class=\"mb-0 text-muted ukt-volunteer-pillar-desc\">\r\n                                            Food on Wall, community nourishment, and conscious service for living\r\n                                            beings.\r\n                                        </p>\r\n                                    </div>\r\n                                </div>\r\n                                <div class=\"col-sm-6\">\r\n                                    <div class=\"ukt-volunteer-pillar-card\">\r\n                                        <div class=\"ukt-volunteer-icon ukt-volunteer-icon-purple\">\r\n                                            <i class=\"bi bi-stars\"></i>\r\n                                        </div>\r\n                                        <h4 class=\"fw-bold mb-1 ukt-volunteer-pillar-title\">Karmic Enrichment</h4>\r\n                                        <p class=\"mb-0 text-muted ukt-volunteer-pillar-desc\">\r\n                                            Self-enrichment through selfless effort, resolving karmic barriers for\r\n                                            future growth.\r\n                                        </p>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n\r\n                            <!-- Direct Action Buttons in a Single Row -->\r\n                            <div class=\"d-flex flex-wrap gap-2\">\r\n                                <a href=\"http://localhost/universal-knowledge-trust-wordpress/all-our-events\" target=\"_blank\"\r\n                                    rel=\"noopener noreferrer\" class=\"btn fw-bold px-3 py-2 text-white ukt-btn-events-action\">\r\n                                    <i class=\"bi bi-calendar-event\"></i> Explore Our Events\r\n                                </a>\r\n                                <a href=\"http://wa.me/9880043056\" target=\"_blank\" rel=\"noopener noreferrer\"\r\n                                    class=\"btn fw-bold px-3 py-2 ukt-btn-whatsapp-outline\">\r\n                                    <i class=\"bi bi-whatsapp text-success\"></i> Connect via WhatsApp (9880043056)\r\n                                </a>\r\n                                <a href=\"http://localhost/universal-knowledge-trust-wordpress/contact\" class=\"btn fw-bold px-3 py-2 text-white ukt-btn-call-action\">\r\n                                    <i class=\"bi bi-geo-alt\"></i> Contact Us\r\n                                </a>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <!-- Visual Column -->\r\n                        <div class=\"col-lg-5\">\r\n                            <div class=\"p-3 rounded-4 ukt-career-visual-card\">\r\n                                <figure class=\"ukt-career-visual-figure\">\r\n                                    <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/nature-retreats-articles/nature-retreat-4.jpg\"\r\n                                        alt=\"Universal Knowledge Trust Community and Volunteering Circle\">\r\n                                    <figcaption class=\"visually-hidden\">Universal Knowledge Trust Community and\r\n                                        Volunteering Circle</figcaption>\r\n                                </figure>\r\n                                <div class=\"mt-3\">\r\n                                    <div class=\"d-flex align-items-center gap-2 mb-2\">\r\n                                        <span class=\"badge ukt-badge-seva-spotlight\">Seva Community</span>\r\n                                        <span class=\"text-muted small\">Nature &amp; Conscious Living</span>\r\n                                    </div>\r\n                                    <p class=\"mb-0 text-muted ukt-career-visual-desc\">\r\n                                        Join hands with like-minded seekers, healers, and nature advocates. Connect\r\n                                        with us through events and service projects to enrich yourself and elevate\r\n                                        collective awareness.\r\n                                    </p>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         CALL TO ACTION SECTION (Standardized 55px rhythm)\r\n    ========================================================== -->\r\n    <section class=\"ukt-cta-section ukt-section-gap ukt-careers-cta-section\">\r\n        <div class=\"container text-center\">\r\n            <span class=\"ukt-careers-cta-eyebrow\">STEP FORWARD &bull; CREATE MEANINGFUL IMPACT</span>\r\n            <h2 class=\"ukt-careers-cta-title\">\r\n                Connect With <span class=\"ukt-careers-cta-highlight\">Universal Knowledge Trust</span>\r\n            </h2>\r\n            <p class=\"ukt-careers-cta-desc\">\r\n                Whether applying as a School Trainer or offering time and effort as a dedicated Volunteer, take the\r\n                next step in your personal and spiritual journey with us.\r\n            </p>\r\n            <div class=\"d-flex flex-wrap justify-content-center gap-3\">\r\n                <a href=\"http://wa.me/9880043056\" target=\"_blank\" rel=\"noopener noreferrer\"\r\n                    class=\"ukt-hero-primary-action ukt-btn-cta-whatsapp\">\r\n                    <i class=\"bi bi-whatsapp me-1\"></i> WhatsApp: 9880043056\r\n                </a>\r\n                <a href=\"tel:9880043056\" class=\"ukt-hero-primary-action ukt-btn-cta-gold\">\r\n                    <i class=\"bi bi-telephone-fill me-1\"></i> Call 9880043056\r\n                </a>\r\n                <a href=\"http://localhost/universal-knowledge-trust-wordpress/our-events/\" target=\"_blank\" rel=\"noopener noreferrer\"\r\n                    class=\"ukt-hero-secondary-action ukt-btn-cta-outline\">\r\n                    <i class=\"bi bi-calendar-event me-1\"></i> View Our Events\r\n                </a>\r\n            </div>\r\n        </div>\r\n    </section>\r\n\r\n</article>', 'Careers', '', 'publish', 'closed', 'closed', '', 'careers', '', '', '2026-10-26 22:39:52', '2026-10-26 17:09:52', '', 0, 'http://localhost/universal-knowledge-trust-wordpress/?page_id=278', 0, 'page', '', 0),
(279, 1, '2026-10-26 22:39:52', '2026-10-26 17:09:52', '<article>\r\n    <!-- =========================================================\r\n         CAREERS & OPPORTUNITIES HERO / BANNER SECTION\r\n         (Standardized 45px rhythm & single row hero actions)\r\n    ========================================================== -->\r\n    <section class=\"ukt-hero-showcase\">\r\n        <div class=\"ukt-hero-slide-layout\">\r\n            <div class=\"container-fluid\">\r\n                <div class=\"row g-0 align-items-stretch\">\r\n\r\n                    <!-- LEFT CONTENT AREA -->\r\n                    <div class=\"col-lg-5 d-flex align-items-center\">\r\n                        <div class=\"ukt-hero-copy-zone\">\r\n                            <div class=\"ukt-hero-left-decoration\"></div>\r\n\r\n                            <div class=\"ukt-hero-slide-kicker\">\r\n                                <i class=\"bi bi-briefcase-fill me-1 ukt-text-green\"></i> Universal\r\n                                Knowledge Trust &bull; Careers &amp; Service\r\n                            </div>\r\n\r\n                            <h1 class=\"ukt-hero-main-title\">\r\n                                <span>Careers &amp;</span>\r\n                                <span>Opportunities</span>\r\n                            </h1>\r\n\r\n                            <div class=\"ukt-hero-script-line\">\r\n                                Current Opportunities at Universal Knowledge Trust &reg;\r\n                            </div>\r\n\r\n                            <p class=\"ukt-hero-description\">\r\n                                Be a catalyst of positive transformation. Join Universal Knowledge Trust as a School\r\n                                Trainer to awaken young minds, or offer your time and effort as a Volunteer serving\r\n                                children, the environment, and all living beings.\r\n                            </p>\r\n\r\n                            <div class=\"ukt-hero-action-row\">\r\n                                <a href=\"#trainers\" class=\"ukt-hero-primary-action\">\r\n                                    <i class=\"bi bi-mortarboard-fill me-1\"></i> Trainer Openings\r\n                                </a>\r\n                                <a href=\"#volunteers\" class=\"ukt-hero-secondary-action\">\r\n                                    <i class=\"bi bi-heart-fill me-1 text-danger\"></i> Volunteer With Us\r\n                                </a>\r\n                            </div>\r\n\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- RIGHT IMAGE AREA -->\r\n                    <div class=\"col-lg-7\">\r\n                        <div class=\"ukt-hero-visual-zone\">\r\n                            <div class=\"ukt-hero-image-frame\">\r\n                                <figure class=\"ukt-hero-image-figure\">\r\n                                    <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/download-for-school-training-program-banner.png\"\r\n                                        alt=\"Universal Knowledge Trust Careers &amp; Opportunities - School Training and Community Volunteering\"\r\n                                        loading=\"eager\" class=\"ukt-hero-image-cover\">\r\n                                    <figcaption class=\"visually-hidden\">Universal Knowledge Trust Careers &amp;\r\n                                        Opportunities - School Training and Community Volunteering</figcaption>\r\n                                </figure>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         SECTION: CURRENT OPPORTUNITIES (Standardized 55px rhythm)\r\n    ========================================================== -->\r\n    <section id=\"opportunities\" class=\"ukt-section-gap py-0 ukt-careers-opportunities-section\">\r\n        <div class=\"container-fluid px-3 px-md-4\">\r\n            <div class=\"ukt-career-container\">\r\n\r\n                <!-- SECTION HEADER -->\r\n                <div class=\"ukt-section-header text-center mb-4\">\r\n                    <div class=\"ukt-section-eyebrow\">\r\n                        <span></span>\r\n                        JOIN OUR NOBLE MISSION\r\n                        <span></span>\r\n                    </div>\r\n                    <h2 class=\"ukt-section-main-title\">\r\n                        Current Opportunities at <span>Universal Knowledge Trust &reg;</span>\r\n                    </h2>\r\n                    <div class=\"ukt-section-heading-design\">\r\n                        <span></span>\r\n                        <i class=\"bi bi-flower1\"></i>\r\n                        <span></span>\r\n                    </div>\r\n                    <p class=\"text-muted mx-auto mb-0 ukt-career-lead-text\">\r\n                        We invite compassionate, dedicated individuals to enrich themselves and society through\r\n                        teaching, conscious youth mentorship, and selfless service.\r\n                    </p>\r\n                </div>\r\n\r\n                <!-- OPPORTUNITY 1: TRAINER FOR SCHOOLS -->\r\n                <div id=\"trainers\" class=\"ukt-career-card ukt-career-card-accent-green\">\r\n                    <div class=\"row g-4 align-items-center\">\r\n\r\n                        <div class=\"col-lg-7\">\r\n                            <!-- Badge Header -->\r\n                            <div class=\"ukt-career-badge-bar\">\r\n                                <span class=\"badge ukt-badge-mentorship\">\r\n                                    <i class=\"bi bi-mortarboard-fill me-1\"></i> Teaching &amp; Youth Mentorship\r\n                                </span>\r\n                                <span class=\"badge ukt-badge-part-time\">\r\n                                    Part-Time Role\r\n                                </span>\r\n                                <span class=\"badge ukt-badge-trainers\">\r\n                                    UKT Trainers\r\n                                </span>\r\n                            </div>\r\n\r\n                            <!-- Title -->\r\n                            <h3 class=\"fw-bold mb-3 ukt-career-item-title\">\r\n                                1. Trainer for schools:\r\n                            </h3>\r\n\r\n                            <!-- Verbatim Opening Paragraph -->\r\n                            <p class=\"lead fw-semibold mb-3 ukt-career-lead-text\">\r\n                                We Invite applications from candidates to become trainers and train school children.\r\n                                Training for selected candidates starts from the first week of December 2022.\r\n                            </p>\r\n\r\n                            <!-- Key Highlights Pills -->\r\n                            <div class=\"d-flex flex-wrap gap-2 mb-3\">\r\n                                <div class=\"ukt-career-pill\">\r\n                                    <i class=\"bi bi-calendar-check text-success fs-5\"></i>\r\n                                    <div>\r\n                                        <div class=\"ukt-career-pill-label\">\r\n                                            Training Starts</div>\r\n                                        <strong>First week of December 2022</strong>\r\n                                    </div>\r\n                                </div>\r\n                                <div class=\"ukt-career-pill\">\r\n                                    <i class=\"bi bi-clock-history text-primary fs-5\"></i>\r\n                                    <div>\r\n                                        <div class=\"ukt-career-pill-label\">\r\n                                            Program Structure</div>\r\n                                        <strong>15 Days (5 Onsite + 10 Online)</strong>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n\r\n                            <!-- Verbatim Job Profile Box -->\r\n                            <div class=\"ukt-job-profile-box\">\r\n                                <div class=\"d-flex align-items-center gap-2 mb-1\">\r\n                                    <i class=\"bi bi-person-workspace text-success\"></i>\r\n                                    <strong class=\"ukt-job-profile-label\">Job Profile:</strong>\r\n                                </div>\r\n                                <p class=\"mb-0 ukt-job-profile-text\">\r\n                                    Conduct training program for school children for 15 days which includes 5 days\r\n                                    onsite at school and 10 days online classes.\r\n                                </p>\r\n                            </div>\r\n\r\n                            <!-- Verbatim Requirements & Contact Instruction -->\r\n                            <p class=\"mb-4 ukt-career-requirements-text\">\r\n                                If you have any experience in teaching and want to be a part of UKT Trainers as a\r\n                                part time trainers then send your biodata to <strong>Hlr. Shammy Shiri</strong> via\r\n                                <a href=\"http://wa.me/9880043056\" target=\"_blank\" rel=\"noopener noreferrer\"\r\n                                    class=\"fw-bold text-success text-decoration-none\"><i class=\"bi bi-whatsapp\"></i>\r\n                                    whattsapp</a> and for more details call <a href=\"tel:9880043056\"\r\n                                    class=\"fw-bold text-decoration-none ukt-volunteer-pillar-title\"><i\r\n                                        class=\"bi bi-telephone-fill\"></i> 9880043056</a>.\r\n                            </p>\r\n\r\n                            <!-- Direct Action Buttons in a Single Row -->\r\n                            <div class=\"d-flex flex-wrap gap-2 pt-2\">\r\n                                <a href=\"http://wa.me/9880043056\" target=\"_blank\" rel=\"noopener noreferrer\"\r\n                                    class=\"btn fw-bold px-3 py-2 text-white ukt-btn-whatsapp-action\">\r\n                                    <i class=\"bi bi-whatsapp fs-5\"></i> Send Biodata via WhatsApp\r\n                                </a>\r\n                                <a href=\"tel:9880043056\" class=\"btn fw-bold px-3 py-2 text-white ukt-btn-call-action\">\r\n                                    <i class=\"bi bi-telephone-fill\"></i> Call 9880043056\r\n                                </a>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <!-- Visual Column -->\r\n                        <div class=\"col-lg-5\">\r\n                            <div class=\"p-3 rounded-4 ukt-career-visual-card\">\r\n                                <figure class=\"ukt-career-visual-figure\">\r\n                                    <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/training-programs-for-scool/training-programs-for-school-4.jpg\"\r\n                                        alt=\"Universal Knowledge Trust School Children Training Session\">\r\n                                    <figcaption class=\"visually-hidden\">Universal Knowledge Trust School Children\r\n                                        Training Session</figcaption>\r\n                                </figure>\r\n                                <div class=\"mt-3\">\r\n                                    <div class=\"d-flex align-items-center gap-2 mb-2\">\r\n                                        <span class=\"badge ukt-badge-impact\">Impact Spotlight</span>\r\n                                        <span class=\"text-muted small\">School Transformation</span>\r\n                                    </div>\r\n                                    <p class=\"mb-0 text-muted ukt-career-visual-desc\">\r\n                                        UKT School Training programs help children develop mental focus, emotional\r\n                                        equilibrium, values, and inner resilience through guided workshops and\r\n                                        interactive online sessions.\r\n                                    </p>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Clean Subtle Divider -->\r\n                <hr class=\"ukt-career-divider\">\r\n\r\n                <!-- OPPORTUNITY 2: VOLUNTEERS -->\r\n                <div id=\"volunteers\" class=\"ukt-career-card ukt-career-card-accent-gold\">\r\n                    <div class=\"row g-4 align-items-center\">\r\n\r\n                        <div class=\"col-lg-7\">\r\n                            <!-- Badge Header -->\r\n                            <div class=\"ukt-career-badge-bar\">\r\n                                <span class=\"badge ukt-badge-seva\">\r\n                                    <i class=\"bi bi-heart-fill me-1 text-danger\"></i> Selfless Service &bull; Seva\r\n                                </span>\r\n                                <span class=\"badge ukt-badge-donation\">\r\n                                    Time &amp; Effort Donation\r\n                                </span>\r\n                                <span class=\"badge ukt-badge-open-all\">\r\n                                    Open to All\r\n                                </span>\r\n                            </div>\r\n\r\n                            <!-- Title -->\r\n                            <h3 class=\"fw-bold mb-3 ukt-career-item-title\">\r\n                                2. Volunteers:\r\n                            </h3>\r\n\r\n                            <!-- Verbatim Opening Paragraph -->\r\n                            <p class=\"lead fw-semibold mb-3 ukt-career-lead-text\">\r\n                                We are always welcoming like minded individuals who have a wide open mindset to\r\n                                enrich themselves via time and effort donation and serving humanity, environment and\r\n                                all living beings. This will resolve most karmatic issues and lay the foundation for\r\n                                future events to unfold.\r\n                            </p>\r\n\r\n                            <!-- Verbatim Focus & Link -->\r\n                            <p class=\"mb-4 ukt-career-requirements-text\">\r\n                                We are big on training children and tree plantations as well as other activites in\r\n                                the link <a href=\"http://localhost/universal-knowledge-trust-wordpress/all-our-events\" target=\"_blank\"\r\n                                    rel=\"noopener noreferrer\" class=\"fw-bold text-decoration-none ukt-btn-events-action\"><i class=\"bi bi-box-arrow-up-right me-1\"></i> Our\r\n                                    events</a> Connect with us to further your life goals.\r\n                            </p>\r\n\r\n                            <!-- Volunteer Service Focus Areas -->\r\n                            <div class=\"row g-2 mb-4\">\r\n                                <div class=\"col-sm-6\">\r\n                                    <div class=\"ukt-volunteer-pillar-card\">\r\n                                        <div class=\"ukt-volunteer-icon ukt-volunteer-icon-green\">\r\n                                            <i class=\"bi bi-tree-fill\"></i>\r\n                                        </div>\r\n                                        <h4 class=\"fw-bold mb-1 ukt-volunteer-pillar-title\">Tree Plantations</h4>\r\n                                        <p class=\"mb-0 text-muted ukt-volunteer-pillar-desc\">\r\n                                            Project Green initiatives, sapling planting drives, and environmental\r\n                                            restoration.\r\n                                        </p>\r\n                                    </div>\r\n                                </div>\r\n                                <div class=\"col-sm-6\">\r\n                                    <div class=\"ukt-volunteer-pillar-card\">\r\n                                        <div class=\"ukt-volunteer-icon ukt-volunteer-icon-blue\">\r\n                                            <i class=\"bi bi-backpack-fill\"></i>\r\n                                        </div>\r\n                                        <h4 class=\"fw-bold mb-1 ukt-volunteer-pillar-title\">Training Children</h4>\r\n                                        <p class=\"mb-0 text-muted ukt-volunteer-pillar-desc\">\r\n                                            Supporting values education, student wellness, and school programs.\r\n                                        </p>\r\n                                    </div>\r\n                                </div>\r\n                                <div class=\"col-sm-6\">\r\n                                    <div class=\"ukt-volunteer-pillar-card\">\r\n                                        <div class=\"ukt-volunteer-icon ukt-volunteer-icon-gold\">\r\n                                            <i class=\"bi bi-cup-hot-fill\"></i>\r\n                                        </div>\r\n                                        <h4 class=\"fw-bold mb-1 ukt-volunteer-pillar-title\">Serving Humanity</h4>\r\n                                        <p class=\"mb-0 text-muted ukt-volunteer-pillar-desc\">\r\n                                            Food on Wall, community nourishment, and conscious service for living\r\n                                            beings.\r\n                                        </p>\r\n                                    </div>\r\n                                </div>\r\n                                <div class=\"col-sm-6\">\r\n                                    <div class=\"ukt-volunteer-pillar-card\">\r\n                                        <div class=\"ukt-volunteer-icon ukt-volunteer-icon-purple\">\r\n                                            <i class=\"bi bi-stars\"></i>\r\n                                        </div>\r\n                                        <h4 class=\"fw-bold mb-1 ukt-volunteer-pillar-title\">Karmic Enrichment</h4>\r\n                                        <p class=\"mb-0 text-muted ukt-volunteer-pillar-desc\">\r\n                                            Self-enrichment through selfless effort, resolving karmic barriers for\r\n                                            future growth.\r\n                                        </p>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n\r\n                            <!-- Direct Action Buttons in a Single Row -->\r\n                            <div class=\"d-flex flex-wrap gap-2\">\r\n                                <a href=\"http://localhost/universal-knowledge-trust-wordpress/all-our-events\" target=\"_blank\"\r\n                                    rel=\"noopener noreferrer\" class=\"btn fw-bold px-3 py-2 text-white ukt-btn-events-action\">\r\n                                    <i class=\"bi bi-calendar-event\"></i> Explore Our Events\r\n                                </a>\r\n                                <a href=\"http://wa.me/9880043056\" target=\"_blank\" rel=\"noopener noreferrer\"\r\n                                    class=\"btn fw-bold px-3 py-2 ukt-btn-whatsapp-outline\">\r\n                                    <i class=\"bi bi-whatsapp text-success\"></i> Connect via WhatsApp (9880043056)\r\n                                </a>\r\n                                <a href=\"http://localhost/universal-knowledge-trust-wordpress/contact\" class=\"btn fw-bold px-3 py-2 text-white ukt-btn-call-action\">\r\n                                    <i class=\"bi bi-geo-alt\"></i> Contact Us\r\n                                </a>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <!-- Visual Column -->\r\n                        <div class=\"col-lg-5\">\r\n                            <div class=\"p-3 rounded-4 ukt-career-visual-card\">\r\n                                <figure class=\"ukt-career-visual-figure\">\r\n                                    <img src=\"http://localhost/universal-knowledge-trust-wordpress/wp-content/themes/custom-child-theme/assets/images/nature-retreats-articles/nature-retreat-4.jpg\"\r\n                                        alt=\"Universal Knowledge Trust Community and Volunteering Circle\">\r\n                                    <figcaption class=\"visually-hidden\">Universal Knowledge Trust Community and\r\n                                        Volunteering Circle</figcaption>\r\n                                </figure>\r\n                                <div class=\"mt-3\">\r\n                                    <div class=\"d-flex align-items-center gap-2 mb-2\">\r\n                                        <span class=\"badge ukt-badge-seva-spotlight\">Seva Community</span>\r\n                                        <span class=\"text-muted small\">Nature &amp; Conscious Living</span>\r\n                                    </div>\r\n                                    <p class=\"mb-0 text-muted ukt-career-visual-desc\">\r\n                                        Join hands with like-minded seekers, healers, and nature advocates. Connect\r\n                                        with us through events and service projects to enrich yourself and elevate\r\n                                        collective awareness.\r\n                                    </p>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n        </div>\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         CALL TO ACTION SECTION (Standardized 55px rhythm)\r\n    ========================================================== -->\r\n    <section class=\"ukt-cta-section ukt-section-gap ukt-careers-cta-section\">\r\n        <div class=\"container text-center\">\r\n            <span class=\"ukt-careers-cta-eyebrow\">STEP FORWARD &bull; CREATE MEANINGFUL IMPACT</span>\r\n            <h2 class=\"ukt-careers-cta-title\">\r\n                Connect With <span class=\"ukt-careers-cta-highlight\">Universal Knowledge Trust</span>\r\n            </h2>\r\n            <p class=\"ukt-careers-cta-desc\">\r\n                Whether applying as a School Trainer or offering time and effort as a dedicated Volunteer, take the\r\n                next step in your personal and spiritual journey with us.\r\n            </p>\r\n            <div class=\"d-flex flex-wrap justify-content-center gap-3\">\r\n                <a href=\"http://wa.me/9880043056\" target=\"_blank\" rel=\"noopener noreferrer\"\r\n                    class=\"ukt-hero-primary-action ukt-btn-cta-whatsapp\">\r\n                    <i class=\"bi bi-whatsapp me-1\"></i> WhatsApp: 9880043056\r\n                </a>\r\n                <a href=\"tel:9880043056\" class=\"ukt-hero-primary-action ukt-btn-cta-gold\">\r\n                    <i class=\"bi bi-telephone-fill me-1\"></i> Call 9880043056\r\n                </a>\r\n                <a href=\"http://localhost/universal-knowledge-trust-wordpress/our-events/\" target=\"_blank\" rel=\"noopener noreferrer\"\r\n                    class=\"ukt-hero-secondary-action ukt-btn-cta-outline\">\r\n                    <i class=\"bi bi-calendar-event me-1\"></i> View Our Events\r\n                </a>\r\n            </div>\r\n        </div>\r\n    </section>\r\n\r\n</article>', 'Careers', '', 'inherit', 'closed', 'closed', '', '278-revision-v1', '', '', '2026-10-26 22:39:52', '2026-10-26 17:09:52', '', 278, 'http://localhost/universal-knowledge-trust-wordpress/?p=279', 0, 'revision', '', 0),
