(375, 1, '2026-10-26 23:24:25', '2026-10-26 17:54:25', '{\n    \"custom_css[custom-child-theme]\": {\n        \"value\": \"/* Display multiple images in a row inside WordPress post content */\\n.single-post .entry-content figure.wp-block-image,\\n.single-post .entry-content .wp-block-gallery,\\n.single-post .entry-content .wp-block-image {\\n    max-width: 100%;\\n}\\n\\n/* Arrange consecutive standalone images horizontally */\\n.single-post .entry-content p:has(> img) {\\n    display: flex;\\n    flex-wrap: wrap;\\n    align-items: flex-start;\\n    gap: 12px;\\n}\\n\\n.single-post .entry-content p:has(> img) img {\\n    width: auto;\\n    max-width: 100%;\\n    height: auto;\\n    object-fit: contain;\\n}\\n\\n/* Responsive layout for mobile */\\n@media (max-width: 600px) {\\n    .single-post .entry-content p:has(> img) img {\\n        max-width: 100%;\\n    }\\n}\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-10-26 17:54:25\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', '77c59ed9-ae00-4462-8a73-4804671ea289', '', '', '2026-10-26 23:24:25', '2026-10-26 17:54:25', '', 0, 'http://localhost/universal-knowledge-trust-wordpress/77c59ed9-ae00-4462-8a73-4804671ea289/', 0, 'customize_changeset', '', 0),
(376, 1, '2026-10-26 23:24:25', '2026-10-26 17:54:25', '/* Display multiple images in a row inside WordPress post content */\n.single-post .entry-content figure.wp-block-image,\n.single-post .entry-content .wp-block-gallery,\n.single-post .entry-content .wp-block-image {\n    max-width: 100%;\n}\n\n/* Arrange consecutive standalone images horizontally */\n.single-post .entry-content p:has(> img) {\n    display: flex;\n    flex-wrap: wrap;\n    align-items: flex-start;\n    gap: 12px;\n}\n\n.single-post .entry-content p:has(> img) img {\n    width: auto;\n    max-width: 100%;\n    height: auto;\n    object-fit: contain;\n}\n\n/* Responsive layout for mobile */\n@media (max-width: 600px) {\n    .single-post .entry-content p:has(> img) img {\n        max-width: 100%;\n    }\n}', 'custom-child-theme', '', 'inherit', 'closed', 'closed', '', '367-revision-v1', '', '', '2026-10-26 23:24:25', '2026-10-26 17:54:25', '', 367, 'http://localhost/universal-knowledge-trust-wordpress/?p=376', 0, 'revision', '', 0),
(377, 1, '2026-10-26 23:26:42', '2026-10-26 17:56:42', '{\n    \"custom_css[custom-child-theme]\": {\n        \"value\": \"\\n/* Arrange multiple images inside WordPress post content in a row */\\n.single-post .entry-content p:has(> img) {\\n    display: flex !important;\\n    flex-direction: row !important;\\n    flex-wrap: wrap !important;\\n    align-items: flex-start;\\n    gap: 12px;\\n}\\n\\n/* Remove WordPress alignment spacing */\\n.single-post .entry-content p:has(> img) > img {\\n    display: block !important;\\n    float: none !important;\\n    margin: 0 !important;\\n    width: calc(33.333% - 8px) !important;\\n    max-width: calc(33.333% - 8px) !important;\\n    height: auto !important;\\n    object-fit: contain;\\n}\\n\\n/* Responsive layout */\\n@media (max-width: 768px) {\\n    .single-post .entry-content p:has(> img) > img {\\n        width: calc(50% - 6px) !important;\\n        max-width: calc(50% - 6px) !important;\\n    }\\n}\\n\\n@media (max-width: 480px) {\\n    .single-post .entry-content p:has(> img) > img {\\n        width: 100% !important;\\n        max-width: 100% !important;\\n    }\\n}\\n\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-10-26 17:56:42\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', '4c908286-f321-4995-aa0a-9a62232ef8a2', '', '', '2026-10-26 23:26:42', '2026-10-26 17:56:42', '', 0, 'http://localhost/universal-knowledge-trust-wordpress/4c908286-f321-4995-aa0a-9a62232ef8a2/', 0, 'customize_changeset', '', 0),
(378, 1, '2026-10-26 23:26:42', '2026-10-26 17:56:42', '\n/* Arrange multiple images inside WordPress post content in a row */\n.single-post .entry-content p:has(> img) {\n    display: flex !important;\n    flex-direction: row !important;\n    flex-wrap: wrap !important;\n    align-items: flex-start;\n    gap: 12px;\n}\n\n/* Remove WordPress alignment spacing */\n.single-post .entry-content p:has(> img) > img {\n    display: block !important;\n    float: none !important;\n    margin: 0 !important;\n    width: calc(33.333% - 8px) !important;\n    max-width: calc(33.333% - 8px) !important;\n    height: auto !important;\n    object-fit: contain;\n}\n\n/* Responsive layout */\n@media (max-width: 768px) {\n    .single-post .entry-content p:has(> img) > img {\n        width: calc(50% - 6px) !important;\n        max-width: calc(50% - 6px) !important;\n    }\n}\n\n@media (max-width: 480px) {\n    .single-post .entry-content p:has(> img) > img {\n        width: 100% !important;\n        max-width: 100% !important;\n    }\n}\n', 'custom-child-theme', '', 'inherit', 'closed', 'closed', '', '367-revision-v1', '', '', '2026-10-26 23:26:42', '2026-10-26 17:56:42', '', 367, 'http://localhost/universal-knowledge-trust-wordpress/?p=378', 0, 'revision', '', 0),
